window.QUESTION_BANK = {"title":"遙控無人機專業操作證學科測驗題庫","meta":{"sourceFile":"專業操作證學科測驗題庫(1140528更新)_3833_102559.docx","updatedAt":"114.5.28","totalQuestions":588,"extractedAt":"2026-04-09 12:14:05"},"chapters":[{"id":"chapter-01","name":"第一章民用航空法及相關法規","shortName":"民用航空法及相關法規","questions":[{"id":"chapter-01-001","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機如為不法份子作為犯罪工具或因不當操作而致失控墜落者，可能導致何種後果？","answer":"D","options":[{"key":"A","text":"造成他人生命財產之損失。"},{"key":"B","text":"危害公共利益。"},{"key":"C","text":"影響飛航安全。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-002","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"市面上遙控無人機類型繁多，為保障操作安全，操作人於購買時應留意產品何項資訊？","answer":"D","options":[{"key":"A","text":"使用限制。"},{"key":"B","text":"操作性能。"},{"key":"C","text":"保固範圍。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-003","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之註冊、針對操作人員進行教育宣導及操作範圍警示之規定，係為達到哪個目的？","answer":"C","options":[{"key":"A","text":"刁難操作人員。"},{"key":"B","text":"打擊遙控無人機市場。"},{"key":"C","text":"安全使用。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-004","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作證考取目的係為確保操作人於哪個階段能熟悉相關航空知識與管理規範，並具備一定操作熟練度及緊急處置能力？","answer":"A","options":[{"key":"A","text":"操作前及操作時。"},{"key":"B","text":"操作前及操作後。"},{"key":"C","text":"操作前。"},{"key":"D","text":"操作後。"}]},{"id":"chapter-01-005","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"外國人領有外國政府對於所持有遙控無人機之註冊、操作證及檢驗合格等證明文件者，必須向哪個單位申請認可後，於遵守我國相關法令下從事遙控無人機活動？","answer":"C","options":[{"key":"A","text":"外交部。"},{"key":"B","text":"駐外單位。"},{"key":"C","text":"民航局。"},{"key":"D","text":"科技部。"}]},{"id":"chapter-01-006","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人僅透過遙控無人機即時傳輸圖像功能，是否即足以監控鏡頭外之周遭狀況？","answer":"A","options":[{"key":"A","text":"否。"},{"key":"B","text":"是。"},{"key":"C","text":"視傳輸圖像清晰度而定。"},{"key":"D","text":"視天氣狀況而定。"}]},{"id":"chapter-01-007","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人不得利用遙控無人機從事哪種行為？","answer":"B","options":[{"key":"A","text":"合法行為。"},{"key":"B","text":"非法行為。"},{"key":"C","text":"適法行為。"},{"key":"D","text":"法定行為。"}]},{"id":"chapter-01-008","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人不得無故利用遙控無人機對他人進行何種行為？","answer":"D","options":[{"key":"A","text":"攝錄非公開活動。"},{"key":"B","text":"竊聽私下談話。"},{"key":"C","text":"窺視身體隱私部位。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-009","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人未經同意，不得以遙控無人機對他人進行何種行為？","answer":"D","options":[{"key":"A","text":"錄音。"},{"key":"B","text":"照相、錄影。"},{"key":"C","text":"電磁紀錄竊錄。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-010","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人不得無故利用遙控無人機於哪個場所進行飛航活動？","answer":"D","options":[{"key":"A","text":"私人庭院。"},{"key":"B","text":"學校教室。"},{"key":"C","text":"辦公室場所。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-011","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機於空中進行飛航活動時，易伴隨較高之何種風險？","answer":"C","options":[{"key":"A","text":"文化風險。"},{"key":"B","text":"健康風險。"},{"key":"C","text":"社會風險。"},{"key":"D","text":"貿易風險。"}]},{"id":"chapter-01-012","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"對違反規範之遙控無人機操作人及所有人所為之處罰，係欲達到哪個目的？","answer":"D","options":[{"key":"A","text":"維持社會秩序。"},{"key":"B","text":"增進公共利益。"},{"key":"C","text":"維護公共安全。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-013","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"針對違反規範之遙控無人機操作人及所有人所處以罰鍰額度，係衡量何種因素而定？","answer":"A","options":[{"key":"A","text":"公眾利益及安全財產危害程度。"},{"key":"B","text":"政府稅收及國家經濟指數。"},{"key":"C","text":"國力強弱及世界局勢。"},{"key":"D","text":"教育程度及人民素質等。"}]},{"id":"chapter-01-014","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人於遵守相關規範下從事屬休閒娛樂性質之遙控無人機活動，其活動風險以何種管理方式為主？","answer":"B","options":[{"key":"A","text":"財政管理。"},{"key":"B","text":"自我管理。"},{"key":"C","text":"衛生管理。"},{"key":"D","text":"健康管理。"}]},{"id":"chapter-01-015","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"為法人從事業務之遙控無人機操作人，依法須強制加入何種保險？","answer":"B","options":[{"key":"A","text":"積水險。"},{"key":"B","text":"責任險。"},{"key":"C","text":"地震險。"},{"key":"D","text":"颱風險。"}]},{"id":"chapter-01-016","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機定義為何？","answer":"D","options":[{"key":"A","text":"自遙控設備以信號鏈路進行飛航控制之無人航空器。"},{"key":"B","text":"自遙控設備以自動駕駛操作之無人航空器。"},{"key":"C","text":"其他經民航局公告之無人航空器。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-017","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某遙控無人機操作人欲代地方農會執行農藥噴灑作業，以下敘述何者正確？","answer":"A","options":[{"key":"A","text":"該操作人須通過學、術科測驗。"},{"key":"B","text":"該操作人不須通過術科測驗。"},{"key":"C","text":"執行農藥噴灑作業前不需經申請核准。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-018","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"於何處進行遙控無人機飛航活動適用民用航空法之「遙控無人機」相關規定？","answer":"B","options":[{"key":"A","text":"建築物內密閉空間。"},{"key":"B","text":"建築物外開放空間。"},{"key":"C","text":"任何空間。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-01-019","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機活動期間，其所有人或操作人應負責任為何？","answer":"D","options":[{"key":"A","text":"使用安全之責。"},{"key":"B","text":"風險管理之責。"},{"key":"C","text":"法規遵循之責。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-020","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關遙控無人機飛航活動，下列敘述何者正確？","answer":"A","options":[{"key":"A","text":"未經許可不得飛航於禁航區。"},{"key":"B","text":"可任意飛航於限航區。"},{"key":"C","text":"航空站四周之一定距離範圍內飛航無相關規定。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-021","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"航空站或飛行場四周之一定距離範圍係由哪個機關進行公告？","answer":"A","options":[{"key":"A","text":"民航局。"},{"key":"B","text":"衛福部。"},{"key":"C","text":"內政部。"},{"key":"D","text":"文化部。"}]},{"id":"chapter-01-022","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"直轄市、縣（市）政府依民航法第99條之13第2項所規範之區域內，得依公益及安全需要，進行哪些項目之公告？","answer":"D","options":[{"key":"A","text":"遙控無人機活動區域。"},{"key":"B","text":"遙控無人機活動時間。"},{"key":"C","text":"其他管理事項。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-023","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"中央主管機關認有禁止或限制遙控無人機飛航活動需求者，得提請所在地哪個機關進行公告？","answer":"B","options":[{"key":"A","text":"鄉鎮區公所。"},{"key":"B","text":"直轄市、縣（市）政府。"},{"key":"C","text":"地方派出所。"},{"key":"D","text":"地方農會。"}]},{"id":"chapter-01-024","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人因執行業務需於禁、限航區及航空站或飛行場四周一定距離範圍內從事遙控無人機飛航活動者，應申請何者會商目的事業主管機關同意後，始得為之？","answer":"C","options":[{"key":"A","text":"鄉鎮區公所。"},{"key":"B","text":"衛福部。"},{"key":"C","text":"民航局。"},{"key":"D","text":"科技部。"}]},{"id":"chapter-01-025","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人因執行業務需於直轄市、縣（市）政府所公告之遙控無人機活動區域、時間及其他管理事項外從事飛航活動者，應申請何者會商相關中央主管機關同意後，始得為之？","answer":"A","options":[{"key":"A","text":"直轄市、縣（市）政府。"},{"key":"B","text":"衛福部。"},{"key":"C","text":"農委會。"},{"key":"D","text":"交通部。"}]},{"id":"chapter-01-026","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機未經同意飛入禁航區、限航區，得由何者採取適當措施予以制止或排除？","answer":"B","options":[{"key":"A","text":"交通警察大隊。"},{"key":"B","text":"禁航區、限航區之管理人。"},{"key":"C","text":"鄉鎮區公所。"},{"key":"D","text":"地方派出所。"}]},{"id":"chapter-01-027","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機未經同意飛入航空站或飛行場四周之一定距離範圍內者，航空站、飛行場之經營人或管理人得會同何者予以取締？","answer":"C","options":[{"key":"A","text":"當地里長。"},{"key":"B","text":"地方派出所。"},{"key":"C","text":"航空警察局。"},{"key":"D","text":"交通警察大隊。"}]},{"id":"chapter-01-028","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機未經同意飛入直轄市、縣（市）政府所公告之活動區域、時間及其他管理事項外者，得由何者進行取締？","answer":"A","options":[{"key":"A","text":"直轄市、縣（市）政府。"},{"key":"B","text":"鄉鎮區公所。"},{"key":"C","text":"地方派出所。"},{"key":"D","text":"衛福部。"}]},{"id":"chapter-01-029","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事休閒娛樂用途之遙控無人機活動，其飛航實際高度不得逾距地面或水面多少高度？","answer":"B","options":[{"key":"A","text":"800呎。"},{"key":"B","text":"400呎。"},{"key":"C","text":"200呎。"},{"key":"D","text":"100呎。"}]},{"id":"chapter-01-030","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事遙控無人機飛航活動，非經民航局核准不得執行下列何者行為？","answer":"C","options":[{"key":"A","text":"以信號鏈路進行飛航控制。"},{"key":"B","text":"以自動駕駛操作。"},{"key":"C","text":"投擲或噴灑任何物件。"},{"key":"D","text":"其他經民航局同意之操作。"}]},{"id":"chapter-01-031","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事遙控無人機飛航活動，不得裝載哪種物品？","answer":"C","options":[{"key":"A","text":"光學酬載。"},{"key":"B","text":"飛航所需燃油或電池。"},{"key":"C","text":"民用航空法所公告之危險物品。"},{"key":"D","text":"調整重心所需之配重塊。"}]},{"id":"chapter-01-032","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"哪個機關負責訂定從事遙控無人機飛航活動所應遵守之規範？","answer":"B","options":[{"key":"A","text":"衛福部。"},{"key":"B","text":"交通部。"},{"key":"C","text":"內政部。"},{"key":"D","text":"文化部。"}]},{"id":"chapter-01-033","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事休閒娛樂用途之遙控無人機不得於下列哪個區域進行飛航活動？","answer":"A","options":[{"key":"A","text":"人群聚集或室外集會遊行上空。"},{"key":"B","text":"經地方政府同意開放無人機活動之公園綠地。"},{"key":"C","text":"經地方政府同意開放無人機活動之人煙稀少區。"},{"key":"D","text":"經地方政府同意開放無人機活動之河灘地。"}]},{"id":"chapter-01-034","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事休閒娛樂用途之遙控無人機不得於下列哪個時間進行飛航活動？","answer":"A","options":[{"key":"A","text":"日落後至日出前。"},{"key":"B","text":"日出後。"},{"key":"C","text":"正中午。"},{"key":"D","text":"無特別規定。"}]},{"id":"chapter-01-035","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人於從事休閒娛樂用途之遙控無人機飛航活動時，最多得同時控制幾架遙控無人機？","answer":"A","options":[{"key":"A","text":"1架。"},{"key":"B","text":"2架。"},{"key":"C","text":"5架。"},{"key":"D","text":"10架以上。"}]},{"id":"chapter-01-036","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人於從事遙控無人機飛航活動期間，應留意下列何者？","answer":"C","options":[{"key":"A","text":"遙控無人機之販售包裝。"},{"key":"B","text":"遙控無人機之外觀造型。"},{"key":"C","text":"遙控無人機飛航及其周遭狀況。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-01-037","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"從事遙控無人機飛航活動時，應防止其與何者之接近或碰撞？","answer":"D","options":[{"key":"A","text":"其他航空器。"},{"key":"B","text":"建築物。"},{"key":"C","text":"人群。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-038","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人欲執行遙控無人機法規所訂之操作限制者，得檢附相關文書並向下列何者申請核准後為之？","answer":"B","options":[{"key":"A","text":"直轄市、縣（市）政府。"},{"key":"B","text":"民航局。"},{"key":"C","text":"警察機關。"},{"key":"D","text":"衛福部。"}]},{"id":"chapter-01-039","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人經民航局核准得於「人群聚集或室外集會遊行上空」進行飛航活動者，其活動場地部分仍應取得何者之同意？","answer":"A","options":[{"key":"A","text":"直轄市、縣（市）政府及相關中央主管機關。"},{"key":"B","text":"直轄市、縣（市）政府。"},{"key":"C","text":"相關中央主管機關。"},{"key":"D","text":"當地派出所。"}]},{"id":"chapter-01-040","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作遙控無人機發生下列哪種情形時，遙控無人機所有人應負賠償責任？","answer":"D","options":[{"key":"A","text":"故意致他人死傷。"},{"key":"B","text":"過失致他人死傷。"},{"key":"C","text":"故意或過失毀損他人財物。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-041","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機所有人將其遙控無人機交由他人進行操作而不慎墜落傷人，應由何人負連帶賠償責任？","answer":"C","options":[{"key":"A","text":"所有人及旁觀人。"},{"key":"B","text":"所有人及設計者。"},{"key":"C","text":"所有人及操作人。"},{"key":"D","text":"所有人及製造者。"}]},{"id":"chapter-01-042","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人於從事民航局核准之遙控無人機飛航活動前，應依法投保責任保險，係依據何法所定之內容？","answer":"B","options":[{"key":"A","text":"保險法。"},{"key":"B","text":"民用航空法。"},{"key":"C","text":"民法。"},{"key":"D","text":"勞動基準法。"}]},{"id":"chapter-01-043","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機所有人或操作人違反「禁航區、限航區及航空站或飛行場四周之一定距離範圍內從事飛航活動」之相關規定者，民航局除廢止其操作證並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"D","options":[{"key":"A","text":"3萬元以上18萬元以下。"},{"key":"B","text":"5萬元以上28萬元以下。"},{"key":"C","text":"10萬元以上48萬元以下。"},{"key":"D","text":"30萬元以上150萬元以下。"}]},{"id":"chapter-01-044","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機所有人或操作人違反「不得逾距地面或水面高度400呎從事飛航活動」之規定者，民航局除廢止其操作證並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"A","options":[{"key":"A","text":"30萬元以上150萬元以下。"},{"key":"B","text":"1萬元以上10萬元以下。"},{"key":"C","text":"20萬元以上50萬元以下。"},{"key":"D","text":"5萬元以上30萬元以下。"}]},{"id":"chapter-01-045","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之所有人或操作人違反「未領有操作證而操作遙控無人機」之規定者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"C","options":[{"key":"A","text":"1萬元以上8萬元以下。"},{"key":"B","text":"3萬元以上18萬元以下。"},{"key":"C","text":"6萬元以上30萬元以下。"},{"key":"D","text":"8萬元以上38萬元以下。"}]},{"id":"chapter-01-046","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之所有人或操作人違反「未投保或未足額投保責任保險而從事遙控無人機活動」之規定者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"A","options":[{"key":"A","text":"6萬元以上30萬元以下。"},{"key":"B","text":"3萬元以上20萬元以下。"},{"key":"C","text":"1萬元以上8萬元以下。"},{"key":"D","text":"8萬元以上50萬元以下。"}]},{"id":"chapter-01-047","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之所有人或操作人違反「遙控無人機註冊或標明註冊號碼」之相關規定者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"D","options":[{"key":"A","text":"10萬元以上48萬元以下。"},{"key":"B","text":"8萬元以上38萬元以下。"},{"key":"C","text":"5萬元以上28萬元以下。"},{"key":"D","text":"3萬元以上15萬元以下。"}]},{"id":"chapter-01-048","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之所有人或操作人違反「直轄市、縣（市）政府公告之區域、時間及其他管理事項」之相關規定者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"A","options":[{"key":"A","text":"3萬元以上15萬元以下。"},{"key":"B","text":"5萬元以上28萬元以下。"},{"key":"C","text":"8萬元以上38萬元以下。"},{"key":"D","text":"15萬元以上30萬元以下。"}]},{"id":"chapter-01-049","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之所有人或操作人違反「遙控無人機飛航活動應遵守之規定」者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"D","options":[{"key":"A","text":"10萬元以上48萬元以下。"},{"key":"B","text":"8萬元以上38萬元以下。"},{"key":"C","text":"5萬元以上28萬元以下。"},{"key":"D","text":"3萬元以上15萬元以下。"}]},{"id":"chapter-01-050","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"違反「射頻識別、檢驗、認可、維修與檢查、飛航活動之活動許可及內容、製造者與進口者之登錄及責任、飛航安全相關事件之通報等事項」規定者，除禁止其活動，情節重大者並得沒入遙控無人機外，另處多少新臺幣之罰鍰？","answer":"A","options":[{"key":"A","text":"1萬元以上150萬元以下。"},{"key":"B","text":"5萬元以上498萬元以下。"},{"key":"C","text":"8萬元以上798萬元以下。"},{"key":"D","text":"10萬元以上998萬元以下。"}]},{"id":"chapter-01-051","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機和遙控設備間為操作飛行管理目的之資料鏈接，稱之？","answer":"B","options":[{"key":"A","text":"網路鏈路。"},{"key":"B","text":"通訊及控制信號鏈路。"},{"key":"C","text":"電信鏈路。"},{"key":"D","text":"光纖鏈路。"}]},{"id":"chapter-01-052","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"計算遙控無人機之最大起飛重量(MTOW)，應包含下列哪些重量？","answer":"D","options":[{"key":"A","text":"機體。"},{"key":"B","text":"燃料、電池。"},{"key":"C","text":"負載設備、酬載。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-053","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"依據法規定義，於遙控無人機飛航活動期間，實際操控遙控無人機或指揮監督飛航活動之人員稱之？","answer":"B","options":[{"key":"A","text":"目視觀察員。"},{"key":"B","text":"遙控無人機操作人。"},{"key":"C","text":"任務協調員。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-01-054","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"依據法規定義，持有遙控無人機操作證並於遙控無人機活動期間，提供實際操控遙控無人機操作人必要飛航資訊之人員稱之？","answer":"B","options":[{"key":"A","text":"設計者。"},{"key":"B","text":"目視觀察員。"},{"key":"C","text":"製造者。"},{"key":"D","text":"遙控無人機所有人。"}]},{"id":"chapter-01-055","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機依其構造可分為哪幾種？","answer":"D","options":[{"key":"A","text":"無人飛機。"},{"key":"B","text":"無人直昇機。"},{"key":"C","text":"無人多旋翼機。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-056","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"無人多旋翼機具有幾個以上之垂直傳動軸？","answer":"B","options":[{"key":"A","text":"2個以上。"},{"key":"B","text":"3個以上。"},{"key":"C","text":"4個以上。"},{"key":"D","text":"6個以上。"}]},{"id":"chapter-01-057","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"何人應負飛航安全之責，對遙控無人機為妥善之維護，並從事安全飛航作業？","answer":"A","options":[{"key":"A","text":"遙控無人機所有人及操作人。"},{"key":"B","text":"遙控無人機設計者。"},{"key":"C","text":"遙控無人機製造者。"},{"key":"D","text":"遙控無人機改裝者。"}]},{"id":"chapter-01-058","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"若遙控無人機飛航活動涉及2位以上之操作者，下列敘述何者正確？","answer":"A","options":[{"key":"A","text":"應指定1人為決定權人，使得從事飛航活動。"},{"key":"B","text":"不須指定決定權人即可從事飛航活動。"},{"key":"C","text":"是否指定決定權人視任務性質而定。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-01-059","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"下列何者較適合做為遙控無人機註冊號碼之標明處所？","answer":"C","options":[{"key":"A","text":"起落架上。"},{"key":"B","text":"螺旋槳面上。"},{"key":"C","text":"機身未遮蔽之平整面上。"},{"key":"D","text":"電池蓋上。"}]},{"id":"chapter-01-060","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"註冊號碼應以標籤、鐫刻、噴漆或其他能辨識之方式標明，並於每次飛航時符合下列何項要求？","answer":"D","options":[{"key":"A","text":"確保不至脫落。"},{"key":"B","text":"保持清潔。"},{"key":"C","text":"能明顯辨識。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-061","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機註冊號碼之標漆位置依法應位於何處？","answer":"B","options":[{"key":"A","text":"固定結構內部。"},{"key":"B","text":"固定結構外部。"},{"key":"C","text":"轉動機構外部。"},{"key":"D","text":"轉動機構內部。"}]},{"id":"chapter-01-062","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"註冊號碼之顏色應以肉眼即能辨識，並應符合下列何項要求？","answer":"C","options":[{"key":"A","text":"融入背景顏色。"},{"key":"B","text":"與背景顏色相近。"},{"key":"C","text":"與背景明顯反襯。"},{"key":"D","text":"無特別規定。"}]},{"id":"chapter-01-063","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關遙控無人機註冊號碼之使用，下列何者正確？","answer":"D","options":[{"key":"A","text":"不得偽造。"},{"key":"B","text":"不得變造。"},{"key":"C","text":"不得矇領。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-064","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關遙控無人機註冊號碼之使用，下列何者正確？","answer":"A","options":[{"key":"A","text":"不得於任何未註冊之遙控無人機上使用。"},{"key":"B","text":"可於他人未註冊之遙控無人機上使用。"},{"key":"C","text":"可於自己所有未註冊之遙控無人機上使用。"},{"key":"D","text":"使用狀況視遙控無人機型式而定。"}]},{"id":"chapter-01-065","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量超過一定重量之遙控無人機應具有射頻識別功能，其一定重量，係由下列哪個機關公告之？","answer":"D","options":[{"key":"A","text":"衛福部。"},{"key":"B","text":"內政部。"},{"key":"C","text":"科技部。"},{"key":"D","text":"民航局。"}]},{"id":"chapter-01-066","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之設計、製造、改裝，可由何者提出型式檢驗申請？","answer":"D","options":[{"key":"A","text":"設計者。"},{"key":"B","text":"製造者。"},{"key":"C","text":"改裝者。"},{"key":"D","text":"以上皆可。"}]},{"id":"chapter-01-067","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機之設計、製造、改裝，應檢附申請書向哪個機關申請型式檢驗？","answer":"A","options":[{"key":"A","text":"民航局。"},{"key":"B","text":"衛福部。"},{"key":"C","text":"內政部。"},{"key":"D","text":"科技部。"}]},{"id":"chapter-01-068","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"自國外進口之遙控無人機，應由何者依規定向民航局申請型式檢驗？","answer":"C","options":[{"key":"A","text":"操作人。"},{"key":"B","text":"所有人。"},{"key":"C","text":"進口者。"},{"key":"D","text":"設計者。"}]},{"id":"chapter-01-069","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機於設計、製造、改裝階段為驗證性能諸元所需之試飛，應檢附文件向哪個機關申請試飛活動？","answer":"D","options":[{"key":"A","text":"衛福部。"},{"key":"B","text":"內政部。"},{"key":"C","text":"科技部。"},{"key":"D","text":"民航局。"}]},{"id":"chapter-01-070","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量25公斤以上之遙控無人機，為確保其符合設計、製造、改裝之性能諸元，應由何者提出實體檢驗申請？","answer":"B","options":[{"key":"A","text":"操作人。"},{"key":"B","text":"所有人。"},{"key":"C","text":"設計者。"},{"key":"D","text":"製造者。"}]},{"id":"chapter-01-071","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量25公斤以上之遙控無人機，為確保其符合設計、製造、改裝之性能諸元，應向哪個機關申請實體檢驗？","answer":"A","options":[{"key":"A","text":"民航局。"},{"key":"B","text":"衛福部。"},{"key":"C","text":"內政部。"},{"key":"D","text":"科技部。"}]},{"id":"chapter-01-072","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"自行製造、使用之最大起飛重量25公斤以上遙控無人機，何人可提出合併型式檢驗及實體檢驗之申請？","answer":"C","options":[{"key":"A","text":"製造者。"},{"key":"B","text":"操作人。"},{"key":"C","text":"所有人。"},{"key":"D","text":"設計者。"}]},{"id":"chapter-01-073","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"自行製造、使用之最大起飛重量25公斤以上遙控無人機，可向哪個機關提出合併型式檢驗及實體檢驗之申請？","answer":"B","options":[{"key":"A","text":"內政部。"},{"key":"B","text":"民航局。"},{"key":"C","text":"科技部。"},{"key":"D","text":"衛福部。"}]},{"id":"chapter-01-074","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"實體檢驗合格證或特種實體檢驗合格證之記載事項如有變更時，下列敘述何者正確？","answer":"D","options":[{"key":"A","text":"製造者應於事實發生日起15日內申請換發。"},{"key":"B","text":"設計者應於事實發生日起10日內申請換發。"},{"key":"C","text":"操作人應於事實發生日起7日內申請換發。"},{"key":"D","text":"所有人應於事實發生日起15日內申請換發。"}]},{"id":"chapter-01-075","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關遙控無人機製造者與進口者申請產品資訊登錄時機，下列敘述何者正確？","answer":"A","options":[{"key":"A","text":"販售或進口前。"},{"key":"B","text":"販售或進口時。"},{"key":"C","text":"販售或進口後。"},{"key":"D","text":"以上皆可。"}]},{"id":"chapter-01-076","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機製造者與進口者應向哪個機關申請產品資訊登錄？","answer":"C","options":[{"key":"A","text":"內政部。"},{"key":"B","text":"科技部。"},{"key":"C","text":"民航局。"},{"key":"D","text":"經濟部。"}]},{"id":"chapter-01-077","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量25公斤以上之遙控無人機因系統設計、製造或改裝缺失而致有不安全情況時，下列何者為非？","answer":"D","options":[{"key":"A","text":"設計者應針對該缺失採取補正措施。"},{"key":"B","text":"製造者應針對該缺失採取補正措施。"},{"key":"C","text":"改裝者應針對該缺失採取補正措施。"},{"key":"D","text":"無須採取任何補正措施。"}]},{"id":"chapter-01-078","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作政府機關（構）、學校或法人所有遙控無人機之操作人應持有民航局發給之何種證照，始得操作？","answer":"B","options":[{"key":"A","text":"機師檢定證。"},{"key":"B","text":"操作證。"},{"key":"C","text":"維修檢定證。"},{"key":"D","text":"鑑定合格證。"}]},{"id":"chapter-01-079","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關遙控無人機操作證之分類，下列何者為非？","answer":"A","options":[{"key":"A","text":"暫時操作證。"},{"key":"B","text":"普通操作證。"},{"key":"C","text":"專業操作證。"},{"key":"D","text":"學習操作證。"}]},{"id":"chapter-01-080","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"自然人欲以遙控無人機從事休閒娛樂用途，下列有關考照需求敘述何者正確？","answer":"B","options":[{"key":"A","text":"操作10公斤且裝置導航設備之遙控無人機不需考照。"},{"key":"B","text":"操作未達2公斤之遙控無人機不須考照。"},{"key":"C","text":"操作15公斤以上之遙控無人機僅需通過學科測驗。"},{"key":"D","text":"操作未達2公斤之遙控無人機須通過學科測驗。"}]},{"id":"chapter-01-081","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"申請遙控無人機專業操作證者，其術科測驗應於學科測驗通過日起多久內完成，否則應重新申請學科測驗？","answer":"D","options":[{"key":"A","text":"3個月內。"},{"key":"B","text":"6個月內。"},{"key":"C","text":"9個月內。"},{"key":"D","text":"1年內。"}]},{"id":"chapter-01-082","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人從事遙控無人機活動，應於何時依製造者所提供之維修指引對遙控無人機系統進行檢查，以符合安全飛航條件後始得活動？","answer":"A","options":[{"key":"A","text":"應於飛航活動前執行。"},{"key":"B","text":"應於飛航活動後執行。"},{"key":"C","text":"應於飛航活動中執行。"},{"key":"D","text":"任何時間均可執行。"}]},{"id":"chapter-01-083","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人從事遙控無人機飛航活動前，下列何者非為主要考量因素？","answer":"D","options":[{"key":"A","text":"氣象條件。"},{"key":"B","text":"空域、飛航限制。"},{"key":"C","text":"其他空中或地面之危害因素。"},{"key":"D","text":"操作者家庭狀況。"}]},{"id":"chapter-01-084","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關操作人欲於載具上操作遙控無人機以進行飛航活動，下列敘述何者錯誤？","answer":"C","options":[{"key":"A","text":"可於固定之導控站上操作。"},{"key":"B","text":"可於固定之車輛上操作。"},{"key":"C","text":"可於移動中之航空器上操作。"},{"key":"D","text":"可於固定之船艦上操作。"}]},{"id":"chapter-01-085","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"哪些單位應檢附文件向民航局申請核准後，始得從事遙控無人機飛航活動？","answer":"D","options":[{"key":"A","text":"政府機關（構）。"},{"key":"B","text":"學校。"},{"key":"C","text":"法人。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-01-086","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人欲於直轄市、縣（市）政府公告之禁止、限制區域內從事遙控無人機飛航活動者，應至少於活動日前多久檢附計畫書提出申請？","answer":"C","options":[{"key":"A","text":"30日前。"},{"key":"B","text":"20日前。"},{"key":"C","text":"15日前。"},{"key":"D","text":"10日前。"}]},{"id":"chapter-01-087","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量2公斤以上且裝置導航設備之遙控無人機遭受實質損害或失蹤時，所有人或操作人應於發生或得知消息後多久內填具飛航安全相關事件報告表通報民航局？","answer":"C","options":[{"key":"A","text":"6小時內。"},{"key":"B","text":"12小時內。"},{"key":"C","text":"24小時內。"},{"key":"D","text":"48小時內。"}]},{"id":"chapter-01-088","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"當遙控無人機發生與其他航空器或障礙物接近或碰撞之事故時，所有人或操作人應於發生或得知消息後多久內填具飛航安全相關事件報告表通報民航局？","answer":"C","options":[{"key":"A","text":"6小時內。"},{"key":"B","text":"12小時內。"},{"key":"C","text":"24小時內。"},{"key":"D","text":"48小時內。"}]},{"id":"chapter-01-089","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"當發生遙控無人機飛航安全相關事件時，民航局針對操作人可採取哪項措施？","answer":"A","options":[{"key":"A","text":"得逕為暫停其操作或飛航活動。"},{"key":"B","text":"經操作人同意後，得暫停其操作或飛航活動。"},{"key":"C","text":"經所在地方政府同意後，得暫停其操作或飛航活動。"},{"key":"D","text":"需待調查結束後並經操作人同意，使得暫停其操作或飛航活動。"}]},{"id":"chapter-01-090","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"根據「遙控無人機管理規則」內容，各項申請及通報作業可透過何處以電子化方式為之？","answer":"B","options":[{"key":"A","text":"地方政府所建置之資訊系統。"},{"key":"B","text":"民航局所指定之資訊系統。"},{"key":"C","text":"財政部所建置資訊系統。"},{"key":"D","text":"經濟部所建置資訊系統。"}]},{"id":"chapter-01-091","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機經型式檢驗合格後，除因改裝需重新辦理檢驗及註冊異動外，是否需再辦理定期檢驗？","answer":"B","options":[{"key":"A","text":"仍需再辦理定期檢驗。"},{"key":"B","text":"無需再辦理定期檢驗。"},{"key":"C","text":"操作人認為有需要則應再辦理定期檢驗。"},{"key":"D","text":"所有人認為有需要則應再辦理定期檢驗。"}]},{"id":"chapter-01-092","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機於發生飛航安全相關事件後，何人應負責進行通報？","answer":"C","options":[{"key":"A","text":"僅有所有人。"},{"key":"B","text":"僅有操作人。"},{"key":"C","text":"所有人或操作人。"},{"key":"D","text":"操作人之親屬。"}]},{"id":"chapter-01-093","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人未經獲准從事視距外之遙控無人機飛航活動，除不得使用矯正鏡片外之任何工具做延伸視距飛航外，另須遵守哪項飛航範圍限制？","answer":"B","options":[{"key":"A","text":"須於信號鏈路有效範圍內操作。"},{"key":"B","text":"須於目視範圍內操作。"},{"key":"C","text":"須於自動駕駛有效範圍內操作。"},{"key":"D","text":"須於安全油量範圍內操作。"}]},{"id":"chapter-01-094","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關政府機關（構）、學校或法人欲執行獲民航局許可之遙控無人機飛航任務，下列敘述何者正確？","answer":"C","options":[{"key":"A","text":"飛航任務後應向民航局申請該次活動許可。"},{"key":"B","text":"飛航任務時應向民航局申請該次活動許可。"},{"key":"C","text":"飛航任務前應向民航局申請該次活動許可。"},{"key":"D","text":"不須向民航局申請該次活動許可。"}]},{"id":"chapter-01-095","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機管理規則針對「延伸視距飛航」之定義，下列何者為非？","answer":"D","options":[{"key":"A","text":"操作人須於視距外操作。"},{"key":"B","text":"目視觀察員須距遙控無人機半徑三百公尺範圍內。"},{"key":"C","text":"操作人應自目視觀察員獲取必要飛航資訊。"},{"key":"D","text":"目視觀察員不須與遙控無人機保持直接目視接觸。"}]},{"id":"chapter-01-096","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機管理規則如何定義「延伸視距最大範圍」？","answer":"A","options":[{"key":"A","text":"以遙控無人機操作人為中心，半徑900公尺、相對地面或水面高度低於400呎內之區域。"},{"key":"B","text":"以遙控無人機操作人為中心，半徑600公尺、相對地面或水面高度低於300呎內之區域。"},{"key":"C","text":"以遙控無人機操作人為中心，半徑500公尺、相對地面或水面高度低於200呎內之區域。"},{"key":"D","text":"以遙控無人機操作人為中心，半徑1,200公尺、相對地面或水面高度低於200呎內之區域。"}]},{"id":"chapter-01-097","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"針對自然人所有之遙控無人機，法規明訂其最大起飛重量達多少以上，即應辦理註冊？","answer":"A","options":[{"key":"A","text":"250公克以上。"},{"key":"B","text":"1公斤以上。"},{"key":"C","text":"2公斤以上。"},{"key":"D","text":"15公斤以上。"}]},{"id":"chapter-01-098","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機發生滅失情形者，其所有人申請註銷註冊之程序為何？","answer":"A","options":[{"key":"A","text":"事實發生日起15日內向民航局申請。"},{"key":"B","text":"事實發生日起20日內向民航局申請。"},{"key":"C","text":"事實發生日起15日內向所在地方政府申請。"},{"key":"D","text":"事實發生日起20日內向所在地方政府申請。"}]},{"id":"chapter-01-099","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機註冊號碼之有效期限為幾年？","answer":"B","options":[{"key":"A","text":"1年。"},{"key":"B","text":"2年。"},{"key":"C","text":"3年。"},{"key":"D","text":"4年。"}]},{"id":"chapter-01-100","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"法規規定最大起飛重量達多少以上且裝置導航設備之遙控無人機，應具備防止其進入禁、限航區及航空站或飛行場四周一定距離範圍內之圖資軟體系統？","answer":"B","options":[{"key":"A","text":"250公克以上。"},{"key":"B","text":"1公斤以上。"},{"key":"C","text":"2公斤以上。"},{"key":"D","text":"15公斤以上。"}]},{"id":"chapter-01-101","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機實體檢驗合格證之有效期限為幾年？","answer":"C","options":[{"key":"A","text":"1年。"},{"key":"B","text":"2年。"},{"key":"C","text":"3年。"},{"key":"D","text":"4年。"}]},{"id":"chapter-01-102","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"持有普通操作證之自然人，依規定得操作下列哪個重量級距之遙控無人機？","answer":"C","options":[{"key":"A","text":"15公斤以上之遙控無人機。"},{"key":"B","text":"25公斤以上之遙控無人機。"},{"key":"C","text":"未達15公斤且裝置導航設備之遙控無人機。"},{"key":"D","text":"30公斤以上之遙控無人機。"}]},{"id":"chapter-01-103","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"持有普通操作證及專業操作證對於可操控之遙控無人機重量界線為何？","answer":"C","options":[{"key":"A","text":"1公斤。"},{"key":"B","text":"2公斤。"},{"key":"C","text":"15公斤。"},{"key":"D","text":"25公斤。"}]},{"id":"chapter-01-104","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"針對學習操作證之敘述，下列何者為非？","answer":"C","options":[{"key":"A","text":"申請者應年滿16歲。"},{"key":"B","text":"持有者須於具備普通或專業操作證之操作人在旁指導監護下，使得操作。"},{"key":"C","text":"持有者所操作遙控無人機構型不受限制。"},{"key":"D","text":"持有者所操作遙控無人機重量不得逾15公斤。"}]},{"id":"chapter-01-105","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"針對專業操作證之敘述，下列何者正確？","answer":"C","options":[{"key":"A","text":"分為初、中、高等3級。"},{"key":"B","text":"持有者僅須通過學科測驗。"},{"key":"C","text":"持有者得執行獲核准之法人委託業務。"},{"key":"D","text":"持有者無須經過體格檢查。"}]},{"id":"chapter-01-106","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"申請遙控無人機專業操作證者，其術科測驗應於學科測驗通過日起多久內完成？","answer":"D","options":[{"key":"A","text":"3個月內。"},{"key":"B","text":"6個月內。"},{"key":"C","text":"9個月內。"},{"key":"D","text":"1年內。"}]},{"id":"chapter-01-107","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"操作人操作遙控無人機時，血液中酒精濃度依法不得超過多少？","answer":"B","options":[{"key":"A","text":"0.01%。"},{"key":"B","text":"0.02%。"},{"key":"C","text":"0.04%。"},{"key":"D","text":"0.06%。"}]},{"id":"chapter-01-108","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"最大起飛重量未達25公斤且裝置導航設備之遙控無人機，其最大飛行速度不得超過多少？","answer":"B","options":[{"key":"A","text":"70海浬/小時。"},{"key":"B","text":"87海浬/小時。"},{"key":"C","text":"100海浬/小時。"},{"key":"D","text":"150海浬/小時。"}]},{"id":"chapter-01-109","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人欲於禁、限航區及航空站或飛行場四周一定距離範圍內從事遙控無人機飛航活動者，應於活動日前多久提出申請？","answer":"A","options":[{"key":"A","text":"15日前。"},{"key":"B","text":"10日前。"},{"key":"C","text":"5日前。"},{"key":"D","text":"3日前。"}]},{"id":"chapter-01-110","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人於涉及軍事航空管理機關（構）管理之禁、限航區及航空站或飛行場四周一定距離範圍內從事遙控無人機飛航活動者，應於活動日前多久提出申請？","answer":"A","options":[{"key":"A","text":"30日前。"},{"key":"B","text":"20日前。"},{"key":"C","text":"15日前。"},{"key":"D","text":"10日前。"}]},{"id":"chapter-01-111","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人於直轄市、縣（市）政府公告之禁止、限制區域內從事遙控無人機飛航活動時，如有跨縣市飛航情形，應向哪個機關提出申請？","answer":"B","options":[{"key":"A","text":"飛經之直轄市、縣（市）政府。"},{"key":"B","text":"起飛地點所在直轄市、縣（市）政府提出申請，經所在地及跨縣市政府同意。"},{"key":"C","text":"降落地點所在直轄市、縣（市）政府。"},{"key":"D","text":"降落地點所鄰近直轄市、縣（市）政府。"}]},{"id":"chapter-01-112","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"當災害發生時，欲於各級政府依災害防救法劃定之警戒區域或指定區域內從事遙控無人機飛航活動者，應聽從何者之統一指揮調度？","answer":"D","options":[{"key":"A","text":"民航局局長。"},{"key":"B","text":"當地警察局局長。"},{"key":"C","text":"當地消防局局長。"},{"key":"D","text":"各級政府災害應變中心指揮官。"}]},{"id":"chapter-01-113","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"政府機關（構）、學校或法人依法應保存遙控無人機之註冊號碼、活動日期、活動區域、飛航時間、飛航性質、操作人員姓名、維護或修理、改裝等紀錄，並應保存多久？","answer":"B","options":[{"key":"A","text":"1年。"},{"key":"B","text":"2年。"},{"key":"C","text":"3年。"},{"key":"D","text":"5年。"}]},{"id":"chapter-01-114","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關外國人領有外國政府所核發遙控無人機相關證照者，應向民航局申請認可後使得於本區從事遙控無人機飛航活動之規定，是否亦適用於領有外國政府核發證照之本國人？","answer":"B","options":[{"key":"A","text":"是，本國人亦適用。"},{"key":"B","text":"否，本國人不適用。"},{"key":"C","text":"視活動時間決定適用與否。"},{"key":"D","text":"視活動性質決定適用與否。"}]},{"id":"chapter-01-115","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某合格無人機業務團隊受委託以遙控無人機執行山區電纜線路查檢工作。惟因路況不佳，該團隊無法抵達預訂工作區域，為不影響任務進行，成員臨時決定仍將無人機飛至工作區，並以望遠鏡保持與其間之視線接觸。請問該團隊之決定是否違反無人機相關規範？","answer":"B","options":[{"key":"A","text":"並無違反遙控無人機相關規範。"},{"key":"B","text":"已違反遙控無人機相關規範。"},{"key":"C","text":"有無違反規範視任務執行結果而定。"},{"key":"D","text":"資訊不足，無法判斷。"}]},{"id":"chapter-01-116","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊獲准於機場跑道上空測試某項酬載功能，有人建議飛得越高越能展現測試成果，請問操作人對於該建議應有哪項認知？","answer":"B","options":[{"key":"A","text":"活動既經核准，即無飛航高度限制，想飛多高就多高。"},{"key":"B","text":"飛航高度未經核准，仍應遵守距地表面不得逾400呎之規定。"},{"key":"C","text":"飛航高度聽從現場指揮人員視任務執行狀況決定。"},{"key":"D","text":"飛航高度視能見度好壞決定。"}]},{"id":"chapter-01-117","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊正擬定拍攝一大型廟會活動之飛航計畫，請問該團隊對於其執行之任務，應有下列何種正確認知？","answer":"D","options":[{"key":"A","text":"團隊技術高超，拍攝時無須特別防護工作。"},{"key":"B","text":"為達拍攝效果，於任務中任意變換無人機飛航高度甚至接近人群是可以接受的。"},{"key":"C","text":"重量較輕的無人機相對危害較小，故可隨意飛近目標物進行拍攝。"},{"key":"D","text":"操作人應領有相應專業操作證，且於執行任務前應申請活動許可。"}]},{"id":"chapter-01-118","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"無人機團隊正在作飛行前準備，臨時被告知因緊急狀況，無人機於飛航時必須裝載由民航局公告之危險物品，請問操作人該有下列哪項正確認知？","answer":"B","options":[{"key":"A","text":"僅要能確保無人機飛航時之平衡及控制穩定，即同意該要求，否則拒絕該要求。"},{"key":"B","text":"未經核准前，依規定不得以無人機裝載危險物品，應直接拒絕該要求。"},{"key":"C","text":"如該危險物品之包裝完好且易固定，即同意該要求，否則就拒絕該要求。"},{"key":"D","text":"因為緊急狀況，應無條件同意該要求。"}]},{"id":"chapter-01-119","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某款遙控無人機搭載攝影機及GPS等裝備，可利用圖傳系統於螢幕上即時傳輸圖像，請問操作人於操作該款無人機時，對於即時傳輸圖像功能應具有下列哪項正確認知？","answer":"D","options":[{"key":"A","text":"可完全信賴，操作時不必再監視無人機飛航及其周遭狀況。"},{"key":"B","text":"只要搭載攝影裝備解析度夠好，即不必再監視無人機飛航及其周遭狀況。"},{"key":"C","text":"只要操作人技術夠純熟，即不必再監視無人機飛航及其周遭狀況。"},{"key":"D","text":"無論是否搭載圖傳裝備，操作人仍應隨時監視無人機之飛航及其周遭狀況。"}]},{"id":"chapter-01-120","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"遙控無人機飛航活動對於其他航空器活動、地面人群及建築物所帶來之影響顯而易見，請問就操作人而言，應有下列哪項正確觀念？","answer":"B","options":[{"key":"A","text":"反正其他目標物均很明顯，發現時再緊急避讓即可。"},{"key":"B","text":"應於可操作區域進行飛航、遵守相關規定，隨時注意並防止無人機接近任何其他目標物。"},{"key":"C","text":"只要於可操作區域內飛航，無人機是否接近其他目標物非操作者的責任。"},{"key":"D","text":"進行無人機飛航活動時，若有目視觀察員在側，由目視觀察員全權負責無人機與其他目標物之隔離工作。"}]},{"id":"chapter-01-121","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某明星正在室外舉行音樂發表會，主辦單位看到現場人山人海，為擴大宣傳效果，臨時打算請某無人機團隊利用無人機於現場人群上空進行投擲紀念版T恤及CD活動，請問下列敘述何者正確？","answer":"A","options":[{"key":"A","text":"法規已明訂未取得相應專業操作證及事前活動申請許可，不得以遙控無人機進行投擲作業。"},{"key":"B","text":"主辦單位只要事先向現場人群說明活動進行方式，即可進行投擲作業。"},{"key":"C","text":"只要主辦單位提供之T恤及CD數量能符合無人機酬載需求，即可進行投擲作業。"},{"key":"D","text":"使用無人機投擲物件稀鬆平常，毫無安全疑慮，可以直接進行投擲作業。"}]},{"id":"chapter-01-122","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某電影拍攝作業因取景需求，導演指示團隊將無人機飛入民用航空法所規範之限航區內執行空拍任務，請問下列敘述何者正確？","answer":"B","options":[{"key":"A","text":"只要在限航區內不要待太久，趕緊拍攝完畢就好。"},{"key":"B","text":"非經核准，限航區內不得從事遙控無人機飛航活動。"},{"key":"C","text":"若限航區位處人煙罕至處，飛進去拍攝無妨。"},{"key":"D","text":"只要有助手協助觀察限航區內狀況，即可飛入拍攝。"}]},{"id":"chapter-01-123","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"國內某無人機團隊有名外籍成員，雖領有該國政府所核發之合格無人機操作證，惟尚未獲得本國民航局認可。針對該名外籍成員欲參與團隊於本國境內之無人機飛航活動之敘述，下列何者正確？","answer":"C","options":[{"key":"A","text":"該員已領有外國政府核發證照，理當可於本國境內從事飛航活動。"},{"key":"B","text":"如該員已具備無人機操作經歷滿3年以上，即可直接於本國境內從事飛航活動。"},{"key":"C","text":"該員必須獲得本國民航局認可，使得於本國境內從事飛航活動。"},{"key":"D","text":"只要無人機團隊有人願簽切結書擔保活動之安全，該員即可於本國境內從事飛航活動。"}]},{"id":"chapter-01-124","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"王大華從某購物商場購買一台最大起飛重量950公克的無人多旋翼機，欲作為假日出遊紀錄小孩玩樂過程的利器，有關王大華應注意事項，下列哪項正確？","answer":"C","options":[{"key":"A","text":"王大華不須為該台無人多旋翼機辦理註冊。"},{"key":"B","text":"王大華須取得高級專業操作證後，才能操作該台無人多旋翼機。"},{"key":"C","text":"王大華不得任意於機場周邊進行飛航操作。"},{"key":"D","text":"王大華須為該台無人多旋翼機辦理實體檢驗。"}]},{"id":"chapter-01-125","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某大學校慶活動，預計於該校室內體育館舉行一場無人機競技比賽，請問有關該比賽之適法性問題，下列何者為非？","answer":"B","options":[{"key":"A","text":"該比賽舉辦地點於室內，非屬民航法無人機專章規範範圍。"},{"key":"B","text":"該比賽舉辦地點雖於室內，仍屬民航法無人機專章規範範圍。"},{"key":"C","text":"操作人於比賽過程中仍須注意在場人員之安全。"},{"key":"D","text":"比賽過程中如因操作人操作不當而傷及他人者，操作人仍可能須負相關法律責任。"}]},{"id":"chapter-01-126","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊受知名電視台委託，要利用無人機進行即時新聞事件之空拍作業，惟團隊經評估後認為該空拍作業可能存在安全顧慮，請問該團隊面對電視台之委託，採取下列何項作法較為恰當？","answer":"C","options":[{"key":"A","text":"僅須視操作人經驗決定是否接受該任務。"},{"key":"B","text":"視電視台給予酬勞多寡決定是否接受該任務。"},{"key":"C","text":"評估有安全顧慮即應婉拒該任務，並詳細解釋其原因。"},{"key":"D","text":"視任務活動投保額度高低決定是否接受該任務。"}]},{"id":"chapter-01-127","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"小陳為某新成立無人機業務公司負責人，目前除積極招兵買馬外，亦準備購入20台不同構型、重量之業務用無人機。請問小陳對於該公司所購入無人機之註冊相關規定，下列敘述何者正確？","answer":"A","options":[{"key":"A","text":"所有無人機均須辦理註冊。"},{"key":"B","text":"最大起飛重量超過250公克之無人機才須辦理註冊。"},{"key":"C","text":"僅須為所採購無人機之半數辦理註冊即可。"},{"key":"D","text":"由主管機關決定應辦理註冊之無人機數量。"}]},{"id":"chapter-01-128","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某公司因業務需求所購入之一批無人機剛完成向民航局申請之註冊程序，請問該公司對於註冊號碼之標註規定所應有認知，下列何者為非？","answer":"D","options":[{"key":"A","text":"註冊號碼標註位置須能清楚辨識。"},{"key":"B","text":"註冊號碼得以噴漆方式標註。"},{"key":"C","text":"須確保註冊號碼不會於每次飛航活動中脫落。"},{"key":"D","text":"無人機之移動結構外部最適合作為註冊號碼標註之處。"}]},{"id":"chapter-01-129","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊因特殊任務需求所新購之一架無人機尚未完成註冊程序，惟因任務在即，有成員建議先借用另一架已註冊無人機之註冊號碼，再向民航局報備即可。請問針對該成員之主張，下列何者為正確？","answer":"D","options":[{"key":"A","text":"註冊號碼本來就可以互相借用，並無違反相關規定。"},{"key":"B","text":"只要所借用註冊號碼同屬該團隊其他無人機所有，即無違反相關規定。"},{"key":"C","text":"只要先向民航局報備獲准借用，即無違反相關規範。"},{"key":"D","text":"註冊號碼不得借供於未註冊之無人機上使用，該成員之主張已明顯違反相關規範。"}]},{"id":"chapter-01-130","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"無人機團隊因任務需要，為其所有之一架已取得型式檢驗合格證之無人機進行改裝行為，請問該團隊針對無人機改裝後之應有認知，下列何者正確？","answer":"A","options":[{"key":"A","text":"改裝者應檢附申請書向民航局再次申請型式檢驗。"},{"key":"B","text":"改裝行為並不影響型式檢驗之效力，無須再進行任何檢驗。"},{"key":"C","text":"該團隊能擔保改裝行為不影響無人機飛航性能及安全，即不須再進行任何檢驗。"},{"key":"D","text":"由主管機關自由判定改裝行為是否須進行重新檢驗。"}]},{"id":"chapter-01-131","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某團隊擁有一架最大起飛重量達30公斤之無人飛機逾半年之久，經過幾次任務後發現該機因某項設計缺失而恐致操作安全疑慮，請問該團隊應有下列何項認知及作為？","answer":"B","options":[{"key":"A","text":"只要加強操作人技術及應付緊急狀況之能力即可，不須採取其他作為。"},{"key":"B","text":"團隊應儘速詢求該無人機設計者，以針對設計缺失進行補正作為。"},{"key":"C","text":"於往後每次活動區域內設置安全防護網即可，不須採取其他作為。"},{"key":"D","text":"於往後活動前只要記得投保較高額度之保險即可，不須採取其他作為。"}]},{"id":"chapter-01-132","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某電影公司欲拍攝高速公路警匪追逐場景，為求逼真效果，電影公司要求無人機團隊操作無人機近距離拍攝疾駛於高速公路上之車輛，請問操作人應有哪項正確認知？","answer":"D","options":[{"key":"A","text":"這是訓練自己技術的好機會，應大膽接受任務。"},{"key":"B","text":"看在電影公司給予高額酬勞的份上，理應接受該任務。"},{"key":"C","text":"只要團隊多數人認為可以執行，即應接受該任務。"},{"key":"D","text":"未經核准飛航前，無人機飛航活動應遠離高速公路至少30公尺以上，該任務顯違反規定，應予以拒絕。"}]},{"id":"chapter-01-133","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某區域發生強烈地震，造成人員傷亡及財產損害嚴重，某新聞機構要求無人機團隊不待申請，立即趕赴當地執行空拍任務，以便進行獨家即時新聞報導，請問該團隊應有何種正確認知？","answer":"A","options":[{"key":"A","text":"緊急情況時，應遵守災害防救法之規定，統一聽從政府災害應變中心指揮及調度，不可擅自進行拍攝。"},{"key":"B","text":"因屬災害危難事件、人命關天，應不顧一切答應其要求，並立即前往進行拍攝。"},{"key":"C","text":"只要取得欲拍攝區域之里長口頭同意後，即可進行拍攝任務。"},{"key":"D","text":"只要取得欲拍攝區域之消防主管機關口頭同意後，即可進行拍攝任務。"}]},{"id":"chapter-01-134","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某大學順應潮流成立無人機社團，其成員亦將成為該校未來無人機業務執行主力。學校為擴大宣傳，臨時決定某日下午於校園空曠處進行無人機飛航展示活動，請問下列認知何者正確？","answer":"C","options":[{"key":"A","text":"校園內飛航無受法規限制，可盡情執行飛航展示活動。"},{"key":"B","text":"只要經學校同意，並於活動現場派員口頭宣導注意事項，即可任意進行飛航展示活動。"},{"key":"C","text":"該校仍應於完成飛航活動許可申請後，始得依申請內容進行飛航操作展示。"},{"key":"D","text":"為展示無人機性能，刻意將無人機飛越人群、教室或辦公區域是可允許的。"}]},{"id":"chapter-01-135","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"小華為某公司無人機業務部門主管兼資深飛手，請問有關每趟飛航任務之操作紀錄、無人機維護紀錄及相關修理紀錄等處置事宜，小華應有哪項正確認知？","answer":"D","options":[{"key":"A","text":"法規針對相關紀錄之處置並無明確規範，隨公司高層想怎麼處理都可以。"},{"key":"B","text":"相關紀錄內容隨便寫寫就好，反正任務完成、機器能正常運作即可。"},{"key":"C","text":"明知飛航任務中發生異常現象，為利團隊績效，自行研判若不嚴重，即不須特別紀錄。"},{"key":"D","text":"公司應妥善保存每趟任務之相關紀錄，法規針對紀錄事項及保存期限等亦有相關規定。"}]},{"id":"chapter-01-136","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"一架最大起飛重量5公斤且裝置導航設備之遙控無人機於海岸邊執行空拍任務時，因操作不當而致失控墜海，目視機體已明顯損壞無法繼續使用。請問操作人應採取下列哪項正確作為？","answer":"D","options":[{"key":"A","text":"只要無造成人員傷亡，即不須作任何處置。"},{"key":"B","text":"只要無造成人員傷亡，只需要把墜海的無人機拾回即可。"},{"key":"C","text":"無論有無造成人員傷亡，應於事件發生後24小時內依規定通報當地消防單位。"},{"key":"D","text":"無論有無造成人員傷亡，應於事件發生後24小時內依規定通報民航局。"}]},{"id":"chapter-01-137","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊正規劃一場沙灘音樂饗宴任務，其內容包括：「日落後利用無人機於參與民眾上空噴灑彩色粉末，以製造繽紛效果」。請問下列何者為該團隊執行任務前最重要之考量因素？","answer":"C","options":[{"key":"A","text":"操作者之飛航技術及膽識是否足夠。"},{"key":"B","text":"彩色粉末之數量是否足夠活動需求。"},{"key":"C","text":"該任務是否已經申請核准，操作者是否領有相應操作證。"},{"key":"D","text":"現場燈光及音效設備是否良好，以營造絢麗歡樂效果。"}]},{"id":"chapter-01-138","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某公司無人機團隊正執行飛航任務，突接獲上層電話指示須臨時將無人機飛至前方人群密集之住宅區拍攝所需影像，並表示公司先前已獲得民航局相關安全能力審查通過，可放心飛入執行拍攝。」請問該團隊應有下列何種正確認知？","answer":"B","options":[{"key":"A","text":"當然是聽從上層的要求，直接飛入住宅區進行拍攝。"},{"key":"B","text":"活動前仍應依規定向民航局申請執行許可後，使得進行拍攝。"},{"key":"C","text":"只要臨時通知所在地轄區派出所後，即可進行拍攝。"},{"key":"D","text":"只要臨時通知所在地轄區里長辦公室後，即可進行拍攝。"}]},{"id":"chapter-01-139","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某業餘玩家利用假日至一處未被劃設禁飛區域內進行無人機試飛活動，並預劃完成數項操作科目，此時已接近日落，尚有幾個科目未完成，請問有關下列該玩家應注意事項，何者正確？","answer":"B","options":[{"key":"A","text":"該區域非為禁飛區，故該玩家於日落後仍可持續進行科目操作。"},{"key":"B","text":"該玩家於日落前即應終止其飛航科目操作。"},{"key":"C","text":"如果天氣良好即可於日落後持續進行飛航科目操作。"},{"key":"D","text":"只要觀察四周無人，即可於日落後持續進行飛航科目操作。"}]},{"id":"chapter-01-140","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"假設現有以下資訊： 1.日落時間為本地時間18點46分。 2.民用暮光時間為19點12分。 3.航海暮光時間為19點43分。 4.天文暮光時間為20點16分。請問無人機操作人應於何時終止飛航活動？","answer":"A","options":[{"key":"A","text":"18點46分。"},{"key":"B","text":"19點12分。"},{"key":"C","text":"19點43分。"},{"key":"D","text":"20點16分。"}]},{"id":"chapter-01-141","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"無人機團隊正評估釣客欲於近海海域使用無人機至離岸數公里處進行投放釣餌之操作需求，請問下列哪項說明為該團隊最重要之考量因素？","answer":"C","options":[{"key":"A","text":"無人機裝載釣餌前後之重量與重心變化是否於其操作限制內。"},{"key":"B","text":"無人機之動力來源是否足以支撐該項投擲任務之完成。"},{"key":"C","text":"涉及利用無人機投擲物體之限制操作項目，應申請活動許可並應考取相關操作證。"},{"key":"D","text":"釣客是否投保相關保險並願意簽署任務執行切結書。"}]},{"id":"chapter-01-142","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某雜誌社委託無人機團隊利用無人機執行一項具有相當危險性之飛航任務，負責人並保證：「於執行任務過程中若發生任何事件，導致人員死傷或財物毀損，均由雜誌社全權負責，請團隊安心進行任務。」請問有關該負責人之保證，下列敘述何者正確？","answer":"D","options":[{"key":"A","text":"雜誌社要能提供書面保證及繳交足額保證金，使得作為團隊免責之依據。"},{"key":"B","text":"只要不是故意造成人員死傷或財物毀損，任一方均不須負賠償責任。"},{"key":"C","text":"只要活動經申請核准執行，且已作有必要防護措施者，任一方均不須負賠償責任。"},{"key":"D","text":"操作無人機造成人員死傷或財物毀損，不論故意或過失，應由所有人及操作人負連帶賠償責任。"}]},{"id":"chapter-01-143","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"無人機團隊自行設計並組裝一架無人機，以因應越趨多元之任務型態，因某次任務時程緊迫，團隊雖然知道該無人機尚未通過檢驗核可，仍決議先進行任務使用，等任務結束後再趕緊完成檢驗程序。請問有關該團隊之決議，下列敘述何整正確？","answer":"C","options":[{"key":"A","text":"只要於任務前先以口頭知會民航局，並於任務後儘快送檢即可。"},{"key":"B","text":"只要於任務後以口頭知會民航局，並儘快送檢即可。"},{"key":"C","text":"未經向民航局申請檢驗取得檢驗合格證者，不得從事飛航活動。"},{"key":"D","text":"於任務前先以口頭知會民航局，並由民航局決定是否准予先執行任務，後續再完成檢驗程序。"}]},{"id":"chapter-01-144","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊所有之一架無人機，於一次任務中因動力失效而墜落地面，機身經檢視受損嚴重，並經評估恐難以再修復使用。請問團隊針對該無人機應有之後續處置作為，下列敘述何者正確?","answer":"D","options":[{"key":"A","text":"該無人機既已損毀，直接丟棄即可，惟應保留其註冊號碼及檢驗合格證。"},{"key":"B","text":"再購買一架新無人機，並得直接使用原損壞無人機之註冊號碼，惟不能使用其檢驗合格證。"},{"key":"C","text":"再購買一架新無人機，並得直接使用原損壞無人機之檢驗合格證，惟不能使用其註冊號碼。"},{"key":"D","text":"所有人應於事實發生日起15日內向民航局申請註銷註冊。其註冊號碼及檢驗合格證均不得使用於其他無人機。"}]},{"id":"chapter-01-145","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"某無人機團隊已獲得民航局安全能力審查核可，得於人群聚集處進行空拍任務。於某次任務執行前，團隊依規定向民航局申請活動許可，惟對於是否應向當地地方政府申請一事意見相左，請問下列敘述何者正確？","answer":"C","options":[{"key":"A","text":"法律為民航局訂定的，當然只要向民航局申請即可。"},{"key":"B","text":"一般而言，經民航局核准後，地方政府通常不會有意見，故不須再做申請。"},{"key":"C","text":"除獲民航局許可外，仍應取得地方政府之同意，故還是得做申請。"},{"key":"D","text":"是否要向地方政府申請，依執行任務之危險度或複雜度而定。"}]},{"id":"chapter-01-146","chapterId":"chapter-01","chapterName":"第一章民用航空法及相關法規","question":"有關操作人從事遙控無人機飛航活動時應注意之距離限制，下列何者為正確？","answer":"C","options":[{"key":"A","text":"應至少距高速公路範圍10公尺以上。"},{"key":"B","text":"應至少距高架鐵路範圍20公尺以上。"},{"key":"C","text":"應至少距建築物及障礙物範圍30公尺以上。"},{"key":"D","text":"以上均正確。"}]}]},{"id":"chapter-02","name":"第二章基礎飛行原理","shortName":"基礎飛行原理","questions":[{"id":"chapter-02-001","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機系統包含下列哪項主要次系統？","answer":"D","options":[{"key":"A","text":"遙控無人機體。"},{"key":"B","text":"遙控設備。"},{"key":"C","text":"通訊及控制信號鏈路。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-002","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機系統之飛行載具，包括下列哪些項目？","answer":"C","options":[{"key":"A","text":"機體、負載設備及酬載。"},{"key":"B","text":"機體、燃料或電池。"},{"key":"C","text":"機體、燃料或電池、負載設備及酬載。"},{"key":"D","text":"機體、燃料或電池、負載設備及酬載、遙控設備。"}]},{"id":"chapter-02-003","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機系統之地面控制站的硬體設備，包括下列哪個項目？","answer":"D","options":[{"key":"A","text":"訊號傳輸設備。"},{"key":"B","text":"指令傳輸設備。"},{"key":"C","text":"資訊接收分析設備。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-004","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人飛機起飛時，除跑道起飛外，還可運用下列哪項裝置？","answer":"D","options":[{"key":"A","text":"火箭助推。"},{"key":"B","text":"彈射軌道發射。"},{"key":"C","text":"人力拋擲。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-005","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人飛機降落時，除跑道降落外，也可運用下列哪項方式？","answer":"D","options":[{"key":"A","text":"攔截網。"},{"key":"B","text":"纜線勾鎖。"},{"key":"C","text":"降落傘。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-006","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機許多層面都還是要由人員來掌握及操控，所以下列哪個因素在整體飛行過程中佔了很重要的一部分？","answer":"A","options":[{"key":"A","text":"人為因素。"},{"key":"B","text":"運氣因素。"},{"key":"C","text":"社會因素。"},{"key":"D","text":"歷史因素。"}]},{"id":"chapter-02-007","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"完整之飛控系統包括下列哪個部分？","answer":"D","options":[{"key":"A","text":"感測器。"},{"key":"B","text":"機載計算機。"},{"key":"C","text":"伺服器。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-008","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"完整之飛控系統可實現遙控無人機下列哪項功能？","answer":"D","options":[{"key":"A","text":"姿態穩定和控制。"},{"key":"B","text":"任務管理。"},{"key":"C","text":"緊急控制模式。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-009","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"下列哪個是飛行控制系統的輸入裝置，用以保持控制精度？","answer":"B","options":[{"key":"A","text":"機載計算機。"},{"key":"B","text":"感測器。"},{"key":"C","text":"伺服器。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-010","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"導航系統提供遙控無人機哪項資訊？","answer":"D","options":[{"key":"A","text":"位置。"},{"key":"B","text":"速度。"},{"key":"C","text":"飛行姿態。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-011","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機導航系統主要分為下列哪兩種？","answer":"A","options":[{"key":"A","text":"非自主（如GPS）和自主（慣性導航）。"},{"key":"B","text":"高精度和一般精度。"},{"key":"C","text":"高抗干擾和低抗干擾。"},{"key":"D","text":"全自動和半自動。"}]},{"id":"chapter-02-012","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機非自主（如GPS）導航系統有下列哪個缺點？","answer":"B","options":[{"key":"A","text":"操作困難。"},{"key":"B","text":"易受干擾。"},{"key":"C","text":"誤差積累增大。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-013","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機自主（慣性導航）導航系統有下列哪個缺點？","answer":"C","options":[{"key":"A","text":"操作困難。"},{"key":"B","text":"易受干擾。"},{"key":"C","text":"誤差積累增大。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-014","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機將朝向下列哪個方向繼續發展？","answer":"D","options":[{"key":"A","text":"高精度。"},{"key":"B","text":"高可靠度。"},{"key":"C","text":"高抗干擾。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-015","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機導航與自動避讓系統的發展，包括下列哪項重點？","answer":"D","options":[{"key":"A","text":"慣性導航。"},{"key":"B","text":"多感應器融合、GPS。"},{"key":"C","text":"光電系統技術整合。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-016","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的動力系統，都朝向下列哪個方向發展？","answer":"D","options":[{"key":"A","text":"體積小、重量輕。"},{"key":"B","text":"成本低。"},{"key":"C","text":"可靠度高。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-017","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的能量來源可以包括下列哪項？","answer":"D","options":[{"key":"A","text":"太陽能。"},{"key":"B","text":"氫能。"},{"key":"C","text":"鋰電池。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-018","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"負責對遙控無人機之命令與控制、資料鏈路等工作的，是下列哪個系統？","answer":"B","options":[{"key":"A","text":"動力系統。"},{"key":"B","text":"無線通訊系統。"},{"key":"C","text":"導航系統。"},{"key":"D","text":"飛行控制系統。"}]},{"id":"chapter-02-019","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機控制鏈路為保密與抗干擾基本上已全面採行下列哪種方式？","answer":"C","options":[{"key":"A","text":"類比化。"},{"key":"B","text":"模組化。"},{"key":"C","text":"數位化。"},{"key":"D","text":"離散化。"}]},{"id":"chapter-02-020","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的圖傳主要資料傳輸形態有下列哪幾種方式？","answer":"B","options":[{"key":"A","text":"高速、寬頻。"},{"key":"B","text":"類比、數位。"},{"key":"C","text":"單工、衛星。"},{"key":"D","text":"雙工、衛星。"}]},{"id":"chapter-02-021","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的通訊技術朝向下列哪個方向發展？","answer":"D","options":[{"key":"A","text":"高速、寬頻。"},{"key":"B","text":"保密。"},{"key":"C","text":"抗干擾。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-022","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"隨著機載感測器精度和任務複雜度的上升，機載處理器的下列哪項需求也將隨之提高？","answer":"A","options":[{"key":"A","text":"運算需求。"},{"key":"B","text":"保密需求。"},{"key":"C","text":"抗干擾需求。"},{"key":"D","text":"重量需求。"}]},{"id":"chapter-02-023","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"所謂航空器，係指任何藉空氣之下列哪種力，得以飛航於大氣中之器物？","answer":"C","options":[{"key":"A","text":"摩擦力。"},{"key":"B","text":"靜電力。"},{"key":"C","text":"反作用力。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-024","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機比空氣重，無法只藉由空氣的浮力而上升，需要相對應的下列哪個項目在空中飛行？","answer":"A","options":[{"key":"A","text":"能量。"},{"key":"B","text":"機身外表顏色。"},{"key":"C","text":"起落架材質。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-025","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空器利用噴射推力或是螺旋槳的拉力，使航空器產生下列哪種力而在空中飛行？","answer":"B","options":[{"key":"A","text":"內力。"},{"key":"B","text":"升力。"},{"key":"C","text":"彈力。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-026","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛行速度快、酬載大、飛行效率高，不需太複雜控制，就可自行抵抗氣流而自行保持穩定的飛行的遙控無人機，是下列哪種遙控無人機？","answer":"B","options":[{"key":"A","text":"遙控無人直昇機。"},{"key":"B","text":"遙控無人飛機。"},{"key":"C","text":"遙控無人多旋翼機。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-027","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人飛機缺點是需要有下列哪個項目供起降之用？","answer":"C","options":[{"key":"A","text":"相當的跑道高度。"},{"key":"B","text":"相當的跑道溫度。"},{"key":"C","text":"相當的跑道長度。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-028","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"透過旋翼槳葉產生升力，同時也能產生推力的遙控無人機，是下列哪種遙控無人機？","answer":"A","options":[{"key":"A","text":"遙控無人直昇機。"},{"key":"B","text":"遙控無人飛機。"},{"key":"C","text":"遙控無人多旋翼機。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-029","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機可以執行下列哪個動作？","answer":"D","options":[{"key":"A","text":"自由調整姿態。"},{"key":"B","text":"定點盤旋。"},{"key":"C","text":"起飛與落地。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-030","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"透過三個以上垂直旋翼間協調來控制姿態，同樣不需跑道，可垂直起降、空中懸停等的遙控無人機，是下列哪種遙控無人機？","answer":"A","options":[{"key":"A","text":"無人多旋翼機。"},{"key":"B","text":"無人直昇機。"},{"key":"C","text":"無人飛機。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-031","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作人只要在遙控設備上施加桿力，就可改變遙控無人機的下列哪些性能？","answer":"C","options":[{"key":"A","text":"重量或重心。"},{"key":"B","text":"外形或顏色。"},{"key":"C","text":"方向或速度。"},{"key":"D","text":"翼展與翼弦。"}]},{"id":"chapter-02-032","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若無人飛機在地面上靜止，依牛頓運動定律，下列哪個特性會使得飛機保持靜止？","answer":"A","options":[{"key":"A","text":"慣性。"},{"key":"B","text":"磁性。"},{"key":"C","text":"氣壓。"},{"key":"D","text":"空氣濕度。"}]},{"id":"chapter-02-033","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若無人飛機保持固定的空速以直線行進，依牛頓運動定律，下列哪個特性會使得飛機持續保持穩定的直線飛行？","answer":"C","options":[{"key":"A","text":"磁性。"},{"key":"B","text":"氣壓。"},{"key":"C","text":"慣性。"},{"key":"D","text":"空氣濕度。"}]},{"id":"chapter-02-034","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機於頂風飛行時，地面速度就會有下列哪種變化？","answer":"C","options":[{"key":"A","text":"變快。"},{"key":"B","text":"不變。"},{"key":"C","text":"變慢。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-035","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若風從無人飛機前方的任一方向吹來，倘若飛行員沒有隨之修正，那下列哪個特性就會受到風所施加的力而改變？","answer":"C","options":[{"key":"A","text":"重量。"},{"key":"B","text":"重心。"},{"key":"C","text":"航向。"},{"key":"D","text":"推力。"}]},{"id":"chapter-02-036","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"噴射機將燃燒的熱氣體往後推送以施加作用力，相對的有相等且相反的下列哪種力，將飛機往前推進？","answer":"A","options":[{"key":"A","text":"反作用力。"},{"key":"B","text":"摩擦力。"},{"key":"C","text":"靜電力。"},{"key":"D","text":"磁力。"}]},{"id":"chapter-02-037","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機在空中飛行時，會受到下列哪些力相互作用的影響？","answer":"D","options":[{"key":"A","text":"升力、推力。"},{"key":"B","text":"推力、阻力。"},{"key":"C","text":"阻力、重力。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-038","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機推力由下列哪個組件提供？","answer":"A","options":[{"key":"A","text":"發動機。"},{"key":"B","text":"起落架。"},{"key":"C","text":"機翼。"},{"key":"D","text":"機身。"}]},{"id":"chapter-02-039","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機阻力由下列哪個項目產生？","answer":"C","options":[{"key":"A","text":"地心引力。"},{"key":"B","text":"重心。"},{"key":"C","text":"空氣。"},{"key":"D","text":"發動機。"}]},{"id":"chapter-02-040","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機升力由下列哪個項目提供？","answer":"B","options":[{"key":"A","text":"起落架。"},{"key":"B","text":"機翼。"},{"key":"C","text":"重心。"},{"key":"D","text":"地心引力。"}]},{"id":"chapter-02-041","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"重力由下列哪個項目產生？","answer":"B","options":[{"key":"A","text":"空氣。"},{"key":"B","text":"地心引力。"},{"key":"C","text":"發動機。"},{"key":"D","text":"機翼。"}]},{"id":"chapter-02-042","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛機等速直線飛行時，縱軸(X軸)方向阻力與推力大小相同方向相反，所以有下列哪種情況？","answer":"C","options":[{"key":"A","text":"橫軸(Y軸)方向合力為零，飛機無升降起伏。"},{"key":"B","text":"垂直軸(Z軸)方向合力為零，飛機無偏航的姿態。"},{"key":"C","text":"縱軸(X軸)方向合力為零，飛機速度不變。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-043","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛機高度保持時，垂直軸(Z軸)方向升力與重力大小相同方向相反，所以有下列哪種情況？","answer":"B","options":[{"key":"A","text":"橫軸(Y軸)方向合力為零，飛機無偏航的姿態。"},{"key":"B","text":"垂直軸(Z軸)方向合力為零，飛機無升降起伏。"},{"key":"C","text":"縱軸(X軸)方向合力為零，飛機速度不變。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-044","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"連續性定理闡述了流體在流動中，下列哪些項目之間的關係？","answer":"A","options":[{"key":"A","text":"流速和管道切面。"},{"key":"B","text":"流速和溫度。"},{"key":"C","text":"管道切面和溫度。"},{"key":"D","text":"溫度和壓力。"}]},{"id":"chapter-02-045","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"連續性定理闡述了流體在流動中，流速和管道切面相關，而且下列哪些項目也相關？","answer":"A","options":[{"key":"A","text":"流速和壓力。"},{"key":"B","text":"流速和溫度。"},{"key":"C","text":"管道切面和溫度。"},{"key":"D","text":"溫度和壓力。"}]},{"id":"chapter-02-046","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"柏努利定律說明流體在一個管道中流動時，有下列哪種現象？","answer":"C","options":[{"key":"A","text":"流速大的地方壓力大，流速小的地方壓力小。"},{"key":"B","text":"流速大的地方壓力大，流速小的地方壓力也大。"},{"key":"C","text":"流速大的地方壓力小，流速小的地方壓力大。"},{"key":"D","text":"流速大的地方壓力小，流速小的地方壓力也小。"}]},{"id":"chapter-02-047","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"柏努利定律目的是要闡述流體在流動中時，下列哪些項目間的關係？","answer":"B","options":[{"key":"A","text":"流速和溫度。"},{"key":"B","text":"流速和壓力。"},{"key":"C","text":"溫度和壓力。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-048","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"柏努利定律中提到，如果流體的速度越快，流體中的壓力就會有下列哪種現象？","answer":"A","options":[{"key":"A","text":"越小。"},{"key":"B","text":"越大。"},{"key":"C","text":"不變。"},{"key":"D","text":"有時越小有時越大。"}]},{"id":"chapter-02-049","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的機翼或旋翼是下列哪種外力主要產生的地方？","answer":"B","options":[{"key":"A","text":"阻力。"},{"key":"B","text":"升力。"},{"key":"C","text":"推力。"},{"key":"D","text":"重力。"}]},{"id":"chapter-02-050","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"基於連續性定理、柏努利定律兩個理論，我們可以知道機翼上、下表面會出現下列哪種現象？","answer":"B","options":[{"key":"A","text":"溫度差。"},{"key":"B","text":"壓力差。"},{"key":"C","text":"濕度差。"},{"key":"D","text":"比熱差。"}]},{"id":"chapter-02-051","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"垂直於相對氣流方向的壓力差之總和就是下列哪種外力？","answer":"C","options":[{"key":"A","text":"槳葉本身的攻角設計。"},{"key":"B","text":"空氣的阻力。"},{"key":"C","text":"機翼的升力。"},{"key":"D","text":"地心引力。"}]},{"id":"chapter-02-052","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"螺旋槳產生的推力是藉由下列哪個項目而成？","answer":"C","options":[{"key":"A","text":"槳葉本身的攻角設計。"},{"key":"B","text":"螺旋槳轉速。"},{"key":"C","text":"以上皆是。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-053","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"螺旋槳轉速通常以下列哪個項目來表示？","answer":"B","options":[{"key":"A","text":"每秒徑度（rad/s）。"},{"key":"B","text":"每分鐘轉數（RPM）。"},{"key":"C","text":"赫茲 (Hz)。"},{"key":"D","text":"每分鐘徑度（rad/min）。"}]},{"id":"chapter-02-054","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"一般螺旋槳攻角最大的位置在槳葉的下列哪個位置？","answer":"A","options":[{"key":"A","text":"槳葉根部。"},{"key":"B","text":"槳葉葉尖。"},{"key":"C","text":"槳葉中尖。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-055","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛機螺旋槳在原廠設計時，為了設計出高效率的槳葉角度，係依據發動機及飛機的下列哪些特性做為基礎？","answer":"D","options":[{"key":"A","text":"銷量和價格。"},{"key":"B","text":"耗油量和扭力。"},{"key":"C","text":"壓縮比和衝程。"},{"key":"D","text":"轉速和空速。"}]},{"id":"chapter-02-056","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空器於飛行中，在空氣裡會有下列哪種外力？","answer":"B","options":[{"key":"A","text":"各種彈力。"},{"key":"B","text":"各種阻力。"},{"key":"C","text":"各種磁力。"},{"key":"D","text":"各種正向力。"}]},{"id":"chapter-02-057","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"某外力係與飛機運動方向相反的空氣動力，會阻礙飛機的前進，它是下列哪種外力？","answer":"A","options":[{"key":"A","text":"阻力。"},{"key":"B","text":"升力。"},{"key":"C","text":"重力。"},{"key":"D","text":"推力。"}]},{"id":"chapter-02-058","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"寄生阻力可分為下列哪幾種？","answer":"D","options":[{"key":"A","text":"摩擦阻力。"},{"key":"B","text":"形狀阻力。"},{"key":"C","text":"干擾阻力。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-059","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"對於高速遙控無人機而言，除了摩擦阻力、形狀阻力、誘導阻力和干擾阻力外，還會另外產生下列哪種阻力？","answer":"A","options":[{"key":"A","text":"震波阻力。"},{"key":"B","text":"布斯曼阻力。"},{"key":"C","text":"達倫伯特阻力。"},{"key":"D","text":"雷諾阻力。"}]},{"id":"chapter-02-060","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"下列哪個項目是空氣產生摩擦力的主要物理特性？","answer":"A","options":[{"key":"A","text":"粘性。"},{"key":"B","text":"低汙染。"},{"key":"C","text":"PM2.5。"},{"key":"D","text":"高揮發性。"}]},{"id":"chapter-02-061","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"空氣流經飛機表面發生摩擦，產生一個阻止飛機前進的力，這個力就是下列哪種阻力？","answer":"C","options":[{"key":"A","text":"形狀阻力。"},{"key":"B","text":"誘導阻力。"},{"key":"C","text":"摩擦阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-062","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"摩擦阻力的大小，決定於下列哪個特性？","answer":"D","options":[{"key":"A","text":"空氣的粘性。"},{"key":"B","text":"飛機的表面狀況。"},{"key":"C","text":"同空氣相接觸的飛機表面積。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-063","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"空氣粘性越大，摩擦阻力就會有下列哪種變化？","answer":"B","options":[{"key":"A","text":"越小。"},{"key":"B","text":"越大。"},{"key":"C","text":"不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-064","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛機表面越粗糙，摩擦阻力就會有下列哪種變化？","answer":"C","options":[{"key":"A","text":"越小。"},{"key":"B","text":"不變。"},{"key":"C","text":"越大。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-065","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"飛機表面積越大，摩擦阻力就會有下列哪種變化？","answer":"A","options":[{"key":"A","text":"越大。"},{"key":"B","text":"越小。"},{"key":"C","text":"不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-066","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"由前後壓力差形成的阻力叫下列哪種阻力？","answer":"B","options":[{"key":"A","text":"摩擦阻力。"},{"key":"B","text":"形狀阻力。"},{"key":"C","text":"誘導阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-067","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"人在逆風中行走，會感到阻力的作用，這就是下列哪種阻力？","answer":"C","options":[{"key":"A","text":"摩擦阻力。"},{"key":"B","text":"誘導阻力。"},{"key":"C","text":"形狀阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-068","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人飛機的機身與尾翼接合部分因氣流相互干擾，都會產生下列哪種阻力？","answer":"D","options":[{"key":"A","text":"摩擦阻力。"},{"key":"B","text":"形狀阻力。"},{"key":"C","text":"誘導阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-069","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"因升力產生渦流而發生的阻力稱為下列哪種阻力？","answer":"B","options":[{"key":"A","text":"摩擦阻力。"},{"key":"B","text":"誘導阻力。"},{"key":"C","text":"形狀阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-070","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"誘導阻力是遙控無人機為產生下列哪種外力而須付出的一種代價？","answer":"C","options":[{"key":"A","text":"磁力。"},{"key":"B","text":"推力。"},{"key":"C","text":"升力。"},{"key":"D","text":"重力。"}]},{"id":"chapter-02-071","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"干擾阻力是遙控無人機各部分之間因下列哪種因素而產生的一種額外阻力？","answer":"A","options":[{"key":"A","text":"氣流相互干擾。"},{"key":"B","text":"熱流相互作用。"},{"key":"C","text":"濕度相互作用。"},{"key":"D","text":"磁力相互作用。"}]},{"id":"chapter-02-072","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"干擾阻力容易產生在下列哪些組件之間？","answer":"D","options":[{"key":"A","text":"機身和機翼、機身和尾翼。"},{"key":"B","text":"機翼和外掛載。"},{"key":"C","text":"機翼、發動機短艙。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-073","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"重力是航空器本身之質量所受的下列哪種外力？","answer":"B","options":[{"key":"A","text":"磁力。"},{"key":"B","text":"地心引力。"},{"key":"C","text":"摩擦力。"},{"key":"D","text":"靜電力。"}]},{"id":"chapter-02-074","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"過重的重力對飛行有負面影響，故無人機機身的設計都是採用下列哪種材質？","answer":"A","options":[{"key":"A","text":"較輕。"},{"key":"B","text":"較重。"},{"key":"C","text":"時重時輕。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-075","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"升力和阻力是飛機在空氣之間的下列哪種行為中產生？","answer":"C","options":[{"key":"A","text":"分子光譜。"},{"key":"B","text":"動量守恆。"},{"key":"C","text":"相對運動（相對氣流）。"},{"key":"D","text":"雷諾傳輸。"}]},{"id":"chapter-02-076","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"影響升力和阻力的基本因素除了飛機本身的特點，還有下列哪個因素？","answer":"D","options":[{"key":"A","text":"機翼在氣流中的相對位置（攻角）。"},{"key":"B","text":"氣流的速度。"},{"key":"C","text":"空氣密度。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-077","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"相對氣流方向與翼弦所夾的角度叫下列哪個角？","answer":"C","options":[{"key":"A","text":"俯仰角。"},{"key":"B","text":"滾轉角。"},{"key":"C","text":"攻角。"},{"key":"D","text":"偏航角。"}]},{"id":"chapter-02-078","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"在飛行速度等其它條件相同的情況下，得到最大升力的攻角，叫做下列哪個項目？","answer":"B","options":[{"key":"A","text":"理想攻角。"},{"key":"B","text":"臨界攻角。"},{"key":"C","text":"牛頓攻角。"},{"key":"D","text":"萊布尼茲攻角。"}]},{"id":"chapter-02-079","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"在小於臨界攻角範圍內增大攻角，會有下列哪種結果？","answer":"A","options":[{"key":"A","text":"升力增大。"},{"key":"B","text":"升力減少。"},{"key":"C","text":"升力不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-080","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"空氣密度大，相對氣流速度快，升力和阻力會有下列哪種變化？","answer":"C","options":[{"key":"A","text":"升力越大、阻力越小。"},{"key":"B","text":"升力越小、阻力越大。"},{"key":"C","text":"升力和阻力越大。"},{"key":"D","text":"升力和阻力越小。"}]},{"id":"chapter-02-081","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"機翼面積大，升力和阻力會有下列哪種變化？","answer":"D","options":[{"key":"A","text":"升力越大、阻力越小。"},{"key":"B","text":"升力越小、阻力越大。"},{"key":"C","text":"升力和阻力越小。"},{"key":"D","text":"升力和阻力越大。"}]},{"id":"chapter-02-082","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"升力和阻力與機翼面積大小的關係是下列哪種？","answer":"A","options":[{"key":"A","text":"都與機翼面積大小成正比。"},{"key":"B","text":"都與機翼面積大小成反比。"},{"key":"C","text":"都與機翼面積大小的平方成正比。"},{"key":"D","text":"都與機翼面積大小的平方成反比。"}]},{"id":"chapter-02-083","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"機翼形狀對下列哪個項目有很大影響？","answer":"B","options":[{"key":"A","text":"磁力。"},{"key":"B","text":"升力、阻力。"},{"key":"C","text":"重力。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-084","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"下列哪個項目對升力、阻力有影響？","answer":"D","options":[{"key":"A","text":"機翼切面形狀的相對厚度、最大厚度位置。"},{"key":"B","text":"機翼平面形狀、襟翼和前緣翼縫的位置。"},{"key":"C","text":"機翼表面光滑狀況。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-085","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機表面光滑狀況會影響下列哪種阻力？","answer":"C","options":[{"key":"A","text":"形狀阻力。"},{"key":"B","text":"誘導阻力。"},{"key":"C","text":"摩擦阻力。"},{"key":"D","text":"干擾阻力。"}]},{"id":"chapter-02-086","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機表面相對光滑，則阻力為下列哪種變化？","answer":"A","options":[{"key":"A","text":"相對較小。"},{"key":"B","text":"相對較大。"},{"key":"C","text":"時大時小。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-087","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"大多數遙控無人機都由下列哪個主要部分組成？","answer":"D","options":[{"key":"A","text":"機翼、機身、尾翼。"},{"key":"B","text":"起降裝置。"},{"key":"C","text":"動力系統。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-088","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機機翼的主要功用是產生下列哪種外力？","answer":"B","options":[{"key":"A","text":"阻力。"},{"key":"B","text":"升力。"},{"key":"C","text":"推力。"},{"key":"D","text":"重力。"}]},{"id":"chapter-02-089","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機機翼除提供升力外，也有下列哪些作用？","answer":"C","options":[{"key":"A","text":"美觀和舒適。"},{"key":"B","text":"潤滑和保濕。"},{"key":"C","text":"穩定和操作。"},{"key":"D","text":"觀測和定位。"}]},{"id":"chapter-02-090","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"在無人飛機機翼上一般安裝下列哪個物件？","answer":"B","options":[{"key":"A","text":"光學酬載。"},{"key":"B","text":"副翼和襟翼。"},{"key":"C","text":"通訊設備。"},{"key":"D","text":"導航設備。"}]},{"id":"chapter-02-091","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操縱無人飛機副翼可使飛機產生下列哪種結果？","answer":"A","options":[{"key":"A","text":"滾轉。"},{"key":"B","text":"爬升。"},{"key":"C","text":"下降。"},{"key":"D","text":"偏航。"}]},{"id":"chapter-02-092","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機機翼還可安裝下列哪個物件？","answer":"D","options":[{"key":"A","text":"發動機。"},{"key":"B","text":"起落架。"},{"key":"C","text":"外掛載。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-093","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機機身的主要功用是裝載下列哪個物件？","answer":"D","options":[{"key":"A","text":"油箱。"},{"key":"B","text":"酬載。"},{"key":"C","text":"各種設備。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-094","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機尾翼包括下列哪些物件？","answer":"C","options":[{"key":"A","text":"大尾翼和小尾翼。"},{"key":"B","text":"高速尾翼和低速尾翼。"},{"key":"C","text":"水平尾翼和垂直尾翼。"},{"key":"D","text":"旋轉尾翼和固定尾翼。"}]},{"id":"chapter-02-095","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機水平尾翼包括下列哪些物件？","answer":"B","options":[{"key":"A","text":"固定的升降舵和可動的水平安定面。"},{"key":"B","text":"固定的水平安定面和可動的升降舵。"},{"key":"C","text":"固定的升降舵和水平安定面。"},{"key":"D","text":"可動的升降舵和水平安定面。"}]},{"id":"chapter-02-096","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機垂直尾翼包括下列哪些物件？","answer":"B","options":[{"key":"A","text":"固定的方向舵和可動的垂直安定面。"},{"key":"B","text":"固定的垂直安定面和可動的方向舵。"},{"key":"C","text":"固定的方向舵和垂直安定面。"},{"key":"D","text":"可動的方向舵和垂直安定面。"}]},{"id":"chapter-02-097","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機的起落架大都由下列哪些物件組成？","answer":"A","options":[{"key":"A","text":"減震支柱和機輪。"},{"key":"B","text":"蒙皮和鉚釘。"},{"key":"C","text":"坡頂桁架和平行弦桁架。"},{"key":"D","text":"拉力元件和扭力元件。"}]},{"id":"chapter-02-098","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"起落架的作用是在下列哪個時機支撐無人飛機?","answer":"D","options":[{"key":"A","text":"起飛時。"},{"key":"B","text":"著陸滑跑時。"},{"key":"C","text":"地面滑行和停放時。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-099","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"動力系統主要用來產生使遙控無人機前進的下列哪些力？","answer":"C","options":[{"key":"A","text":"重力與升力。"},{"key":"B","text":"重力與阻力。"},{"key":"C","text":"拉力和推力。"},{"key":"D","text":"升力與阻力。"}]},{"id":"chapter-02-100","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機常見的動力系統有下列哪個項目？","answer":"D","options":[{"key":"A","text":"航空活塞式發動機加螺旋槳推進器。"},{"key":"B","text":"渦輪噴氣發動機。"},{"key":"C","text":"渦輪螺旋槳發動機和渦輪扇或導風扇發動機。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-101","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機上通常不會安裝下列哪種設備？","answer":"A","options":[{"key":"A","text":"飛行儀表。"},{"key":"B","text":"通訊設備、導航設備。"},{"key":"C","text":"安全設備。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-102","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作人操作油門和操縱桿，控制無人機的操縱面，來達到所想要的下列哪個目的？","answer":"A","options":[{"key":"A","text":"飛行姿態。"},{"key":"B","text":"發動機溫度。"},{"key":"C","text":"環境濕度。"},{"key":"D","text":"酬載功能。"}]},{"id":"chapter-02-103","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"想像為一條由前往後穿過航空器的軸，稱之為下列哪個軸？","answer":"A","options":[{"key":"A","text":"航空器縱軸（X軸）。"},{"key":"B","text":"航空器橫軸（Y軸）。"},{"key":"C","text":"航空器垂直軸（Z軸）。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-104","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"除了副翼，航空器的下列哪個組件對於航空器的滾轉也會有影響？","answer":"C","options":[{"key":"A","text":"升降舵。"},{"key":"B","text":"襟翼。"},{"key":"C","text":"方向舵。"},{"key":"D","text":"小翼。"}]},{"id":"chapter-02-105","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"想像為一條上下兩面垂直地穿過航空器的軸，稱之為下列哪個軸？","answer":"A","options":[{"key":"A","text":"航空器垂直軸（Z軸）。"},{"key":"B","text":"航空器縱軸（X軸）。"},{"key":"C","text":"航空器橫軸（Y軸）。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-106","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"關於遙控無人機的的操作原理，我們首要了解遙控無人飛機的下列哪種特性？","answer":"D","options":[{"key":"A","text":"平衡性。"},{"key":"B","text":"穩定性。"},{"key":"C","text":"操縱性。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-107","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機處於平衡狀態時，是表示下列哪種狀況？","answer":"A","options":[{"key":"A","text":"其速度的大小和方向都保持不變。"},{"key":"B","text":"其發動機的轉速和馬力都保持不變。"},{"key":"C","text":"其所有翼面的角度和方向都保持不變。"},{"key":"D","text":"其酬載的方向和功能都保持不變。"}]},{"id":"chapter-02-108","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機穩定性的強弱，一般由下列哪個現象來衡量？","answer":"D","options":[{"key":"A","text":"擺動衰減時間。"},{"key":"B","text":"擺動幅度。"},{"key":"C","text":"擺動次數。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-109","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的穩定性強，表示下列哪個現象？","answer":"D","options":[{"key":"A","text":"擺動衰減時間短。"},{"key":"B","text":"擺動幅度小。"},{"key":"C","text":"擺動次數少。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-110","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機穩定性的強弱，主要取決於遙控無人機的下列哪個特性？","answer":"D","options":[{"key":"A","text":"重心位置。"},{"key":"B","text":"飛行速度和高度。"},{"key":"C","text":"攻角的變化。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-111","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機在操作人操縱升降舵、方向舵和副翼下改變其飛行狀態的俯仰、方向和橫向之特性，是指遙控無人機的下列哪種特性？","answer":"A","options":[{"key":"A","text":"操縱性。"},{"key":"B","text":"平衡性。"},{"key":"C","text":"穩定性。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-112","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機操縱性好，表示下列哪個現象？","answer":"D","options":[{"key":"A","text":"操縱動作簡單。"},{"key":"B","text":"操縱省力。"},{"key":"C","text":"操縱反應快。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-113","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機操作有哪四大基本動作？","answer":"C","options":[{"key":"A","text":"平直飛行、側滑、爬升、下降。"},{"key":"B","text":"平直飛行、轉彎、爬升、倒飛。"},{"key":"C","text":"平直飛行、轉彎、爬升、下降。"},{"key":"D","text":"平直飛行、側滑、懸停、倒飛。"}]},{"id":"chapter-02-114","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作遙控無人飛機時，當副翼控制右上左下，機體相對於「機體中心」作下列哪種動作？","answer":"C","options":[{"key":"A","text":"向上俯仰。"},{"key":"B","text":"右偏航。"},{"key":"C","text":"右滾。"},{"key":"D","text":"左滾。"}]},{"id":"chapter-02-115","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作遙控無人飛機時，當副翼控制右下左上，機體相對於「機體中心」作下列哪種動作？","answer":"C","options":[{"key":"A","text":"向上俯仰。"},{"key":"B","text":"右偏航。"},{"key":"C","text":"左滾。"},{"key":"D","text":"右滾。"}]},{"id":"chapter-02-116","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作遙控無人飛機時，當方向舵控制往右，機體相對於「機體中心」作下列哪種動作？","answer":"B","options":[{"key":"A","text":"向上俯仰。"},{"key":"B","text":"右偏航。"},{"key":"C","text":"左偏航。"},{"key":"D","text":"右滾。"}]},{"id":"chapter-02-117","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作遙控無人飛機時，當方向舵控制往左，機體相對於「機體中心」作下列哪種動作？","answer":"B","options":[{"key":"A","text":"右滾。"},{"key":"B","text":"左偏航。"},{"key":"C","text":"右偏航。"},{"key":"D","text":"左滾。"}]},{"id":"chapter-02-118","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"控制遙控無人機時，操作人應以相對於下列哪個項目來思考「上」、「下」、「左」、「右」？","answer":"A","options":[{"key":"A","text":"機體中心。"},{"key":"B","text":"地平面。"},{"key":"C","text":"操作人自己的虛擬座標。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-119","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機，其主旋翼在旋轉時主要產生下列哪種力？","answer":"A","options":[{"key":"A","text":"向上的升力。"},{"key":"B","text":"向下的升力。"},{"key":"C","text":"向前的升力。"},{"key":"D","text":"向後的升力。"}]},{"id":"chapter-02-120","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機主旋翼產生升力的原理，類似於下列哪個原理？","answer":"C","options":[{"key":"A","text":"無人飛機機翼產生升力的原理。"},{"key":"B","text":"螺旋槳產生推力的原理。"},{"key":"C","text":"以上皆是。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-121","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若無人直昇機主旋翼的旋轉面保持在水平位置，則所產生的力是下列哪個方向？","answer":"B","options":[{"key":"A","text":"垂直向下。"},{"key":"B","text":"垂直向上。"},{"key":"C","text":"傾斜向下。"},{"key":"D","text":"傾斜向上。"}]},{"id":"chapter-02-122","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機利用主旋翼產生升力的原理執行下列哪些動作？","answer":"D","options":[{"key":"A","text":"起飛離地。"},{"key":"B","text":"爬升。"},{"key":"C","text":"懸停。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-123","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"如果升力與推力大於重力與阻力，遙控無人機的運動方向是下列哪個方向？","answer":"A","options":[{"key":"A","text":"垂直向上。"},{"key":"B","text":"垂直向下。"},{"key":"C","text":"傾斜向上。"},{"key":"D","text":"傾斜向下。"}]},{"id":"chapter-02-124","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機主旋翼的槳葉片的俯仰角愈大，就會有下列哪種情形？","answer":"B","options":[{"key":"A","text":"升力愈大，扭力愈小。"},{"key":"B","text":"升力愈大，扭力也愈大。"},{"key":"C","text":"升力愈小，也扭力愈小。"},{"key":"D","text":"升力愈小，扭力愈大。"}]},{"id":"chapter-02-125","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機的尾旋翼主要功能為何？","answer":"C","options":[{"key":"A","text":"抵消升力，控制機頭方向。"},{"key":"B","text":"抵消阻力，控制機頭方向。"},{"key":"C","text":"抵消扭力，控制機頭方向。"},{"key":"D","text":"抵消重力，控制機頭方向。"}]},{"id":"chapter-02-126","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機有下列哪些基本飛行動作？","answer":"D","options":[{"key":"A","text":"平直飛行。"},{"key":"B","text":"轉彎。"},{"key":"C","text":"爬升及下降。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-127","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「垂直起飛到懸停」，係指垂直飛離地面約2~3呎，並保持下列哪種狀態？","answer":"A","options":[{"key":"A","text":"航向不變。"},{"key":"B","text":"向左的傾斜狀態。"},{"key":"C","text":"向右的傾斜狀態。"},{"key":"D","text":"主旋翼轉速不變。"}]},{"id":"chapter-02-128","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「懸停轉彎」，係指在懸停高度執行機鼻向左轉或向右轉，並保持下列哪種狀態不變？","answer":"B","options":[{"key":"A","text":"相對於其他遙控無人直昇機的位置。"},{"key":"B","text":"相對於地面的位置。"},{"key":"C","text":"相對於最低雲層的位置。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-129","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「懸停轉彎」，係指保持不變的下列哪種狀態？","answer":"D","options":[{"key":"A","text":"高度。"},{"key":"B","text":"轉彎率。"},{"key":"C","text":"轉速。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-130","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機向前移動到另一特定位置，稱之為無人直昇機的下列哪種動作？","answer":"C","options":[{"key":"A","text":"懸停。"},{"key":"B","text":"側向懸停飛行。"},{"key":"C","text":"向前懸停飛行。"},{"key":"D","text":"向後懸停飛行。"}]},{"id":"chapter-02-131","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「向前懸停飛行」，係指保持不變的下列哪種狀態？","answer":"D","options":[{"key":"A","text":"地面速度。"},{"key":"B","text":"高度。"},{"key":"C","text":"航向。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-132","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當必須移動無人直昇機到另一特定位置，但當時狀況不可能執行向前飛行時，就要使用下列哪種動作？","answer":"A","options":[{"key":"A","text":"側向懸停飛行或向後懸停飛行。"},{"key":"B","text":"懸停轉彎。"},{"key":"C","text":"平直飛行。"},{"key":"D","text":"懸停。"}]},{"id":"chapter-02-133","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「側向懸停飛行」，係指保持不變的下列哪種狀態？","answer":"D","options":[{"key":"A","text":"地面速度。"},{"key":"B","text":"高度。"},{"key":"C","text":"航向。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-134","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當必須移動無人直昇機到另一特定位置，但當時狀況不可能執行向前或側向懸停飛行時，就要使用下列哪種動作？","answer":"B","options":[{"key":"A","text":"平直飛行。"},{"key":"B","text":"向後懸停飛行。"},{"key":"C","text":"懸停轉彎。"},{"key":"D","text":"傾斜轉彎。"}]},{"id":"chapter-02-135","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「向後懸停飛行」，係指保持不變的下列哪種狀態？","answer":"D","options":[{"key":"A","text":"地面速度。"},{"key":"B","text":"高度。"},{"key":"C","text":"航向。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-136","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「平直飛行」，係指保持下列哪種狀態？","answer":"A","options":[{"key":"A","text":"高度不變和航向不變。"},{"key":"B","text":"高度不變和地面速度不變。"},{"key":"C","text":"地面速度不變和航向不變。"},{"key":"D","text":"主旋翼轉速不變和航向不變。"}]},{"id":"chapter-02-137","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「傾斜轉彎」，係指保持在向左或向右的傾斜狀態，保持下列哪種狀態之飛行？","answer":"C","options":[{"key":"A","text":"高度不變和航向不變。"},{"key":"B","text":"高度改變，但航向不變。"},{"key":"C","text":"高度不變，但航向改變。"},{"key":"D","text":"高度改變和航向改變。"}]},{"id":"chapter-02-138","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「偏航」，係指利用尾旋翼推力執行下列哪種操縱？","answer":"B","options":[{"key":"A","text":"改變高度。"},{"key":"B","text":"改變航向。"},{"key":"C","text":"改變地面速度。"},{"key":"D","text":"改變升力。"}]},{"id":"chapter-02-139","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機可以下列哪種方式來做區分？","answer":"D","options":[{"key":"A","text":"旋翼數量。"},{"key":"B","text":"旋翼分布位置。"},{"key":"C","text":"旋翼是否能夠傾斜。"},{"key":"D","text":"以上皆可。"}]},{"id":"chapter-02-140","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機能夠垂直且穩定的執行下列哪種動作？","answer":"B","options":[{"key":"A","text":"滾轉及水平平移。"},{"key":"B","text":"升降及偏航。"},{"key":"C","text":"偏航及水平平移。"},{"key":"D","text":"俯仰及水平平移。"}]},{"id":"chapter-02-141","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機具備優秀的下列哪種能力是一般無人飛機望塵莫及的？","answer":"D","options":[{"key":"A","text":"垂直起降能力。"},{"key":"B","text":"定點懸停能力。"},{"key":"C","text":"穩定升降及偏航。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-142","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機的下列哪種旋翼設計使得操控簡單且直接？","answer":"B","options":[{"key":"A","text":"參差配置的。"},{"key":"B","text":"對稱的。"},{"key":"C","text":"不對稱的。"},{"key":"D","text":"偏一邊的。"}]},{"id":"chapter-02-143","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"定距槳無人多旋翼機與無人直昇機相比，在下列哪個方面有很大提升？","answer":"D","options":[{"key":"A","text":"機械設計結構。"},{"key":"B","text":"控制難度。"},{"key":"C","text":"姿態平穩。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-144","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機對飛行的影響是下列哪項？","answer":"C","options":[{"key":"A","text":"沒有影響。"},{"key":"B","text":"變得複雜。"},{"key":"C","text":"變得簡單。"},{"key":"D","text":"有時變得複雜，有時變得簡單。"}]},{"id":"chapter-02-145","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機同時增加或減少每個旋翼的升力，來實現下列哪種飛行狀態？","answer":"A","options":[{"key":"A","text":"垂直的升降姿態。"},{"key":"B","text":"俯仰的姿態。"},{"key":"C","text":"偏航的姿態。"},{"key":"D","text":"滾轉的姿態。"}]},{"id":"chapter-02-146","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"同時影響遙控無人機飛行性能與飛航安全的重要因素是下列哪些項目？","answer":"C","options":[{"key":"A","text":"機體大小。"},{"key":"B","text":"電池容量。"},{"key":"C","text":"重量和重心位置。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-147","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作人在飛行前應確認下列何者在合理範圍內？","answer":"D","options":[{"key":"A","text":"重量。"},{"key":"B","text":"重心。"},{"key":"C","text":"酬載。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-148","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機操作人在飛行前應詳細考量在下列哪種情況下可能降低飛行性能的載重因素？","answer":"D","options":[{"key":"A","text":"高海拔。"},{"key":"B","text":"高溫。"},{"key":"C","text":"高濕度。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-149","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重力的著力點稱為下列哪個項目？","answer":"C","options":[{"key":"A","text":"形心。"},{"key":"B","text":"氣動力中心。"},{"key":"C","text":"重心。"},{"key":"D","text":"升力中心。"}]},{"id":"chapter-02-150","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的下列哪個項目與穩定性有很大的關聯？","answer":"B","options":[{"key":"A","text":"外觀。"},{"key":"B","text":"重心。"},{"key":"C","text":"大小。"},{"key":"D","text":"顏色。"}]},{"id":"chapter-02-151","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當遙控無人機重心位置超出允許範圍時，可能導致遙控無人機發生下列哪種情形？","answer":"D","options":[{"key":"A","text":"無法穩定起飛。"},{"key":"B","text":"無法穩定落地。"},{"key":"C","text":"失速。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-152","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機飛行時，為產生各種姿態，作用於機身上的力為下列哪種情形？","answer":"A","options":[{"key":"A","text":"升力通常較重量為大。"},{"key":"B","text":"升力通常較重量為小。"},{"key":"C","text":"有時升力較大，有時重量較大。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-153","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機的轉彎率因不同的速度而隨之不同，這是為了要抵銷所增加的下列哪種力，以保持負載係數不變？","answer":"B","options":[{"key":"A","text":"向心力。"},{"key":"B","text":"離心力。"},{"key":"C","text":"正向力。"},{"key":"D","text":"扭力。"}]},{"id":"chapter-02-154","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機轉彎時，需執行下列哪個動作以補償升力的不足？","answer":"B","options":[{"key":"A","text":"增加正向力。"},{"key":"B","text":"增加攻角。"},{"key":"C","text":"增加扭力。"},{"key":"D","text":"增加離心力。"}]},{"id":"chapter-02-155","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，為維持遙控無人機的俯仰平衡，需要尾翼提供下列哪種力？","answer":"C","options":[{"key":"A","text":"更大的向前的推力。"},{"key":"B","text":"更大的向上的升力。"},{"key":"C","text":"更大的向下的升力。"},{"key":"D","text":"更大的向外的離心力。"}]},{"id":"chapter-02-156","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重心位置靠前時，機頭較為沉重，起飛離地時有下列哪種情形？","answer":"A","options":[{"key":"A","text":"較為困難。"},{"key":"B","text":"較為容易。"},{"key":"C","text":"有時容易有時困難。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-157","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，會有下列哪種情形？","answer":"B","options":[{"key":"A","text":"減少誘導阻力。"},{"key":"B","text":"增大誘導阻力。"},{"key":"C","text":"誘導阻力不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-158","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，會有下列哪種情形？","answer":"C","options":[{"key":"A","text":"油耗增加。"},{"key":"B","text":"航程距離降低。"},{"key":"C","text":"以上皆是。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-159","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，提高了下列哪種風險？","answer":"A","options":[{"key":"A","text":"不穩定進場的風險。"},{"key":"B","text":"穩定進場的風險。"},{"key":"C","text":"非精確進場的風險。"},{"key":"D","text":"精確進場的風險。"}]},{"id":"chapter-02-160","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心後移時，由於機頭較輕，可能會使得起飛時發生下列哪種情形？","answer":"C","options":[{"key":"A","text":"偏離跑道。"},{"key":"B","text":"左右搖擺。"},{"key":"C","text":"提前仰轉。"},{"key":"D","text":"延後離地。"}]},{"id":"chapter-02-161","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心後移時，起飛爬升時可能會因仰角過大，而造成下列哪種情形？","answer":"C","options":[{"key":"A","text":"起飛速度增加。"},{"key":"B","text":"起飛重量降低。"},{"key":"C","text":"失速與機尾擦地。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-162","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心後移時，配平及總阻力減小，也進而導致下列哪種情形？","answer":"D","options":[{"key":"A","text":"油耗減少。"},{"key":"B","text":"續航能力增加。"},{"key":"C","text":"失速速度減小。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-163","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機重心太靠後，會影響下列哪種性能？","answer":"A","options":[{"key":"A","text":"高速前飛性能及穩定。"},{"key":"B","text":"從地面到正常起飛。"},{"key":"C","text":"平直飛行。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-164","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機重心移動可能造成下列哪種結果？","answer":"B","options":[{"key":"A","text":"升力增加。"},{"key":"B","text":"操控較為困難。"},{"key":"C","text":"阻力減少。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-165","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對起飛速度造成下列哪種結果？","answer":"C","options":[{"key":"A","text":"降低起飛速度。"},{"key":"B","text":"起飛速度不變。"},{"key":"C","text":"提高起飛速度。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-166","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對滑行距離造成下列哪種結果？","answer":"B","options":[{"key":"A","text":"縮短起飛滑行距離。"},{"key":"B","text":"加長起飛滑行距離。"},{"key":"C","text":"起飛滑行距離不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-167","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對爬升率及爬升角造成下列哪種結果？","answer":"A","options":[{"key":"A","text":"降低爬升率和爬升角度。"},{"key":"B","text":"增加爬升率和爬升角度。"},{"key":"C","text":"爬升率和爬升角度不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-168","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對飛航最高高度造成下列哪種結果？","answer":"A","options":[{"key":"A","text":"降低飛航最高高度。"},{"key":"B","text":"增加飛航最高高度。"},{"key":"C","text":"飛航最高高度不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-169","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對操作性能造成下列哪種結果？","answer":"C","options":[{"key":"A","text":"操作性能不變。"},{"key":"B","text":"增加操作性能。"},{"key":"C","text":"降低操作性能。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-170","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對進場及降落速度造成下列哪種結果？","answer":"B","options":[{"key":"A","text":"降低進場和降落速度。"},{"key":"B","text":"提高進場和降落速度。"},{"key":"C","text":"進場和降落速度不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-171","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機重量增加可能對降落滾行距離造成下列哪種結果？","answer":"A","options":[{"key":"A","text":"加長降落滾行距離。"},{"key":"B","text":"縮短降落滾行距離。"},{"key":"C","text":"降落滾行距離不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-172","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"為確保飛行安全，操作人須審慎確認遙控無人機的下列哪個特性？","answer":"B","options":[{"key":"A","text":"外觀。"},{"key":"B","text":"重量與載重平衡。"},{"key":"C","text":"價格。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-173","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"低速、低空的中型無人機的動力裝置，使用下列哪種發動機？","answer":"A","options":[{"key":"A","text":"往復式（活塞）發動機。"},{"key":"B","text":"無刷電動馬達。"},{"key":"C","text":"渦輪螺旋槳發動機。"},{"key":"D","text":"渦輪發動機。"}]},{"id":"chapter-02-174","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"使用於高速無人機上，推重比高但壽命短的動力裝置是下列哪種發動機？","answer":"A","options":[{"key":"A","text":"渦輪發動機。"},{"key":"B","text":"無刷電動馬達。"},{"key":"C","text":"渦輪螺旋槳發動機。"},{"key":"D","text":"往復式（活塞）發動機。"}]},{"id":"chapter-02-175","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"高空或長滯空的大型無人機的動力裝置，使用下列哪種發動機？","answer":"C","options":[{"key":"A","text":"渦輪發動機。"},{"key":"B","text":"無刷電動馬達。"},{"key":"C","text":"渦輪風扇或渦輪螺旋槳發動機。"},{"key":"D","text":"往復式（活塞）發動機。"}]},{"id":"chapter-02-176","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"娛樂/運動級航空模型或小型無人機的動力裝置，一般使用下列哪種發動機？","answer":"B","options":[{"key":"A","text":"渦輪發動機。"},{"key":"B","text":"無刷電動馬達。"},{"key":"C","text":"渦輪風扇或渦輪螺旋槳發動機。"},{"key":"D","text":"往復式（活塞）發動機。"}]},{"id":"chapter-02-177","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"隨著渦輪發動機推重比、壽命不斷提高、油耗降低，未來渦輪發動機可能取代下列哪種發動機成為25公斤至150公斤級的無人機之主要動力？","answer":"D","options":[{"key":"A","text":"無刷電動馬達。"},{"key":"B","text":"渦輪風扇發動機。"},{"key":"C","text":"渦輪螺旋槳發動機。"},{"key":"D","text":"活塞發動機。"}]},{"id":"chapter-02-178","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"一般遙控無人機目前多以下列哪些頻段進行控制與圖傳？","answer":"C","options":[{"key":"A","text":"300MHz或500MHz。"},{"key":"B","text":"500MHz或600MHz。"},{"key":"C","text":"2.4GHz或5.8GHz。"},{"key":"D","text":"100GHz或220GHz。"}]},{"id":"chapter-02-179","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"頻段2.4GHz主要為下列哪種鏈路實現對遙控無人機控制？","answer":"B","options":[{"key":"A","text":"下行鏈路。"},{"key":"B","text":"上行控制鏈路。"},{"key":"C","text":"加密鏈路。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-180","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"頻段5.8GHz主要為下列哪種鏈路執行圖像或數據傳輸等遙測功能？","answer":"A","options":[{"key":"A","text":"下行鏈路。"},{"key":"B","text":"上行控制鏈路。"},{"key":"C","text":"加密鏈路。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-181","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若無外力的影響，靜止的物體會保持靜止，行進的物體會保持直線運動，這就是下列哪個定律？","answer":"C","options":[{"key":"A","text":"牛頓第二定律又稱「加速度定律」。"},{"key":"B","text":"牛頓第三定律。"},{"key":"C","text":"牛頓第一定律又稱「慣性定律」。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-182","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當物體受到所施加的力等於每次的動量變化，這就是下列哪個定律？","answer":"B","options":[{"key":"A","text":"牛頓第一定律又稱「慣性定律」。"},{"key":"B","text":"牛頓第二定律又稱「加速度定律」。"},{"key":"C","text":"牛頓第三定律。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-183","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"牛頓第二定律說明加速度與物體的質量為下列哪種關係？","answer":"A","options":[{"key":"A","text":"成反比。"},{"key":"B","text":"成正比。"},{"key":"C","text":"沒有關係。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-184","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"牛頓第二定律說明加速度與所施加的力為下列哪種關係？","answer":"B","options":[{"key":"A","text":"成反比。"},{"key":"B","text":"成正比。"},{"key":"C","text":"沒有關係。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-185","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"對於每一個作用力，都有一個相等且相反的反作用力，這就是下列哪個定律？","answer":"B","options":[{"key":"A","text":"牛頓第一定律又稱「慣性定律」。"},{"key":"B","text":"牛頓第三定律。"},{"key":"C","text":"牛頓第二定律又稱「加速度定律」。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-186","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"下列哪些理論可以說明一個重於空氣的航空器如何產生升力飛行於空中？","answer":"A","options":[{"key":"A","text":"流體的連續性和柏努利定律。"},{"key":"B","text":"氣候學和大氣化學。"},{"key":"C","text":"大氣動力學和大氣物理學。"},{"key":"D","text":"材料力學和運動學。"}]},{"id":"chapter-02-187","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"流體的連續性說明在同一時間內，流進任一切面和從另一切面流出的下列哪個項目是相等的？","answer":"C","options":[{"key":"A","text":"流體溫度。"},{"key":"B","text":"流體壓力。"},{"key":"C","text":"流體質量。"},{"key":"D","text":"流體速度。"}]},{"id":"chapter-02-188","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"由螺旋槳所產生的拉力或噴射發動機所產生的推力，使航空器前進飛行，是依據下列哪個定律？","answer":"A","options":[{"key":"A","text":"牛頓第三定律。"},{"key":"B","text":"牛頓第一定律。"},{"key":"C","text":"牛頓第二定律。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-189","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"若螺旋槳整片槳葉的攻角都一樣，將使得槳葉的效率有下列哪種變化？","answer":"C","options":[{"key":"A","text":"變得很好。"},{"key":"B","text":"保持不變。"},{"key":"C","text":"變得很差。"},{"key":"D","text":"機時好時差。"}]},{"id":"chapter-02-190","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"超過臨界攻角後，再增大攻角，會有下列哪種結果？","answer":"A","options":[{"key":"A","text":"升力反而減小，阻力急劇增大。"},{"key":"B","text":"升力持續增大，阻力急劇減小。"},{"key":"C","text":"升力、阻力持續增大。"},{"key":"D","text":"升力、阻力急劇減小。"}]},{"id":"chapter-02-191","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"升力和阻力兩者與飛行速度的關係是下列哪種？","answer":"C","options":[{"key":"A","text":"均與飛行速度成正比。"},{"key":"B","text":"均與飛行速度成反比。"},{"key":"C","text":"均與飛行速度的平方成正比。"},{"key":"D","text":"均與飛行速度的平方成反比。"}]},{"id":"chapter-02-192","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"放下遙控無人飛機襟翼可產生下列哪種結果？","answer":"A","options":[{"key":"A","text":"使升力增大。"},{"key":"B","text":"使升力減少。"},{"key":"C","text":"使升力不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-193","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"尾翼的作用是操縱無人飛機的下列哪些動作？","answer":"C","options":[{"key":"A","text":"俯仰和滾轉。"},{"key":"B","text":"滾轉和偏航。"},{"key":"C","text":"俯仰和偏航。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-194","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空器主要係利用副翼改變下列哪種姿態？","answer":"B","options":[{"key":"A","text":"俯仰。"},{"key":"B","text":"左右滾轉。"},{"key":"C","text":"偏航。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-195","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"想像為一條左右兩側穿過航空器的軸，稱之為下列哪個軸？","answer":"C","options":[{"key":"A","text":"航空器縱軸（X軸）。"},{"key":"B","text":"航空器垂直軸（Z軸）。"},{"key":"C","text":"航空器橫軸（Y軸）。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-196","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空器利用升降舵改變下列哪種姿態？","answer":"B","options":[{"key":"A","text":"左右滾轉。"},{"key":"B","text":"俯仰。"},{"key":"C","text":"偏航。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-197","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空器利用方向舵改變下列哪種姿態？","answer":"B","options":[{"key":"A","text":"俯仰。"},{"key":"B","text":"偏航。"},{"key":"C","text":"左右滾轉。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-198","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"作用於遙控無人機的各外力之和、各力矩之和都為零，是指遙控無人機的下列哪種特性？","answer":"C","options":[{"key":"A","text":"穩定性。"},{"key":"B","text":"操縱性。"},{"key":"C","text":"平衡性。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-199","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當遙控無人機受到微小擾動而偏離原來的平衡狀態時，在擾動消失後，不經操作人操縱，自動恢復原來平衡狀態的特性，是指遙控無人機的下列哪種特性？","answer":"B","options":[{"key":"A","text":"平衡性。"},{"key":"B","text":"穩定性。"},{"key":"C","text":"操縱性。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-200","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作無人飛機時，當升降舵控制往上，相對於「機體中心」作下列哪種動作？","answer":"B","options":[{"key":"A","text":"向下俯仰。"},{"key":"B","text":"向上俯仰。"},{"key":"C","text":"右滾。"},{"key":"D","text":"左滾。"}]},{"id":"chapter-02-201","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"操作無人飛機時，當升降舵控制往下，飛機相對於「機體中心」作下列哪種動作？","answer":"A","options":[{"key":"A","text":"向下俯仰。"},{"key":"B","text":"向上俯仰。"},{"key":"C","text":"右滾。"},{"key":"D","text":"左滾。"}]},{"id":"chapter-02-202","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當無人直昇機的發動機讓主旋翼以逆時針方向旋轉時，無人直昇機本身將以下列哪個方向旋轉？","answer":"A","options":[{"key":"A","text":"以順時針方向旋轉。"},{"key":"B","text":"以逆時針方向旋轉。"},{"key":"C","text":"先以順時針方向旋轉，再以逆時針方向旋轉。"},{"key":"D","text":"先以逆時針方向旋轉，再以順時針方向旋轉。"}]},{"id":"chapter-02-203","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機為了抵銷扭力，在設計上使用尾旋翼在機尾產生一個向右的力，稱為下列哪種力？","answer":"C","options":[{"key":"A","text":"尾旋翼升力。"},{"key":"B","text":"尾旋翼阻力。"},{"key":"C","text":"尾旋翼推力。"},{"key":"D","text":"尾旋翼壓力。"}]},{"id":"chapter-02-204","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「懸停」，係指保持幾乎不動的飛行，並保持下列哪種狀態？","answer":"B","options":[{"key":"A","text":"主旋翼轉速不變和航向不變。"},{"key":"B","text":"高度不變和航向不變。"},{"key":"C","text":"主旋翼轉速不變和高度不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-205","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「從懸停到正常起飛」，係指有順序的轉換到向前飛行，執行時應安全且迅速的採取下列哪種動作？","answer":"C","options":[{"key":"A","text":"改變航向。"},{"key":"B","text":"增加地面速度。"},{"key":"C","text":"增加高度。"},{"key":"D","text":"增加主旋翼轉速。"}]},{"id":"chapter-02-206","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機「從地面到正常起飛」，係指使用下列哪個動作，將直昇機從地面移動到有效轉換升力及正常爬升？","answer":"A","options":[{"key":"A","text":"最小的所需動力。"},{"key":"B","text":"最大的所需動力。"},{"key":"C","text":"最小的地面速度。"},{"key":"D","text":"最大的地面速度。"}]},{"id":"chapter-02-207","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機是一種經由多個定距槳的正反旋轉與轉速控制，提供下列哪些性能調整？","answer":"C","options":[{"key":"A","text":"阻力與推力調整。"},{"key":"B","text":"重心與阻力調整。"},{"key":"C","text":"升力與姿態調整。"},{"key":"D","text":"升力與重心調整。"}]},{"id":"chapter-02-208","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機旋翼以不同方向旋轉，抵消反作用力，使產生下列哪項結果？","answer":"A","options":[{"key":"A","text":"使總力矩為零。"},{"key":"B","text":"使總推力為零。"},{"key":"C","text":"使總升力為零。"},{"key":"D","text":"使總阻力為零。"}]},{"id":"chapter-02-209","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機可以直接採用下列哪種螺旋槳？","answer":"A","options":[{"key":"A","text":"定距槳。"},{"key":"B","text":"變距槳。"},{"key":"C","text":"恆速槳。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-210","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機改變前後兩端旋翼的升力，使之不平衡，來實現下列哪種姿態？","answer":"B","options":[{"key":"A","text":"垂直的升降姿態。"},{"key":"B","text":"俯仰的姿態。"},{"key":"C","text":"偏航的姿態。"},{"key":"D","text":"滾轉的姿態。"}]},{"id":"chapter-02-211","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機同時減少或增加斜對角兩對旋翼轉速與升力，來實現下列哪種姿態？","answer":"C","options":[{"key":"A","text":"垂直的升降姿態。"},{"key":"B","text":"俯仰的姿態。"},{"key":"C","text":"偏航的姿態。"},{"key":"D","text":"滾轉的姿態。"}]},{"id":"chapter-02-212","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人多旋翼機改變橫向兩端旋翼的升力，使之不平衡，來實現下列哪種姿態？","answer":"D","options":[{"key":"A","text":"垂直的升降姿態。"},{"key":"B","text":"偏航的姿態。"},{"key":"C","text":"俯仰的姿態。"},{"key":"D","text":"滾轉的姿態。"}]},{"id":"chapter-02-213","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"在空氣動力學裡，負載係數定義為下列哪個比值？","answer":"A","options":[{"key":"A","text":"升力與重力之比值。"},{"key":"B","text":"阻力與重力之比值。"},{"key":"C","text":"推力與重力之比值。"},{"key":"D","text":"升力與阻力之比值。"}]},{"id":"chapter-02-214","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機飛行時會產生各種姿態，負載係數即能表達下列哪個項目？","answer":"B","options":[{"key":"A","text":"巡航速度。"},{"key":"B","text":"姿態動作的大小。"},{"key":"C","text":"飛行距離。"},{"key":"D","text":"續航時間。"}]},{"id":"chapter-02-215","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機在進行協調轉彎時，負載係數是基於下列哪些力的結果？","answer":"C","options":[{"key":"A","text":"升力和重力。"},{"key":"B","text":"推力和重力。"},{"key":"C","text":"離心力和重力。"},{"key":"D","text":"阻力和重力。"}]},{"id":"chapter-02-216","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機轉彎時，機翼必須產生足以與負載係數相等的升力，以達到下列哪個目的？","answer":"A","options":[{"key":"A","text":"維持高度。"},{"key":"B","text":"維持速度。"},{"key":"C","text":"維持航向。"},{"key":"D","text":"維持發動機轉速。"}]},{"id":"chapter-02-217","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，受到配平以及總阻力的增加的影響，為了保持飛行速度不變，必須採取下列哪種手段？","answer":"A","options":[{"key":"A","text":"增加發動機推力。"},{"key":"B","text":"減少發動機推力。"},{"key":"C","text":"先增加然後減少發動機推力。"},{"key":"D","text":"先減少然後增加發動機推力。"}]},{"id":"chapter-02-218","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心位置靠前時，低速飛行時，為了穩定較強的俯仰姿態，可能會有下列哪種情形導致提高不穩定進場的風險？","answer":"A","options":[{"key":"A","text":"配平可能不足。"},{"key":"B","text":"配平可能過大。"},{"key":"C","text":"滾轉可能不足。"},{"key":"D","text":"滾轉可能過大。"}]},{"id":"chapter-02-219","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重心後移時，若進入到下列哪種情形時，會較難改正？","answer":"B","options":[{"key":"A","text":"滾轉角變小。"},{"key":"B","text":"螺旋失速。"},{"key":"C","text":"偏航角變小。"},{"key":"D","text":"攻角變小。"}]},{"id":"chapter-02-220","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人直昇機重心太前，會抑制下列哪種性能？","answer":"B","options":[{"key":"A","text":"平直飛行。"},{"key":"B","text":"向後飛及懸停低速。"},{"key":"C","text":"從地面到正常起飛。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-02-221","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人飛機重量增加可能造成下列哪種結果？","answer":"B","options":[{"key":"A","text":"降低失速速度。"},{"key":"B","text":"提高失速速度。"},{"key":"C","text":"失速速度不變。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-02-222","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"遙控無人機保持平飛，飛行速度越大則升力與阻力會有下列哪種結果？","answer":"B","options":[{"key":"A","text":"升力、誘導阻力越小。"},{"key":"B","text":"升力不變、寄生阻力越大。"},{"key":"C","text":"升力越大、誘導阻力越小。"},{"key":"D","text":"升力不變、誘導阻力越大。"}]},{"id":"chapter-02-223","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人機正以航向90接近機場，請問此無人機目前在機場的下列哪一個方向？","answer":"B","options":[{"key":"A","text":"北方。"},{"key":"B","text":"西方。"},{"key":"C","text":"東方。"},{"key":"D","text":"南方。"}]},{"id":"chapter-02-224","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"在作飛行規畫或操作無人機時，操作人手上有多項重量和平衡的資訊，依日期先後排列，包括a. 2016/8/15（無人機出廠時），b. 2016/10/18，c. 2016/12/27，d. 2017/2/8，e. 2017/6/19（無人機上次飛行時），f. 2017/9/20，操作人應使用下列哪一項？","answer":"A","options":[{"key":"A","text":"2017/9/20重量和平衡的資訊。"},{"key":"B","text":"2016/8/15（無人機出廠時）重量和平衡資訊。"},{"key":"C","text":"2017/6/19（無人機上次飛行時）重量和平衡資訊。"},{"key":"D","text":"任一項的重量和平衡資訊。"}]},{"id":"chapter-02-225","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"請問下列哪一種情況，可以視為上傳鏈路失效？","answer":"B","options":[{"key":"A","text":"操作人無法目視到無人機。"},{"key":"B","text":"無人機不執行地面控制站上傳的控制命令。"},{"key":"C","text":"操作人與塔台間的通訊斷訊。"},{"key":"D","text":"無人機無法將自身狀態（速度、高度、位置、設備狀態等）以及相關任務數據發回地面控制站。"}]},{"id":"chapter-02-226","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"請問上傳鏈路失效通常是下列哪一種原因？","answer":"D","options":[{"key":"A","text":"GPS失效。"},{"key":"B","text":"地面控制站天線附近站了太多人。"},{"key":"C","text":"無人機飛出操作人目視範圍以外。"},{"key":"D","text":"頻率干擾。"}]},{"id":"chapter-02-227","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"慣性導航系統（Inertial Navigation System，INS）是一種不依賴於外部資訊、也不向外部輻射能量（如無線電導航那樣）的自主式導航系統。慣性導航的基本工作原理是下列哪一項？","answer":"D","options":[{"key":"A","text":"以天體力學定律為基礎，以星座獲得位置，經幾何運算得到速度、加速度等資訊。"},{"key":"B","text":"以幾何力學定律為基礎，以磁場獲得位置，經三角運算得到速度、加速度等資訊。"},{"key":"C","text":"以牛頓力學定律為基礎，以GPS獲得位置，微分得到速度，再微分得到加速度等資訊。"},{"key":"D","text":"以牛頓力學定律為基礎，以加速度計獲得加速度，積分得到速度，再積分得到位置等資訊。"}]},{"id":"chapter-02-228","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"下列何者為遙控無人機運作之核心，主要執行起飛、航行、返場降落及回收等動作？","answer":"C","options":[{"key":"A","text":"導航系統。"},{"key":"B","text":"動力系統。"},{"key":"C","text":"飛行控制系統。"},{"key":"D","text":"無線遙控系統。"}]},{"id":"chapter-02-229","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"航空模型上沒有GPS，也沒有高度計，請問操作人應如何判斷400英呎飛行高度？","answer":"A","options":[{"key":"A","text":"在飛行前獲得地面上離無人機400英呎的目測概念作飛行高度參考。"},{"key":"B","text":"該無人機飛行時，操作另一架有高度計的無人機到400英呎作飛行高度參考。"},{"key":"C","text":"操作該無人機到400英呎高塔旁邊作飛行高度參考。"},{"key":"D","text":"操作該無人機到兩座已知高度建築物中間作飛行高度參考。"}]},{"id":"chapter-02-230","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"當準備在無人機上安裝攝影機或其他酬載時，操作人應有如何的認知？","answer":"D","options":[{"key":"A","text":"超出無人機重量限制和重心範圍一點點，不影響安全。"},{"key":"B","text":"先測試看看，只要飛的起來就沒問題。"},{"key":"C","text":"即使超出重心範圍，但只要在重量限制內，透過高超的操作技巧一樣能夠飛行。"},{"key":"D","text":"不超出無人機重量限制和重心範圍。"}]},{"id":"chapter-02-231","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"假設無人飛機最大起飛重量102磅，重心範圍（參考面在機鼻）25~27英吋。某次飛行前稱重，空重（含燃油）50磅、力臂20英吋，前艙酬載20磅、力臂10英吋，後艙酬載30磅、力臂40英吋，總重100磅，重心24英吋，請問操作人應採取下列哪一項動作？","answer":"B","options":[{"key":"A","text":"前艙酬載往前移動2.6英吋。"},{"key":"B","text":"後艙酬載往後移動3.4英吋。"},{"key":"C","text":"後艙酬載配重增加2.5磅。"},{"key":"D","text":"前艙酬載配重增加1.2磅。"}]},{"id":"chapter-02-232","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人機正以空速保持（40 kts）及姿態保持在往東飛行，無人機經緯度為E 121∘10′00\"，N 22∘20′30\"，此時為靜風，無人機要飛到E 121∘30′00\"，N 22∘20′30\"執行任務，請問無人機還要約多少時間才會抵達？","answer":"C","options":[{"key":"A","text":"10分鐘。"},{"key":"B","text":"20分鐘。"},{"key":"C","text":"30分鐘。"},{"key":"D","text":"40分鐘。"}]},{"id":"chapter-02-233","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"無人機正在平直飛行時，因任務需要必須快速增加高度，請問操作人應採取下列哪一項動作？","answer":"D","options":[{"key":"A","text":"將動力加到最大，攻角越大越好，以得到最大爬升率。"},{"key":"B","text":"保持動力，快速增大攻角，注意不超過臨界攻角。"},{"key":"C","text":"將動力加到最大，以最佳爬升角空速執行爬升，在一定距離產生最大高度增加。"},{"key":"D","text":"將動力加到最大，以最佳爬升率空速執行爬升，注意不超過臨界攻角。"}]},{"id":"chapter-02-234","chapterId":"chapter-02","chapterName":"第二章基礎飛行原理","question":"機場跑道地面風約為正南風，使用跑道為南北向，請問一般航空器在操作時應選擇哪一方向的跑道？","answer":"A","options":[{"key":"A","text":"18跑道。"},{"key":"B","text":"27跑道。"},{"key":"C","text":"09跑道。"},{"key":"D","text":"36跑道。"}]}]},{"id":"chapter-03","name":"第三章氣象","shortName":"氣象","questions":[{"id":"chapter-03-001","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣密度增加時，對飛機升力的影響為何者？","answer":"A","options":[{"key":"A","text":"升力增加。"},{"key":"B","text":"升力降低。"},{"key":"C","text":"升力不變。"},{"key":"D","text":"升力有時增加有時降低。"}]},{"id":"chapter-03-002","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列何者非影響空氣密度之因素？","answer":"D","options":[{"key":"A","text":"高度。"},{"key":"B","text":"溫度。"},{"key":"C","text":"濕度。"},{"key":"D","text":"應力。"}]},{"id":"chapter-03-003","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣中分子較少且稀薄，表示其密度高度為何？","answer":"A","options":[{"key":"A","text":"越高。"},{"key":"B","text":"越低。"},{"key":"C","text":"可能高也可能低。"},{"key":"D","text":"無法判斷。"}]},{"id":"chapter-03-004","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣中分子較多且濃厚，表示其密度高度為何？","answer":"B","options":[{"key":"A","text":"越高。"},{"key":"B","text":"越低。"},{"key":"C","text":"可能高也可能低。"},{"key":"D","text":"無法判斷。"}]},{"id":"chapter-03-005","chapterId":"chapter-03","chapterName":"第三章氣象","question":"高密度高度之環境比較不會出現於下列何處？","answer":"A","options":[{"key":"A","text":"低海拔處。"},{"key":"B","text":"高溫處。"},{"key":"C","text":"非常潮濕之處。"},{"key":"D","text":"低大氣壓力之處。"}]},{"id":"chapter-03-006","chapterId":"chapter-03","chapterName":"第三章氣象","question":"低密度高度之環境比較不會出現於下列何處？","answer":"D","options":[{"key":"A","text":"大氣壓力極高之處。"},{"key":"B","text":"低海拔處。"},{"key":"C","text":"乾燥處。"},{"key":"D","text":"高溫處。"}]},{"id":"chapter-03-007","chapterId":"chapter-03","chapterName":"第三章氣象","question":"空氣可藉由外界的作功達到下列哪種效果？","answer":"C","options":[{"key":"A","text":"加工成形。"},{"key":"B","text":"染色。"},{"key":"C","text":"壓縮及膨脹。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-008","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於固定空氣體積下，升溫時該體積空氣密度減少，降溫時該體積空氣密度為下列何種變化？","answer":"A","options":[{"key":"A","text":"增加。"},{"key":"B","text":"減少。"},{"key":"C","text":"不變。"},{"key":"D","text":"有時增加有時減少。"}]},{"id":"chapter-03-009","chapterId":"chapter-03","chapterName":"第三章氣象","question":"對流層裡，溫度及壓力均隨高度增加而有下列何種變化？","answer":"A","options":[{"key":"A","text":"降低。"},{"key":"B","text":"增加。"},{"key":"C","text":"不變。"},{"key":"D","text":"有時增加有時降低。"}]},{"id":"chapter-03-010","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列有關大氣壓力量測之敘述，何者錯誤？","answer":"C","options":[{"key":"A","text":"國際標準大氣(International Standard Atmosphere，ISA)為各國公認之參考校正基準。"},{"key":"B","text":"海平面大氣壓力為29.92英吋汞柱(inHg)。"},{"key":"C","text":"一標準大氣壓力等於1017.2毫巴值。"},{"key":"D","text":"每上升1,000英呎，氣壓值減少約1英吋汞柱。"}]},{"id":"chapter-03-011","chapterId":"chapter-03","chapterName":"第三章氣象","question":"標準一大氣壓的29.92吋汞柱換算成毫巴值為下列哪個數值？","answer":"C","options":[{"key":"A","text":"10.132。"},{"key":"B","text":"101.32。"},{"key":"C","text":"1013.2。"},{"key":"D","text":"10132。"}]},{"id":"chapter-03-012","chapterId":"chapter-03","chapterName":"第三章氣象","question":"大氣壓力之實際值與標準值存在差距，係由於哪項因素所影響？","answer":"B","options":[{"key":"A","text":"壓力錶廠牌差異。"},{"key":"B","text":"地面溫度不平均。"},{"key":"C","text":"壓力錶讀法差異。"},{"key":"D","text":"壓力錶校正值差異。"}]},{"id":"chapter-03-013","chapterId":"chapter-03","chapterName":"第三章氣象","question":"若遙控無人機操作人未能注意大氣壓力實際值與標準值間之差距並適時修正，可能無法精確掌握何項資訊？","answer":"A","options":[{"key":"A","text":"實際高度。"},{"key":"B","text":"實際航向。"},{"key":"C","text":"實際滾轉角。"},{"key":"D","text":"實際引擎轉速。"}]},{"id":"chapter-03-014","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣象資料顯示某區域之氣壓值有向上提升之趨勢，代表該區域天氣狀況有何種變化？","answer":"C","options":[{"key":"A","text":"天氣轉壞。"},{"key":"B","text":"天氣可能轉好也可能轉壞。"},{"key":"C","text":"天氣好轉。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-03-015","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣象資料顯示某區域之氣壓值有向下降低之趨勢，代表該區域天氣狀況有何種變化？","answer":"B","options":[{"key":"A","text":"天氣好轉。"},{"key":"B","text":"天氣轉壞。"},{"key":"C","text":"天氣有時晴朗有時轉壞。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-03-016","chapterId":"chapter-03","chapterName":"第三章氣象","question":"空氣的水平運動稱為？","answer":"B","options":[{"key":"A","text":"「雲」。"},{"key":"B","text":"「風」。"},{"key":"C","text":"「霧」。"},{"key":"D","text":"「霾」。"}]},{"id":"chapter-03-017","chapterId":"chapter-03","chapterName":"第三章氣象","question":"有關風速的單位下列何者為非？","answer":"D","options":[{"key":"A","text":"公尺/每秒（m/s）。"},{"key":"B","text":"公里/每小時（km/h）。"},{"key":"C","text":"海浬/每小時（kts）。"},{"key":"D","text":"公斤/每小時（kg）。"}]},{"id":"chapter-03-018","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機通常應於下列哪種風向下起降？","answer":"C","options":[{"key":"A","text":"順風。"},{"key":"B","text":"側風。"},{"key":"C","text":"逆風。"},{"key":"D","text":"任何風向。"}]},{"id":"chapter-03-019","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人飛機於逆風下起飛，不會有以下哪種特性？","answer":"D","options":[{"key":"A","text":"增加穩定性。"},{"key":"B","text":"增加操縱性。"},{"key":"C","text":"減少起飛距離。"},{"key":"D","text":"減少操縱性。"}]},{"id":"chapter-03-020","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機飛經下列哪個區域較易遭受亂流影響，且其亂流強度與周遭環境有密切關聯？","answer":"D","options":[{"key":"A","text":"大草原區。"},{"key":"B","text":"寬廣湖泊區。"},{"key":"C","text":"平坦操場上空。"},{"key":"D","text":"深山峽谷區。"}]},{"id":"chapter-03-021","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當越強勁的風吹過多山地區時，背風面的風場會如何變化？","answer":"C","options":[{"key":"A","text":"漸趨平穩。"},{"key":"B","text":"有時平穩有時不平穩。"},{"key":"C","text":"漸趨不平穩。"},{"key":"D","text":"不變。"}]},{"id":"chapter-03-022","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機飛航活動期間，可能於任何高度遭遇不同風切狀況，其中以哪一項對其操控性影響最大？","answer":"D","options":[{"key":"A","text":"超高空風切。"},{"key":"B","text":"高空風切。"},{"key":"C","text":"向量風切。"},{"key":"D","text":"低空風切。"}]},{"id":"chapter-03-023","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機於起降階段突遇風速與風向之明顯改變，不會有下列哪種影響？","answer":"D","options":[{"key":"A","text":"飛行姿態改變。"},{"key":"B","text":"飛行軌跡改變。"},{"key":"C","text":"所獲升力改變。"},{"key":"D","text":"最大載重改變。"}]},{"id":"chapter-03-024","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列針對發生於臺灣地區低空風切之敘述，何者較為正確？","answer":"B","options":[{"key":"A","text":"於鋒面過境時較為溫和，西南季風吹拂時較為強烈。"},{"key":"B","text":"於鋒面過境時較為強烈，西南季風吹拂時較為溫和。"},{"key":"C","text":"鋒面過境或西南季風吹拂時均為溫和。"},{"key":"D","text":"鋒面過境或西南季風吹拂時均為強烈。"}]},{"id":"chapter-03-025","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機操作人於操作前及操作時需隨時注意天氣狀況，因天氣因素可能對無人機產生何種影響？","answer":"B","options":[{"key":"A","text":"外觀美感。"},{"key":"B","text":"飛行航向。"},{"key":"C","text":"品牌知名度。"},{"key":"D","text":"重量大小。"}]},{"id":"chapter-03-026","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列何種天氣現象，與大氣垂直運動無直接關係？","answer":"B","options":[{"key":"A","text":"雷雨。"},{"key":"B","text":"平流霧。"},{"key":"C","text":"冰雹。"},{"key":"D","text":"下爆氣流。"}]},{"id":"chapter-03-027","chapterId":"chapter-03","chapterName":"第三章氣象","question":"大氣穩定度與下列何項因子有直接關係？","answer":"A","options":[{"key":"A","text":"空氣流動方向。"},{"key":"B","text":"空氣中懸浮微粒大小。"},{"key":"C","text":"水氣飽和程度。"},{"key":"D","text":"空氣乾燥程度。"}]},{"id":"chapter-03-028","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於地球表面某特殊地區所生成，具停留時間長且其水平方向之物理性質(如溫度及濕度)等均為一致之廣大空氣體，稱之？","answer":"B","options":[{"key":"A","text":"鋒面。"},{"key":"B","text":"氣團。"},{"key":"C","text":"颶風。"},{"key":"D","text":"塔狀積雲。"}]},{"id":"chapter-03-029","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列哪個城市所處位置之氣候條件，較易發生午後雷陣雨？","answer":"B","options":[{"key":"A","text":"東京。"},{"key":"B","text":"新加坡。"},{"key":"C","text":"莫斯科。"},{"key":"D","text":"倫敦。"}]},{"id":"chapter-03-030","chapterId":"chapter-03","chapterName":"第三章氣象","question":"一定量空氣於一定溫度下，所能容納之下列何者亦有其限度？","answer":"C","options":[{"key":"A","text":"PM2.5。"},{"key":"B","text":"微生物。"},{"key":"C","text":"水氣量。"},{"key":"D","text":"細菌。"}]},{"id":"chapter-03-031","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣中水氣含量已達其最高限度時，此時相對溼度為何？","answer":"D","options":[{"key":"A","text":"0.2。"},{"key":"B","text":"0.4。"},{"key":"C","text":"0.8。"},{"key":"D","text":"1。"}]},{"id":"chapter-03-032","chapterId":"chapter-03","chapterName":"第三章氣象","question":"空氣能容納水氣量之多寡與下列何者有密切關係？","answer":"C","options":[{"key":"A","text":"空氣含氧量。"},{"key":"B","text":"空氣雜質含量。"},{"key":"C","text":"溫度。"},{"key":"D","text":"空氣惰性氣體成份。"}]},{"id":"chapter-03-033","chapterId":"chapter-03","chapterName":"第三章氣象","question":"已飽和之水氣如遇溫度持續下降，不會產生下列哪種現象？","answer":"D","options":[{"key":"A","text":"霧。"},{"key":"B","text":"雲。"},{"key":"C","text":"雨滴。"},{"key":"D","text":"風。"}]},{"id":"chapter-03-034","chapterId":"chapter-03","chapterName":"第三章氣象","question":"空氣中實際所含水氣量，與相同溫度下可含最大水氣量之百分比，稱為？","answer":"B","options":[{"key":"A","text":"絕對濕度。"},{"key":"B","text":"相對濕度。"},{"key":"C","text":"同溫濕度。"},{"key":"D","text":"實際濕度。"}]},{"id":"chapter-03-035","chapterId":"chapter-03","chapterName":"第三章氣象","question":"空氣中濕度越高，會導致下列哪種情形？","answer":"B","options":[{"key":"A","text":"空氣的壓力越大。"},{"key":"B","text":"空氣密度越低。"},{"key":"C","text":"飛行器升力增加。"},{"key":"D","text":"涼爽度提高。"}]},{"id":"chapter-03-036","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣溫度等於露點溫度時，即達到何種狀況？","answer":"B","options":[{"key":"A","text":"水氣沸點。"},{"key":"B","text":"水氣飽和點。"},{"key":"C","text":"水氣熔點。"},{"key":"D","text":"水氣蒸發點。"}]},{"id":"chapter-03-037","chapterId":"chapter-03","chapterName":"第三章氣象","question":"水汽飽和時不會產生下列哪種現象？","answer":"D","options":[{"key":"A","text":"雲。"},{"key":"B","text":"霧。"},{"key":"C","text":"雨。"},{"key":"D","text":"雷爆。"}]},{"id":"chapter-03-038","chapterId":"chapter-03","chapterName":"第三章氣象","question":"「霧」依其形成條件及特性分有不同種類，下列何者非常用之分類？","answer":"D","options":[{"key":"A","text":"平流霧。"},{"key":"B","text":"蒸氣霧。"},{"key":"C","text":"鋒面霧。"},{"key":"D","text":"高空霧。"}]},{"id":"chapter-03-039","chapterId":"chapter-03","chapterName":"第三章氣象","question":"有關平流霧之特點，下列何者為非？","answer":"A","options":[{"key":"A","text":"日出後消散快速。"},{"key":"B","text":"相對濕度較高。"},{"key":"C","text":"不容易消散。"},{"key":"D","text":"可能發生於沿海區域。"}]},{"id":"chapter-03-040","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列哪一種情況能有助於平流霧之消散？","answer":"B","options":[{"key":"A","text":"風速變小。"},{"key":"B","text":"風向轉變。"},{"key":"C","text":"溫度升高。"},{"key":"D","text":"濕度增高。"}]},{"id":"chapter-03-041","chapterId":"chapter-03","chapterName":"第三章氣象","question":"有關輻射霧之特點，下列何者為非？","answer":"C","options":[{"key":"A","text":"日出後漸漸消散。"},{"key":"B","text":"大都發生於冬季。"},{"key":"C","text":"相較於平流霧比較不容易消散。"},{"key":"D","text":"通常地面風速微弱、空氣穩定。"}]},{"id":"chapter-03-042","chapterId":"chapter-03","chapterName":"第三章氣象","question":"冷空氣因流經溫暖水面之蒸發作用使其中水氣增加，因而凝結成下列哪種霧的型態？","answer":"A","options":[{"key":"A","text":"蒸氣霧。"},{"key":"B","text":"輻射霧。"},{"key":"C","text":"山坡霧。"},{"key":"D","text":"鋒面霧。"}]},{"id":"chapter-03-043","chapterId":"chapter-03","chapterName":"第三章氣象","question":"蒸氣霧常出現於下列哪個季節？","answer":"C","options":[{"key":"A","text":"春夏季節。"},{"key":"B","text":"夏末季節。"},{"key":"C","text":"秋冬季節。"},{"key":"D","text":"春末季節。"}]},{"id":"chapter-03-044","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於兩股不同性質氣團之交界面，當空氣自高空往下移動自近地面較冷空氣而凝結所成之霧，稱之？","answer":"A","options":[{"key":"A","text":"鋒面霧。"},{"key":"B","text":"山坡霧。"},{"key":"C","text":"輻射霧。"},{"key":"D","text":"蒸氣霧。"}]},{"id":"chapter-03-045","chapterId":"chapter-03","chapterName":"第三章氣象","question":"鋒面霧多伴隨何種天氣現象發生？","answer":"B","options":[{"key":"A","text":"颱風。"},{"key":"B","text":"鋒面。"},{"key":"C","text":"雷陣雨。"},{"key":"D","text":"龍捲風。"}]},{"id":"chapter-03-046","chapterId":"chapter-03","chapterName":"第三章氣象","question":"平流和輻射兩種物理過程亦可相輔相成，造成下列哪種霧的發生？","answer":"A","options":[{"key":"A","text":"平流輻射霧。"},{"key":"B","text":"山坡霧。"},{"key":"C","text":"蒸氣霧。"},{"key":"D","text":"鋒面霧。"}]},{"id":"chapter-03-047","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當周遭空氣溫度下降至低於露點，水氣因此凝結成水滴並附著於地表或建築物上，其稱之？","answer":"B","options":[{"key":"A","text":"雲。"},{"key":"B","text":"露。"},{"key":"C","text":"霧。"},{"key":"D","text":"霜。"}]},{"id":"chapter-03-048","chapterId":"chapter-03","chapterName":"第三章氣象","question":"附著於航空器上之露珠若凝結成固態霜，對飛航安全有何影響？","answer":"B","options":[{"key":"A","text":"對飛安有幫助。"},{"key":"B","text":"對飛安可能造成危害。"},{"key":"C","text":"對飛安並無影響。"},{"key":"D","text":"對飛安有時可能造成危害有時無影響。"}]},{"id":"chapter-03-049","chapterId":"chapter-03","chapterName":"第三章氣象","question":"附著於機體表面的霜在飛行時不會產生下列哪種情形？","answer":"D","options":[{"key":"A","text":"擾動流經機翼之空氣。"},{"key":"B","text":"降低升力。"},{"key":"C","text":"增加阻力。"},{"key":"D","text":"增加飛航效率。"}]},{"id":"chapter-03-050","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於大陸型氣候區域執行深秋早晨之飛行任務前，務必進行下列哪個程序以確保安全？","answer":"C","options":[{"key":"A","text":"暖身程序。"},{"key":"B","text":"點名程序。"},{"key":"C","text":"除霜程序。"},{"key":"D","text":"冥想程序。"}]},{"id":"chapter-03-051","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雲有下列哪幾種型態？","answer":"D","options":[{"key":"A","text":"積狀雲。"},{"key":"B","text":"層狀雲。"},{"key":"C","text":"卷狀雲。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-052","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雲的型態依據雲所在的高度可以分成下列哪幾種？","answer":"D","options":[{"key":"A","text":"高雲族。"},{"key":"B","text":"中雲族。"},{"key":"C","text":"低雲族。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-053","chapterId":"chapter-03","chapterName":"第三章氣象","question":"高雲族高度大約在6,000公尺以上，主要有下列哪幾種？","answer":"D","options":[{"key":"A","text":"卷雲。"},{"key":"B","text":"卷層雲。"},{"key":"C","text":"卷積雲。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-054","chapterId":"chapter-03","chapterName":"第三章氣象","question":"中雲族高度大約在2,000~6,000公尺，主要有下列哪幾種？","answer":"D","options":[{"key":"A","text":"高積雲。"},{"key":"B","text":"高層雲。"},{"key":"C","text":"雨層雲。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-055","chapterId":"chapter-03","chapterName":"第三章氣象","question":"低雲族高度位於2,000公尺以下，包含下列哪幾種？","answer":"D","options":[{"key":"A","text":"積雲。"},{"key":"B","text":"層雲。"},{"key":"C","text":"層積雲。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-056","chapterId":"chapter-03","chapterName":"第三章氣象","question":"下列何者為常見氣團分類方式？","answer":"D","options":[{"key":"A","text":"依其源地緯度高或低。"},{"key":"B","text":"依其源地為大陸或海洋。"},{"key":"C","text":"依其所經地面為冷空氣或暖空氣。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-057","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣團本身冷於周遭空氣稱為？","answer":"B","options":[{"key":"A","text":"暖氣團。"},{"key":"B","text":"冷氣團。"},{"key":"C","text":"冰氣團。"},{"key":"D","text":"熱氣團。"}]},{"id":"chapter-03-058","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣團穩定度決定其籠罩區域的哪種形態？","answer":"C","options":[{"key":"A","text":"社會形態。"},{"key":"B","text":"經濟形態。"},{"key":"C","text":"天氣形態。"},{"key":"D","text":"政治形態。"}]},{"id":"chapter-03-059","chapterId":"chapter-03","chapterName":"第三章氣象","question":"在鋒面兩側的下列哪種現象通常均有明顯的差異？","answer":"D","options":[{"key":"A","text":"溫度。"},{"key":"B","text":"濕度。"},{"key":"C","text":"風、天氣。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-060","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當冷空氣前進，迫使暖空氣後退而取代暖空氣原有位置，則此時產生之鋒面稱為？","answer":"C","options":[{"key":"A","text":"滯留鋒。"},{"key":"B","text":"暖鋒。"},{"key":"C","text":"冷鋒。"},{"key":"D","text":"囚錮鋒。"}]},{"id":"chapter-03-061","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當冷暖氣團勢均力敵以致使鋒面呈滯留狀態，此時之鋒面稱為？","answer":"B","options":[{"key":"A","text":"暖鋒。"},{"key":"B","text":"滯留鋒。"},{"key":"C","text":"冷鋒。"},{"key":"D","text":"囚錮鋒。"}]},{"id":"chapter-03-062","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機飛經各鋒面區時，可能遭遇下列何項劇烈變化？","answer":"D","options":[{"key":"A","text":"溫度。"},{"key":"B","text":"濕度。"},{"key":"C","text":"風向。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-063","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機於山區飛行時若遇強風，則可選擇何處飛行相較為平順？","answer":"C","options":[{"key":"A","text":"背風面。"},{"key":"B","text":"側風面。"},{"key":"C","text":"迎風面。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-03-064","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機於山區飛行時，過了山巔需注意沿何方向所產生之亂流？","answer":"B","options":[{"key":"A","text":"側風面。"},{"key":"B","text":"背風面。"},{"key":"C","text":"迎風面。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-03-065","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機飛越可見水氣（如雨或雲）時，需注意哪個部位可能發生積冰現象？","answer":"D","options":[{"key":"A","text":"機翼翼面。"},{"key":"B","text":"尾翼翼面。"},{"key":"C","text":"感測器。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-066","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機飛行時，於下列哪種情形可能發生積冰現象？","answer":"D","options":[{"key":"A","text":"機體周遭氣溫為攝氏零度。"},{"key":"B","text":"機體周遭氣溫為攝氏零度以下。"},{"key":"C","text":"有可見水氣。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-067","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當遙控無人機飛越結冰區域時，可能發生下列哪種狀況？","answer":"A","options":[{"key":"A","text":"影響或誤判遙控無人機飛行性能表現。"},{"key":"B","text":"提升遙控無人機飛行性能表現。"},{"key":"C","text":"遙控無人機飛行性能表現可能變好或變壞。"},{"key":"D","text":"不太可能發生任何狀況。"}]},{"id":"chapter-03-068","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雷雨的發展循環不包含下列何者？","answer":"C","options":[{"key":"A","text":"發展期。"},{"key":"B","text":"成熟期。"},{"key":"C","text":"重疊期。"},{"key":"D","text":"消散期。"}]},{"id":"chapter-03-069","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雷雨成熟期具有的特徵為何？","answer":"D","options":[{"key":"A","text":"下沉氣流。"},{"key":"B","text":"開始降水。"},{"key":"C","text":"打雷。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-070","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雷雨消散期具有的特徵為何？","answer":"D","options":[{"key":"A","text":"降雨減緩。"},{"key":"B","text":"下沉氣流減緩。"},{"key":"C","text":"雷雨雹消散。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-071","chapterId":"chapter-03","chapterName":"第三章氣象","question":"臺北航空氣象中心隸屬於下列哪個機關？","answer":"B","options":[{"key":"A","text":"交通部觀光局飛航服務總臺。"},{"key":"B","text":"交通部民用航空局飛航服務總臺。"},{"key":"C","text":"交通部中央氣象局飛航服務總臺。"},{"key":"D","text":"交通部航政司飛航服務總臺。"}]},{"id":"chapter-03-072","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機操作人可透過中央氣象局網頁取得下列哪項資料？","answer":"D","options":[{"key":"A","text":"天氣觀測資料。"},{"key":"B","text":"天氣預報資料。"},{"key":"C","text":"衛星雲圖。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-073","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機操作人可透過飛航服務總臺所建置之航空氣象服務網(AOAWS)取得下列哪項資料？","answer":"A","options":[{"key":"A","text":"國內外主要機場之即時觀測資料。"},{"key":"B","text":"國內機場6小時天氣預報資料。"},{"key":"C","text":"太平洋地區衛星雲圖。"},{"key":"D","text":"高空風溫圖。"}]},{"id":"chapter-03-074","chapterId":"chapter-03","chapterName":"第三章氣象","question":"考量天氣條件對於遙控無人機操控行為之影響，遙控無人機操作人應具備下列何者之基礎判讀能力？","answer":"A","options":[{"key":"A","text":"航空氣象報文。"},{"key":"B","text":"國內城市氣象報文。"},{"key":"C","text":"外國城市氣象報文。"},{"key":"D","text":"觀光地區氣象報文。"}]},{"id":"chapter-03-075","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，所使用觀測日期與時間及其代碼說明為下列何者？","answer":"A","options":[{"key":"A","text":"Z字母指示碼；代表UTC時間。"},{"key":"B","text":"L字母指示碼；代表本地時間。"},{"key":"C","text":"T字母指示碼；代表UTC時間。"},{"key":"D","text":"X字母指示碼；代表本地時間。"}]},{"id":"chapter-03-076","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，所觀測盛行能見度值，其編報方式及單位為何？","answer":"A","options":[{"key":"A","text":"4碼（公尺）。"},{"key":"B","text":"6碼（公尺）。"},{"key":"C","text":"8碼（公尺）。"},{"key":"D","text":"10碼（公尺）。"}]},{"id":"chapter-03-077","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象觀測員將天空劃分成8等份，若觀測到1/8至2/8的天空被雲層遮蓋，該雲量類別稱為下列何者？","answer":"A","options":[{"key":"A","text":"稀雲。"},{"key":"B","text":"疏雲。"},{"key":"C","text":"裂雲。"},{"key":"D","text":"密雲。"}]},{"id":"chapter-03-078","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象觀測員將天空劃分成8等份，若觀測到3/8至4/8的天空被雲層遮蓋，該雲量類別稱為下列何者？","answer":"B","options":[{"key":"A","text":"稀雲。"},{"key":"B","text":"疏雲。"},{"key":"C","text":"裂雲。"},{"key":"D","text":"密雲。"}]},{"id":"chapter-03-079","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象觀測員將天空劃分成8等份，若觀測到5/8至7/8的天空被雲層遮蓋，該雲量類別稱為下列何者？","answer":"C","options":[{"key":"A","text":"稀雲。"},{"key":"B","text":"疏雲。"},{"key":"C","text":"裂雲。"},{"key":"D","text":"密雲。"}]},{"id":"chapter-03-080","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象觀測員將天空劃分成8等份，若觀測到8/8的天空被雲層遮蓋，該雲量類別稱為下列何者？","answer":"D","options":[{"key":"A","text":"稀雲。"},{"key":"B","text":"疏雲。"},{"key":"C","text":"裂雲。"},{"key":"D","text":"密雲。"}]},{"id":"chapter-03-081","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，雲層之雲底高度單位為下列哪一個？","answer":"C","options":[{"key":"A","text":"公尺。"},{"key":"B","text":"公里。"},{"key":"C","text":"呎。"},{"key":"D","text":"浬。"}]},{"id":"chapter-03-082","chapterId":"chapter-03","chapterName":"第三章氣象","question":"終端機場天氣觀測報中，盛行天氣現象包括下列哪個項目？","answer":"D","options":[{"key":"A","text":"風向風速。"},{"key":"B","text":"能見度。"},{"key":"C","text":"天氣狀況及雲組。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-083","chapterId":"chapter-03","chapterName":"第三章氣象","question":"某一特定容積氣體的密度換算成標準大氣壓力狀態下的高度，稱之為下列哪種高度？","answer":"C","options":[{"key":"A","text":"指示高度。"},{"key":"B","text":"壓力高度。"},{"key":"C","text":"密度高度。"},{"key":"D","text":"絕對高度。"}]},{"id":"chapter-03-084","chapterId":"chapter-03","chapterName":"第三章氣象","question":"相同體積下，在低壓力狀態的氣體，其特徵為？","answer":"B","options":[{"key":"A","text":"質量較高。"},{"key":"B","text":"密度較低。"},{"key":"C","text":"質量密度均高。"},{"key":"D","text":"無法判斷。"}]},{"id":"chapter-03-085","chapterId":"chapter-03","chapterName":"第三章氣象","question":"相同體積下，當壓力加倍，則空氣密度將為哪種變化？","answer":"A","options":[{"key":"A","text":"亦為加倍。"},{"key":"B","text":"減半。"},{"key":"C","text":"增加4倍。"},{"key":"D","text":"減少為1/4。"}]},{"id":"chapter-03-086","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於一定體積下，空氣之溫度與密度成何項關係？","answer":"B","options":[{"key":"A","text":"溫度與密度成正比。"},{"key":"B","text":"溫度與密度成反比。"},{"key":"C","text":"溫度與密度的平方成正比。"},{"key":"D","text":"溫度與密度的平方成反比。"}]},{"id":"chapter-03-087","chapterId":"chapter-03","chapterName":"第三章氣象","question":"「國際標準大氣」是指在假設大氣環境下，海平面之大氣壓力和溫度分別為何？","answer":"B","options":[{"key":"A","text":"29.92吋汞柱/攝氏25度。"},{"key":"B","text":"29.92吋汞柱/攝氏15度。"},{"key":"C","text":"39.92吋汞柱/攝氏15度。"},{"key":"D","text":"39.92吋汞柱/攝氏25度。"}]},{"id":"chapter-03-088","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於對流層中，高度每上升1,000呎，溫度如何變化？","answer":"A","options":[{"key":"A","text":"降低約攝氏2度。"},{"key":"B","text":"升高約攝氏2度。"},{"key":"C","text":"降低約攝氏20度。"},{"key":"D","text":"升高約攝氏20度。"}]},{"id":"chapter-03-089","chapterId":"chapter-03","chapterName":"第三章氣象","question":"高度每上升1,000呎，氣壓值如何變化？","answer":"C","options":[{"key":"A","text":"減少約10吋汞柱。"},{"key":"B","text":"增加約10吋汞柱。"},{"key":"C","text":"減少約1吋汞柱。"},{"key":"D","text":"增加約1吋汞柱。"}]},{"id":"chapter-03-090","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣象上定義風的來向為風向，例如風自東邊吹來，稱其為？","answer":"B","options":[{"key":"A","text":"西風。"},{"key":"B","text":"東風。"},{"key":"C","text":"南風。"},{"key":"D","text":"北風。"}]},{"id":"chapter-03-091","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當遙控無人飛機於起飛時遭遇較強之正側風，可能導致下列哪種風險？","answer":"C","options":[{"key":"A","text":"操作人視線不清。"},{"key":"B","text":"導控距離變短。"},{"key":"C","text":"翼面與地面接觸。"},{"key":"D","text":"起飛距離變短。"}]},{"id":"chapter-03-092","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當遙控無人飛機於降落時遭遇較強之正側風，可能導致下列哪種風險？","answer":"A","options":[{"key":"A","text":"落地後偏離跑道。"},{"key":"B","text":"操作人視線不清。"},{"key":"C","text":"導控距離變短。"},{"key":"D","text":"降落距離變短。"}]},{"id":"chapter-03-093","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人直昇機及遙控無人多旋翼機，由於可垂直起降，因此對於風向之考量多著重於下列何者？","answer":"B","options":[{"key":"A","text":"起降時遇到較強的正側風。"},{"key":"B","text":"滯空飛行時的穩定度。"},{"key":"C","text":"避免順風起降。"},{"key":"D","text":"不要遮蔽操作人視線。"}]},{"id":"chapter-03-094","chapterId":"chapter-03","chapterName":"第三章氣象","question":"大氣中不同兩點間風速或風向之劇烈變化，稱之為何？","answer":"B","options":[{"key":"A","text":"風流。"},{"key":"B","text":"風切。"},{"key":"C","text":"風格。"},{"key":"D","text":"風氣。"}]},{"id":"chapter-03-095","chapterId":"chapter-03","chapterName":"第三章氣象","question":"風切可能伴隨下列哪種現象？","answer":"A","options":[{"key":"A","text":"垂直氣流。"},{"key":"B","text":"焚風氣流。"},{"key":"C","text":"旋風氣流。"},{"key":"D","text":"離心氣流。"}]},{"id":"chapter-03-096","chapterId":"chapter-03","chapterName":"第三章氣象","question":"所謂低空風切，我國定義係指下列哪個高度範圍之空氣層中，其風向或風速之突然變化？","answer":"D","options":[{"key":"A","text":"10,000~15,000呎。"},{"key":"B","text":"5,000~10,000呎。"},{"key":"C","text":"1,600~5,000呎。"},{"key":"D","text":"1,600呎以下。"}]},{"id":"chapter-03-097","chapterId":"chapter-03","chapterName":"第三章氣象","question":"微爆氣流的循環約在5到15分鐘之間，所產生之下沉氣流可達下列何項速度？","answer":"B","options":[{"key":"A","text":"每分鐘600呎。"},{"key":"B","text":"每分鐘6,000呎。"},{"key":"C","text":"每分鐘20,000呎。"},{"key":"D","text":"每分鐘50,000呎。"}]},{"id":"chapter-03-098","chapterId":"chapter-03","chapterName":"第三章氣象","question":"微爆氣流頂風與尾風的速度差距可達哪項範圍？","answer":"A","options":[{"key":"A","text":"30到90節。"},{"key":"B","text":"5到10節。"},{"key":"C","text":"10到20節。"},{"key":"D","text":"20到30節。"}]},{"id":"chapter-03-099","chapterId":"chapter-03","chapterName":"第三章氣象","question":"淺層的逆溫層一般來說高度為下列何者？","answer":"D","options":[{"key":"A","text":"約離地5,000公尺。"},{"key":"B","text":"約離地3,000公尺。"},{"key":"C","text":"約離地1,000公尺。"},{"key":"D","text":"約離地300公尺。"}]},{"id":"chapter-03-100","chapterId":"chapter-03","chapterName":"第三章氣象","question":"同樣體積之空氣溫度愈高，能容納之水氣為何？","answer":"A","options":[{"key":"A","text":"愈多。"},{"key":"B","text":"愈少。"},{"key":"C","text":"不變。"},{"key":"D","text":"有時愈多有時愈少。"}]},{"id":"chapter-03-101","chapterId":"chapter-03","chapterName":"第三章氣象","question":"在一定大氣壓力下，空氣中水氣含量固定不變時，若氣溫降至相當溫度使空氣飽和，氣溫再稍低，水氣即行凝結，此時之溫度，稱為下列哪種狀況？","answer":"A","options":[{"key":"A","text":"露點。"},{"key":"B","text":"沸點。"},{"key":"C","text":"霜點。"},{"key":"D","text":"熔點。"}]},{"id":"chapter-03-102","chapterId":"chapter-03","chapterName":"第三章氣象","question":"暖空氣經過冷地表時，暖空氣受地表影響降溫，可使水氣達到下列哪個狀態？","answer":"C","options":[{"key":"A","text":"不飽和狀態。"},{"key":"B","text":"半飽和狀態。"},{"key":"C","text":"飽和狀態。"},{"key":"D","text":"超飽和狀態。"}]},{"id":"chapter-03-103","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當空氣溫度達到或接近露點時，空氣中的水氣就會逐漸凝結，進而發生會影響能見度的下列哪種狀況？","answer":"C","options":[{"key":"A","text":"霜。"},{"key":"B","text":"露。"},{"key":"C","text":"霧。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-104","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當溫暖且潮溼的空氣流經較冷的地面時，低層空氣中的水氣會因冷卻作用而凝結形成霧，稱之為下列哪種霧？","answer":"A","options":[{"key":"A","text":"平流霧。"},{"key":"B","text":"山坡霧。"},{"key":"C","text":"鋒面霧。"},{"key":"D","text":"蒸氣霧。"}]},{"id":"chapter-03-105","chapterId":"chapter-03","chapterName":"第三章氣象","question":"通常出現在冬季晴朗、微風、近地面水氣充沛的夜間或清晨的霧，稱之為下列哪種霧？","answer":"A","options":[{"key":"A","text":"輻射霧。"},{"key":"B","text":"山坡霧。"},{"key":"C","text":"鋒面霧。"},{"key":"D","text":"蒸氣霧。"}]},{"id":"chapter-03-106","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當濕空氣沿山坡上升時，經絕熱冷卻而成的霧，稱之為下列哪種霧？","answer":"A","options":[{"key":"A","text":"山坡霧。"},{"key":"B","text":"輻射霧。"},{"key":"C","text":"蒸氣霧。"},{"key":"D","text":"鋒面霧。"}]},{"id":"chapter-03-107","chapterId":"chapter-03","chapterName":"第三章氣象","question":"平流輻射霧好發生於下列哪種季節地點？","answer":"C","options":[{"key":"A","text":"春末夏初台灣東部地區。"},{"key":"B","text":"夏末秋初台灣北部地區。"},{"key":"C","text":"冬末春初台灣西部地區。"},{"key":"D","text":"秋末冬初台灣南部地區。"}]},{"id":"chapter-03-108","chapterId":"chapter-03","chapterName":"第三章氣象","question":"水氣若溫度低於冰點即凝結成下列哪種現象？","answer":"B","options":[{"key":"A","text":"雲。"},{"key":"B","text":"霜。"},{"key":"C","text":"露。"},{"key":"D","text":"霧。"}]},{"id":"chapter-03-109","chapterId":"chapter-03","chapterName":"第三章氣象","question":"氣團從發源地移出後，與不同屬性的氣團相遇，而性質不同之冷暖兩氣團相遇時，其交界處稱為下列哪種現象？","answer":"A","options":[{"key":"A","text":"鋒面。"},{"key":"B","text":"界面。"},{"key":"C","text":"團面。"},{"key":"D","text":"表面。"}]},{"id":"chapter-03-110","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機若是嚴重結冰則可能會導致下列哪種狀況？","answer":"C","options":[{"key":"A","text":"推力不足而失速。"},{"key":"B","text":"重心偏移而失速。"},{"key":"C","text":"升力不足而失速。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-03-111","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雷雨發展期的特徵是下列哪種現象？","answer":"B","options":[{"key":"A","text":"下沉氣流。"},{"key":"B","text":"上升氣流。"},{"key":"C","text":"垂直風切。"},{"key":"D","text":"水平風切。"}]},{"id":"chapter-03-112","chapterId":"chapter-03","chapterName":"第三章氣象","question":"不宜在下列哪個範圍操作遙控無人機？","answer":"A","options":[{"key":"A","text":"成長快速的積雲附近。"},{"key":"B","text":"遠離成長快速的積雲。"},{"key":"C","text":"不明顯且成長停滯的積雲附近。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-03-113","chapterId":"chapter-03","chapterName":"第三章氣象","question":"雷雨成熟期的上升氣流及下沉氣流互相交錯，產生下列哪種現象？","answer":"B","options":[{"key":"A","text":"水平風切。"},{"key":"B","text":"垂直風切。"},{"key":"C","text":"低空風切。"},{"key":"D","text":"微爆氣流。"}]},{"id":"chapter-03-114","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象裡的機場觀測項目中，觀測人員就機場現時觀測之結果，原則上在下列哪個時間間隔編報「航空例行天氣報告（METAR）」？","answer":"B","options":[{"key":"A","text":"每5分鐘或10分鐘。"},{"key":"B","text":"每30分鐘或60分鐘。"},{"key":"C","text":"每6小時或12小時。"},{"key":"D","text":"每24小時或36小時。"}]},{"id":"chapter-03-115","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空氣象裡的預報資料項目中，針對機場的天氣預報原則上在下列哪個時間間隔編報「終端機場天氣預報（TAF）」？","answer":"C","options":[{"key":"A","text":"每24小時。"},{"key":"B","text":"每12小時。"},{"key":"C","text":"每6小時。"},{"key":"D","text":"每2小時。"}]},{"id":"chapter-03-116","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，觀測場站之識別碼：觀測發生之機場，我國機場識別碼前兩碼均為下列哪兩個英文字母？","answer":"B","options":[{"key":"A","text":"QQ。"},{"key":"B","text":"RC。"},{"key":"C","text":"AA。"},{"key":"D","text":"BB。"}]},{"id":"chapter-03-117","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，風向及風速：機場風向風速之觀測值，使用觀測下列哪個期間之平均風向與平均風速之編報？","answer":"B","options":[{"key":"A","text":"前1分鐘。"},{"key":"B","text":"前10分鐘。"},{"key":"C","text":"前60分鐘。"},{"key":"D","text":"前180分鐘。"}]},{"id":"chapter-03-118","chapterId":"chapter-03","chapterName":"第三章氣象","question":"航空例行天氣報告中，雲量是指下列哪個定義？","answer":"C","options":[{"key":"A","text":"雲在天空中的烏黑程度。"},{"key":"B","text":"雲在天空中的高度。"},{"key":"C","text":"雲在天空中遮蓋的份數。"},{"key":"D","text":"雲在天空中的移動速度。"}]},{"id":"chapter-03-119","chapterId":"chapter-03","chapterName":"第三章氣象","question":"遙控無人機操作人針對不同壓力高度對於無人機起降滑行距離之影響，應有何種正確認知？","answer":"C","options":[{"key":"A","text":"只要載重固定，起降滑行距離不受壓力高度變化影響。"},{"key":"B","text":"起降滑行距離與跑道鋪面、坡度及地面風向有關，無關壓力高度。"},{"key":"C","text":"壓力高度影響空氣密度，進而影響爬升率，對於起降滑行距離有直接影響。"},{"key":"D","text":"起降滑行距離與無人機動力來源有關，無關壓力高度。"}]},{"id":"chapter-03-120","chapterId":"chapter-03","chapterName":"第三章氣象","question":"「霧」對於無人機起降活動之影響顯而易見，請問下列針對「霧」的成因判斷，何者最為恰當？","answer":"D","options":[{"key":"A","text":"注意風（空氣水平運動）的狀況，風速增加就可能形成「霧」。"},{"key":"B","text":"注意對流（空氣垂直運動）的狀況，對流增強就可能形成「霧」。"},{"key":"C","text":"注意大氣壓力值是否降低，降低就可能形成「霧」。"},{"key":"D","text":"注意空氣溫度是否接近露點溫度，接近就可能形成「霧」。"}]},{"id":"chapter-03-121","chapterId":"chapter-03","chapterName":"第三章氣象","question":"無人機結束任務正準備返場，團隊藉由氣象資料得知5邊航線上有風切現象，風速及風向變化劇烈，請問操作人應特別注意風切對無人機之何項影響？","answer":"D","options":[{"key":"A","text":"引擎轉數可能因此而不穩定。"},{"key":"B","text":"資料鏈和GPS可能因此而失效。"},{"key":"C","text":"重心可能因此而偏移。"},{"key":"D","text":"可能造成升力損失，影響飛航穩定性，甚至無法安全降落。"}]},{"id":"chapter-03-122","chapterId":"chapter-03","chapterName":"第三章氣象","question":"無人機正於高聳建物附近飛行，因地面上障礙物會影響風的流動，故操作人應特別注意下列何種情形？","answer":"A","options":[{"key":"A","text":"風速及風向快速變化所產生之亂流。"},{"key":"B","text":"加強無人機穩定性及視線。"},{"key":"C","text":"發揮無人機性能表現。"},{"key":"D","text":"避免資料鏈和GPS可能因風速及風向之變化而失效。"}]},{"id":"chapter-03-123","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當氣團行經水面和陸地，最終將與另一不同特性的氣團接觸。此兩種不同類型的氣團的邊界層稱為鋒面。請問操作人最容易辨認下列哪一種鋒面中的不連續現象？","answer":"C","options":[{"key":"A","text":"雲層的增加。"},{"key":"B","text":"相對濕度的增加。"},{"key":"C","text":"溫度的變化。"},{"key":"D","text":"能見度的變化。"}]},{"id":"chapter-03-124","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當無人機須穿越鋒面進行飛航任務時，操作人應特別注意下列哪一種天氣現象之變化？","answer":"B","options":[{"key":"A","text":"降水型態之改變。"},{"key":"B","text":"風向之改變。"},{"key":"C","text":"氣團穩定性之改變。"},{"key":"D","text":"相對濕度之改變。"}]},{"id":"chapter-03-125","chapterId":"chapter-03","chapterName":"第三章氣象","question":"無人機正以定速（40 kts/時）及定姿態方式保持往東飛行，此時GPS速度（地速）顯示為44 kts/時，GPS航向為116度，請問風速和風向約略為何？","answer":"B","options":[{"key":"A","text":"東風20 kts。"},{"key":"B","text":"北風20 kts。"},{"key":"C","text":"南風20 kts。"},{"key":"D","text":"西風20 kts。"}]},{"id":"chapter-03-126","chapterId":"chapter-03","chapterName":"第三章氣象","question":"當無人機飛行於標準大氣壓力之環境下，其高度表指示高度（壓力高度）為3,000英呎，請問此時大氣壓力約為多少？","answer":"C","options":[{"key":"A","text":"28.86英吋汞柱高。"},{"key":"B","text":"27.82英吋汞柱高。"},{"key":"C","text":"26.82英吋汞柱高。"},{"key":"D","text":"25.84英吋汞柱高。"}]},{"id":"chapter-03-127","chapterId":"chapter-03","chapterName":"第三章氣象","question":"於標準大氣壓力環境下，無人機正於機場(位於水平面)跑道頭準備起飛，此時高度表指示高度（壓力高度）為200英呎，為使無人機壓力高度與機場跑道高度一致，請問操作人應採取下列哪一項動作？","answer":"A","options":[{"key":"A","text":"壓力高度修正為29.72英吋汞柱高。"},{"key":"B","text":"壓力高度修正為27.92英吋汞柱高。"},{"key":"C","text":"壓力高度修正為29.52英吋汞柱高。"},{"key":"D","text":"壓力高度修正為25.92英吋汞柱高。"}]},{"id":"chapter-03-128","chapterId":"chapter-03","chapterName":"第三章氣象","question":"無人機正往南的方向飛行前往任務目標區，根據氣象資料顯示，飛行航線上吹著穩定而強勁之北風，其區域及鄰近並無明顯障礙物，請問下列所述狀況何者為操作人較無須擔心事項？","answer":"C","options":[{"key":"A","text":"強風所持續之時間。"},{"key":"B","text":"風速是否超出無人機飛航性能限制。"},{"key":"C","text":"是否受到側風過大而影響飛航操作。"},{"key":"D","text":"是否因於強風中飛行而消耗更多動力來源，進而降低續航力。"}]},{"id":"chapter-03-129","chapterId":"chapter-03","chapterName":"第三章氣象","question":"依據雲層佔據整個天空的比例，一般將雲區分成稀雲、疏雲、裂雲、密雲等4個種類。現在收到氣象預報：「早晨疏雲，上午密雲，下午裂雲，晚上稀雲」，請問下列哪一個時段的降雨機率比較大？","answer":"C","options":[{"key":"A","text":"早晨。"},{"key":"B","text":"晚上。"},{"key":"C","text":"上午。"},{"key":"D","text":"下午。"}]}]},{"id":"chapter-04","name":"第四章緊急處置與飛行決策","shortName":"緊急處置與飛行決策","questions":[{"id":"chapter-04-001","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人在執行任務前及過程中，需確保參與執行的成員不受下列哪種狀況的影響？","answer":"C","options":[{"key":"A","text":"娛樂圈八卦和謠言。"},{"key":"B","text":"國內股市行情。"},{"key":"C","text":"酒精及藥物。"},{"key":"D","text":"世界經濟發展情勢。"}]},{"id":"chapter-04-002","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人在執行任務前及過程中，下列哪種狀況也可能影響操作安全？","answer":"B","options":[{"key":"A","text":"娛樂圈八卦和謠言。"},{"key":"B","text":"一般的成藥如抗組織胺或解除充血劑。"},{"key":"C","text":"國內股市行情。"},{"key":"D","text":"世界經濟發展情勢。"}]},{"id":"chapter-04-003","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"有關可能影響操作人安全操作遙控無人機的因素主要有下列哪種狀況？","answer":"D","options":[{"key":"A","text":"過度換氣、壓力、疲勞。"},{"key":"B","text":"脫水、熱中暑。"},{"key":"C","text":"酒精與藥物。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-004","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"過度換氣若無法善加控制，可能讓遙控無人機操作人進入下列哪個狀態？","answer":"B","options":[{"key":"A","text":"神經緊張。"},{"key":"B","text":"意識不清。"},{"key":"C","text":"心情鬱悶。"},{"key":"D","text":"懷疑心重。"}]},{"id":"chapter-04-005","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"過度換氣的常見症狀有下列哪種狀況？","answer":"D","options":[{"key":"A","text":"視界窄化、意識不清。"},{"key":"B","text":"輕快或暈眩感、肢體末稍有刺痛感。"},{"key":"C","text":"對冷熱敏感、肌肉痙攣感。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-006","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"過度換氣的改善方法是下列哪種方式？","answer":"C","options":[{"key":"A","text":"多閱讀、多聽音樂。"},{"key":"B","text":"適當的飲食。"},{"key":"C","text":"血液裡的二氧化碳濃度恢復到正常狀態。"},{"key":"D","text":"擴展社交範圍。"}]},{"id":"chapter-04-007","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"最好的預防及矯治過度換氣的方法就是下列哪種方式？","answer":"A","options":[{"key":"A","text":"讓呼吸保持正常、朝向紙袋呼吸或大聲交談。"},{"key":"B","text":"多閱讀、多聽音樂。"},{"key":"C","text":"適當的飲食。"},{"key":"D","text":"擴展社交範圍。"}]},{"id":"chapter-04-008","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪種狀況是人體對於生理及心理的需求所做出的反應？","answer":"B","options":[{"key":"A","text":"脫水。"},{"key":"B","text":"壓力。"},{"key":"C","text":"熱中暑。"},{"key":"D","text":"酒醉。"}]},{"id":"chapter-04-009","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"壓力源包括下列哪種狀況？","answer":"D","options":[{"key":"A","text":"物理的壓力（如噪音及振動）。"},{"key":"B","text":"生理的壓力（如疲勞）。"},{"key":"C","text":"心理的壓力（如工作困難或個人情緒因素）。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-010","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"持續性的急性壓力可能發展成下列哪種狀況？","answer":"C","options":[{"key":"A","text":"不定期的過度換氣壓力。"},{"key":"B","text":"不定期的疲勞壓力。"},{"key":"C","text":"長期的慢性壓力。"},{"key":"D","text":"不定期的酒精壓力。"}]},{"id":"chapter-04-011","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"慢性壓力在長期累積或壓抑下，會導致下列哪種狀況？","answer":"C","options":[{"key":"A","text":"個人能力大幅提升。"},{"key":"B","text":"個人能力時好時壞。"},{"key":"C","text":"個人能力大幅下滑。"},{"key":"D","text":"個人能力保持不變。"}]},{"id":"chapter-04-012","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人若體驗到壓力已導致己身能力下滑時即應採取下列哪種作為？","answer":"A","options":[{"key":"A","text":"暫停執行任務、適當休息。"},{"key":"B","text":"堅持到底、繼續執行任務。"},{"key":"C","text":"順其自然、不必大驚小怪。"},{"key":"D","text":"邊聽音樂舒壓、邊執行任務。"}]},{"id":"chapter-04-013","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"狀況警覺是對哪些風險元素的認知與瞭解？","answer":"D","options":[{"key":"A","text":"飛行作業。"},{"key":"B","text":"操作人、航空器。"},{"key":"C","text":"環境及任務種類。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-014","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪種狀況可能使遙控無人機操作人過度集中注意力在某件事物而失去對整體任務的掌握？","answer":"D","options":[{"key":"A","text":"疲勞。"},{"key":"B","text":"壓力。"},{"key":"C","text":"工作量過多。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-015","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"操作遙控無人機前藉由下列哪些有效的工作量管理，以確保飛行任務安全執行？","answer":"D","options":[{"key":"A","text":"計畫。"},{"key":"B","text":"整理。"},{"key":"C","text":"排序工作任務。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-016","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"疲勞可分為下列哪幾種？","answer":"D","options":[{"key":"A","text":"生理性疲勞。"},{"key":"B","text":"心理性疲勞。"},{"key":"C","text":"急性與慢性疲勞。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-017","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"疲勞會導致下列哪幾種症狀，影響遙控無人機操作人的判斷力？","answer":"D","options":[{"key":"A","text":"注意力渙散。"},{"key":"B","text":"專注力下降。"},{"key":"C","text":"協調性及溝通性降低。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-018","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"急性疲勞通常是下列哪一種？","answer":"A","options":[{"key":"A","text":"短期。"},{"key":"B","text":"長期。"},{"key":"C","text":"有時長期有時短期。"},{"key":"D","text":"以上皆非。"}]},{"id":"chapter-04-019","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人若忽略或未及時改善急性疲勞，則會進一步造成下列哪種狀況？","answer":"B","options":[{"key":"A","text":"過度疲勞。"},{"key":"B","text":"慢性疲勞。"},{"key":"C","text":"中度疲勞。"},{"key":"D","text":"低度疲勞。"}]},{"id":"chapter-04-020","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"慢性疲勞可能出現的症狀包括下列哪種狀況？","answer":"D","options":[{"key":"A","text":"虛弱、強烈的疲倦、倦怠感。"},{"key":"B","text":"心悸、呼吸不順、頭痛。"},{"key":"C","text":"其他身體的不適及沮喪與焦慮。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-021","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"急性疲勞中，有種特殊情況稱之為下列哪種疲勞，在操作方面的影響主要有時機掌握混亂及視域過度聚焦？","answer":"C","options":[{"key":"A","text":"社會性疲勞。"},{"key":"B","text":"經濟性疲勞。"},{"key":"C","text":"技能疲勞。"},{"key":"D","text":"教育性疲勞。"}]},{"id":"chapter-04-022","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪種狀況是身體組織水分不足的情況？","answer":"A","options":[{"key":"A","text":"脫水。"},{"key":"B","text":"失眠。"},{"key":"C","text":"低血糖。"},{"key":"D","text":"缺氧。"}]},{"id":"chapter-04-023","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪種狀況可能會造成水分補充不及導致脫水？","answer":"D","options":[{"key":"A","text":"長時間處於高溫、高溼度、高海拔環境。"},{"key":"B","text":"心理壓力。"},{"key":"C","text":"飲用過多刺激性飲料。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-024","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"脫水最先出現的症狀是下列哪種狀況，將導致遙控無人機操作人的生理及心智表現下滑？","answer":"D","options":[{"key":"A","text":"口乾。"},{"key":"B","text":"舌燥。"},{"key":"C","text":"較強的疲勞感。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-025","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"為避免脫水，遙控無人機操作人應隨時掌握己身之生理狀況，並採取下列哪個動作？","answer":"B","options":[{"key":"A","text":"隨時閱讀。"},{"key":"B","text":"適時補充水分。"},{"key":"C","text":"適時上廁所。"},{"key":"D","text":"隨時聽音樂。"}]},{"id":"chapter-04-026","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪種狀況是指身體無法對體溫進行控制？","answer":"C","options":[{"key":"A","text":"缺氧。"},{"key":"B","text":"低血糖。"},{"key":"C","text":"熱中暑。"},{"key":"D","text":"失眠。"}]},{"id":"chapter-04-027","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"熱中暑原因是下列哪種狀況？","answer":"A","options":[{"key":"A","text":"身體的熱無法排出。"},{"key":"B","text":"飲酒過量。"},{"key":"C","text":"失眠。"},{"key":"D","text":"低血糖。"}]},{"id":"chapter-04-028","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"避免熱中暑的方法是採取下列哪個動作？","answer":"C","options":[{"key":"A","text":"勿飲酒過量。"},{"key":"B","text":"充分的睡眠。"},{"key":"C","text":"規律攝取足量水份。"},{"key":"D","text":"按時用餐。"}]},{"id":"chapter-04-029","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"若遙控無人機操作人服用下列哪種藥物，可能會產生暈眩或是感知功能不全的情況？","answer":"D","options":[{"key":"A","text":"成藥。"},{"key":"B","text":"抗組織胺。"},{"key":"C","text":"解除充血劑。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-030","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"酒精可能對下列哪種狀況造成影響？","answer":"D","options":[{"key":"A","text":"影響操作及判斷、較難掌握周邊環境的變化。"},{"key":"B","text":"身體協調性變差、視界窄化。"},{"key":"C","text":"降低邏輯能力及注意力低落。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-031","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"在下列哪個時機，遙控無人機操作人應對遙控無人機進行起飛前檢查？","answer":"A","options":[{"key":"A","text":"每次操作前。"},{"key":"B","text":"遙控無人機有明顯異狀時。"},{"key":"C","text":"天氣變壞時。"},{"key":"D","text":"操作人感覺不對時。"}]},{"id":"chapter-04-032","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機起飛前檢查中發現任何異常狀況，應採取下列哪個動作？","answer":"B","options":[{"key":"A","text":"暫時忽略異常狀況，繼續操作。"},{"key":"B","text":"應立即修正以確保安全。"},{"key":"C","text":"記錄異常狀況就好，不必大驚小怪，繼續操作。"},{"key":"D","text":"任務重要就繼續操作，任務不重要就暫停操作。"}]},{"id":"chapter-04-033","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"緊急落地可依類型區分為下列哪幾種？","answer":"D","options":[{"key":"A","text":"迫降。"},{"key":"B","text":"預防性緊急著陸。"},{"key":"C","text":"水上迫降。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-034","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"當面對緊急狀況時，若平時沒有熟悉緊急應變之處置程序，操作人可能會陷入下列哪種情境中？","answer":"A","options":[{"key":"A","text":"遙控無人機即將墜地。"},{"key":"B","text":"遙控無人機不會出事。"},{"key":"C","text":"遙控無人機的緊急狀況會自動消失。"},{"key":"D","text":"遙控無人機會自動處理緊急狀況。"}]},{"id":"chapter-04-035","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"當遙控無人機發生異常或緊急事件時，應先穩定操作，掌握無人機位置及高度，再採取下列哪個動作？","answer":"C","options":[{"key":"A","text":"通報有關機關。"},{"key":"B","text":"依檢查表，啟動或關閉相關裝備。"},{"key":"C","text":"尋找最佳的緊急落地處。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-036","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"飛行決策是基於經驗的累積及判斷集合而成，著重於下列哪種決策方案？","answer":"D","options":[{"key":"A","text":"學習決策方案。"},{"key":"B","text":"評估決策方案。"},{"key":"C","text":"選擇決策方案。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-037","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"風險管理的目的是為能夠主動辨識與飛航安全有關的危害因子，並透過下列哪個手段降低到可接受之程度？","answer":"D","options":[{"key":"A","text":"迴避。"},{"key":"B","text":"減少。"},{"key":"C","text":"隔離。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-038","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"飛行決策的過程中應掌握下列哪個基本原則？","answer":"D","options":[{"key":"A","text":"不接受非相關的風險、將風險設定在合適的層級。"},{"key":"B","text":"在獲益超過危害時接受風險。"},{"key":"C","text":"將風險管理整合在飛行各階段的計劃過程中。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-039","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"操作人執行遙控無人機操作時，下列哪種心態干擾會降低飛行決策的品質？","answer":"A","options":[{"key":"A","text":"反威權、衝動及僥倖。"},{"key":"B","text":"衝動、僥倖及服從。"},{"key":"C","text":"英雄主義及積極順應。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-040","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人降低風險的方法，包括下列哪種？","answer":"D","options":[{"key":"A","text":"辨識己身風險。"},{"key":"B","text":"預知己身風險。"},{"key":"C","text":"覺察己身風險。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-041","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下列哪個因素與飛航安全密切相關，已成為維修部門及飛航管理部門關切的焦點？","answer":"B","options":[{"key":"A","text":"政治因素。"},{"key":"B","text":"人為因素。"},{"key":"C","text":"社會因素。"},{"key":"D","text":"經濟因素。"}]},{"id":"chapter-04-042","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"自動決策模式基本上是一種反射性的模式，其形成的重要基礎是下列哪種方式？","answer":"A","options":[{"key":"A","text":"大量的訓練及經驗。"},{"key":"B","text":"擴大參與人數。"},{"key":"C","text":"正確的政治指導。"},{"key":"D","text":"高深的哲學思想。"}]},{"id":"chapter-04-043","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"自動決策模式常用於下列哪種情況？","answer":"D","options":[{"key":"A","text":"緊急情況。"},{"key":"B","text":"無法預作分析的情況。"},{"key":"C","text":"無法沙盤推演的情況。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-044","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"呼吸頻率過快以致血液裡二氧化碳的濃度過低所導致的結果，稱之為下列哪種狀況？","answer":"A","options":[{"key":"A","text":"過度換氣。"},{"key":"B","text":"壓力。"},{"key":"C","text":"疲勞。"},{"key":"D","text":"熱中暑。"}]},{"id":"chapter-04-045","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"壓力基本上可以分做下列哪兩大類？","answer":"A","options":[{"key":"A","text":"急性及慢性。"},{"key":"B","text":"經濟性及社會性。"},{"key":"C","text":"個人性及團體性。"},{"key":"D","text":"有害性及無害性。"}]},{"id":"chapter-04-046","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"急性的壓力包括下列哪種狀況，可能觸發抵抗或逃避的反應？","answer":"B","options":[{"key":"A","text":"可能潛在的威脅。"},{"key":"B","text":"立即的威脅（如危險、緊急情境）。"},{"key":"C","text":"想像的威脅。"},{"key":"D","text":"未來的威脅。"}]},{"id":"chapter-04-047","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"疲勞是一種身心耗弱狀態，乃是長期處在高度壓力之下的下列哪種反應？","answer":"B","options":[{"key":"A","text":"直覺反應。"},{"key":"B","text":"生理或心理反應。"},{"key":"C","text":"情緒反應。"},{"key":"D","text":"鬱悶反應。"}]},{"id":"chapter-04-048","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"操作人於操作前，可利用下列哪方法的自我檢測方法，來瞭解己身的身心狀態？","answer":"A","options":[{"key":"A","text":"IMSAFE。"},{"key":"B","text":"簡易ABC。"},{"key":"C","text":"PAVE。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-049","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"操作遙控無人機時若發生非預期的緊急情況時，操作人首要的任務為下列哪種作為？","answer":"C","options":[{"key":"A","text":"堅持到底、繼續執行任務。"},{"key":"B","text":"暫停執行任務、適當休息。"},{"key":"C","text":"應先確保己身及周邊環境及其他人員的安全。"},{"key":"D","text":"應先確保遙控無人機的安全。"}]},{"id":"chapter-04-050","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"若製造商沒有提供起飛前檢查表或操作自製遙控無人機，則遙控無人機操作人應採取下列哪個動作？","answer":"B","options":[{"key":"A","text":"省略起飛前檢查。"},{"key":"B","text":"應自行設計檢查表以確保能夠安全操作。"},{"key":"C","text":"聯絡製造商提供起飛前檢查表，同時繼續操作。"},{"key":"D","text":"借用其他型式的遙控無人機起飛前檢查表。"}]},{"id":"chapter-04-051","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"遙控無人機操作人在飛航操作環境下，以系統性的評估風險及處理壓力的方法，來達成最適宜的結果，稱之為何種方法？","answer":"C","options":[{"key":"A","text":"腦力激盪。"},{"key":"B","text":"人因工程。"},{"key":"C","text":"飛行決策。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-052","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"某種狀況、物體或活動，其可能造成人員傷亡、裝備損壞或降低運作效能，稱之為下列哪種狀況？","answer":"B","options":[{"key":"A","text":"風險。"},{"key":"B","text":"危害。"},{"key":"C","text":"災難。"},{"key":"D","text":"事故。"}]},{"id":"chapter-04-053","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"危害所可能造成的後果，稱之為下列哪種狀況？","answer":"A","options":[{"key":"A","text":"風險。"},{"key":"B","text":"災難。"},{"key":"C","text":"意外。"},{"key":"D","text":"事故。"}]},{"id":"chapter-04-054","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"在有限的時間壓力下，未經充分蒐集、分析利弊、僅憑直覺或經驗即執行的過程稱為下列哪種方式？","answer":"C","options":[{"key":"A","text":"工程決斷。"},{"key":"B","text":"反射抉擇。"},{"key":"C","text":"自動決策。"},{"key":"D","text":"兩難情境。"}]},{"id":"chapter-04-055","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機正在執行任務時，發現天氣明顯變化：能見度變差、相對濕度變高、陣風風速變大，請問操作人應採取下列哪一項動作？","answer":"A","options":[{"key":"A","text":"當機立斷，立即將無人機返場降落，以免危及無人機性能和飛行安全。"},{"key":"B","text":"視無人機團隊組員人數而定，如果人數夠多就繼續執行任務，不用擔心天氣影響到無人機性能和飛行安全。"},{"key":"C","text":"視無人機機型而定，如果無人機出廠性能優異就繼續執行任務，不必在乎天氣影響到無人機性能和飛行安全。"},{"key":"D","text":"以上皆是。"}]},{"id":"chapter-04-056","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"在作飛行規劃或操作無人機時，操作人手上有多項性能資料，每項都言之成理，但又不盡相同，甚至互相矛盾，操作人應優先使用下列哪一項？","answer":"C","options":[{"key":"A","text":"航空教科書計算得出的性能資料。"},{"key":"B","text":"之前操作人提供的經驗及建議。"},{"key":"C","text":"無人機製造商提供的性能資料。"},{"key":"D","text":"類似系統提供的預估性能資料。"}]},{"id":"chapter-04-057","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"請問在下列哪一種情況下，操作人可以不必執行無人機起飛前檢查？","answer":"C","options":[{"key":"A","text":"前一次飛行已作過起飛前檢查，如果緊接著執行下一次飛行，就不必執行起飛前檢查。"},{"key":"B","text":"當天第一次飛行已作過起飛前檢查，之後當天的所有飛行就都不必執行起飛前檢查。"},{"key":"C","text":"每次飛行前都必須執行起飛前檢查，沒有任何情況可以免除。"},{"key":"D","text":"視飛行任務而定，如果任務簡單且飛行時間短，操作人判斷起飛前檢查屬多餘，就不必執行起飛前檢查。"}]},{"id":"chapter-04-058","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"下午3點無人機飛行時天氣愈來愈壞，氣象預報說下午有雷雨，但此時無人機正在執行一項任務，至少需要到下午5點才能結束返場，請問操作人應採取下列哪一項飛行決策？","answer":"A","options":[{"key":"A","text":"在惡劣天氣下飛行，會增加飛航安全的風險，應避免在雷雨期間下執行任務。"},{"key":"B","text":"無人機狀況良好，雖然氣象預報說有雷雨，但不一定會發生，就算發生也不一定會碰上，所以可繼續執行任務。"},{"key":"C","text":"以前也不是沒碰過雷雨，只要無人機狀況良好、操作人能力優秀，克服天氣因素沒問題，所以可繼續執行任務。"},{"key":"D","text":"因為此次任務非常重要，中途放棄會損失許多金錢和時間，所以可繼續執行任務，等碰到雷雨再說。"}]},{"id":"chapter-04-059","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機已連續飛行一段長時間，操作人全程專心操作，但因前一夜休息不足略顯疲態，操作團隊其他組員感覺該操作人反應變慢、注意力渙散、專注力下降、協調性及溝通性降低等，請問操作團隊應採取下列哪一項動作？","answer":"C","options":[{"key":"A","text":"因為該操作人比較熟悉任務需求，還是由他繼續操作，其他組員多跟他講話，鼓舞精神，硬撐下去。"},{"key":"B","text":"詢問該操作人會不會疲累、可否繼續操作；如果不會疲累就繼續操作，如果會疲累再說。"},{"key":"C","text":"基於飛航安全的考量，應儘快返場落地；由其他合適的操作人繼續執行任務。"},{"key":"D","text":"請該操作人將無人機至於自主飛行模式，然後閉目養神，直到精神恢復再繼續操作。"}]},{"id":"chapter-04-060","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機準備下午3點以後執行任務，為了避免視線干擾應慎選控制站方位，請問操作人應選擇下列哪一種操作方位？","answer":"B","options":[{"key":"A","text":"操作方位面向西方。"},{"key":"B","text":"操作方位面向東方。"},{"key":"C","text":"任一種操作方位都可以，不必擔心視線干擾。"},{"key":"D","text":"操作方位應面對操作範圍內任何反光物體。"}]},{"id":"chapter-04-061","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機正在飛行時，操作團隊臨時要求操作人執行原先飛行計畫沒有安排的科目，請問操作人應如何處理？","answer":"D","options":[{"key":"A","text":"對原先飛行計畫沒有安排的科目，應一律拒絕執行。"},{"key":"B","text":"既然是操作團隊要求的科目，就應配合執行。"},{"key":"C","text":"依科目重要性而定，重要的話就不顧一切去執行，不重要的話就不執行。"},{"key":"D","text":"快速評估可行性，包括無人機性能、個人能力及其他限制等，再決定是否執行。"}]},{"id":"chapter-04-062","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機計畫執行視距內任務，操作人預估有一段路徑無法保持目視無人機，請問操作人應如何處置？","answer":"D","options":[{"key":"A","text":"使用望遠鏡來執行該段路徑無人機飛航。"},{"key":"B","text":"只要操作人技術夠好，就不必在意該段路徑。"},{"key":"C","text":"只要知道該段路徑沒有障礙、沒有其他無人機，就可以繼續執行任務。"},{"key":"D","text":"改變飛行路徑，以保持目視無人機。"}]},{"id":"chapter-04-063","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"最大起飛重量二公斤以上且裝置導航裝置之遙控無人機於執行任務途中，因天氣變壞、能見度變差，最後導致無人機失控墜毀於空曠無人區域，未造成人員死傷或財物毀損，請問操作人對該無人機墜毀事件應有下列哪一項認知？","answer":"D","options":[{"key":"A","text":"雖然未造成人員死傷或財物毀損，仍應將無人機殘骸撿拾乾淨再回程，而且不要跟任何單位通報，以免造成自己困擾。"},{"key":"B","text":"應在墜毀現場檢討失事原因，檢視殘骸狀況，勿破壞現場，通報當地警察局處理。"},{"key":"C","text":"無人機因天氣等不可抗力因素而失控墜毀，只要未造成人員死傷或財物毀損，就不必做任何善後處理或通報任何單位。"},{"key":"D","text":"事件發生後，無人機所有人或操作人應將事件經過通報民航局。"}]},{"id":"chapter-04-064","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機團隊正在作任務前簡報，有人聞到操作人身上有明顯的酒味，便提出質疑，操作人表示他剛剛只是喝了一小杯高粱酒，應無大礙，請問無人機團隊對該操作人的說法應有下列哪一項認知？","answer":"A","options":[{"key":"A","text":"法令規定有其容忍值，但基於飛航安全的考量，在未經酒測前，應禁止操作人執行飛航活動。"},{"key":"B","text":"應以任務執行為優先，還是讓該操作人從事飛航活動，只要無人機團隊多加留意便是。"},{"key":"C","text":"適當的飲酒不但無害且有助視力及反應，所以不必當回事，仍依原計畫讓該操作人從事飛航活動。"},{"key":"D","text":"依該操作人的現場狀況而定，如果該操作人看起來還好就讓他從事飛航活動，如果該操作人看起來醉醺醺就禁止他從事飛航活動。"}]},{"id":"chapter-04-065","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機結束當天任務準備返場，又接到任務指示：「立即至另一指定地點執行下一項任務。」請問操作人對該任務指示應有下列哪一項認知？","answer":"C","options":[{"key":"A","text":"既然尚未返場落地，就接受該任務指示，以滿足任務需求為優先考量。"},{"key":"B","text":"既然當天任務已經結束，就不必理會該任務指示，趕緊返場，早點收工休息。"},{"key":"C","text":"考量下一項任務的油量需求、人員負荷、空域、天氣及無人機狀況等，如果都沒有安全顧慮，不會對任何人或物造成危險，就接受該任務指示，否則應拒絕該任務指示，先返場整備後再執行下一項任務。"},{"key":"D","text":"應依下一項任務的重要性而定，如果下一項任務很重要，就接受該任務指示，否則就拒絕該任務指示。"}]},{"id":"chapter-04-066","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機在地面檢整，準備從事飛航活動，無人機團隊有人主張：「目視檢查無人機外觀完整，應該就沒問題，符合安全飛航條件，可以從事飛航活動。」請問操作人對該主張應有下列哪一項認知？","answer":"B","options":[{"key":"A","text":"該主張正確，只要外觀完整，就可以從事飛航活動。"},{"key":"B","text":"該主張不正確，除了外觀完整，安全飛航條件還包含：機構及動力系統穩固、飛航註冊號碼依規定標示可辨、遙控設備與無人機間之通信及控制鏈路運作正常、燃油或電力之供應符合飛航之需求等。"},{"key":"C","text":"如果提出該主張的人經驗豐富，見多識廣，代表該主張正確，否則該主張不正確。"},{"key":"D","text":"應依當時現場的天候狀況而定，如果天候狀況適於從事飛航活動，代表該主張正確，否則該主張不正確。"}]},{"id":"chapter-04-067","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機團隊正在作任務前簡報，氣象預報指出在任務飛行路徑無人機將進入雷雨區，無人機很可能碰到強勁的上升氣流及下降氣流，請問操作人對該氣象預報應有下列哪一項認知？","answer":"D","options":[{"key":"A","text":"無人機在雷雨區飛行是很稀鬆平常的事，不必放在心上。"},{"key":"B","text":"無人機先起飛再說，說不定雷雨區沒有氣象預報說的強勁氣流，或者根本沒有雷雨區。"},{"key":"C","text":"應依當時任務的重要性而定，如果任務重要就繼續從事飛航活動，否則就取消。"},{"key":"D","text":"因為操作區域氣象條件惡劣，應審慎評估從事飛航活動的風險，必要時應建議無人機團隊延期執行任務。"}]},{"id":"chapter-04-068","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機因操作人操作不當導致失控墜毀於外海，通報民航局備查後，操作人情緒激動，久久不能平復，要求無人機團隊立即讓他操作另一架同型無人機來完成沒有作完的任務，請問無人機團隊對該要求應有下列哪一項認知？","answer":"A","options":[{"key":"A","text":"操作人情緒不穩定，宜暫停從事無人機之飛航活動，所以應拒絕該要求。"},{"key":"B","text":"「操作不當」的不良紀錄會導致操作人聲譽受損，讓操作人繼續執行無人機任務有助他扳回面子，所以應同意該要求。"},{"key":"C","text":"應視當時的天氣狀況而定，如果天氣好就同意該要求，否則就拒絕該要求。"},{"key":"D","text":"應視另一架同型無人機的機務狀況而定，如果機務狀況好就同意該要求，否則就拒絕該要求。"}]},{"id":"chapter-04-069","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機團隊在作任務前簡報，針對此次任務可能的緊急狀況及其處置，團隊中有人主張到時碰到再看事辦事，隨機應變即可，不用管什麼程序，請問操作人對該主張應有下列哪一項認知？","answer":"D","options":[{"key":"A","text":"無人機操作人的經驗最重要，只要操作人自認有把握，就可以同意該主張。"},{"key":"B","text":"應依無人機團隊的共識而定，如果有共識就同意該主張，否則就不同意該主張。"},{"key":"C","text":"應依無人機任務的重要性而定，如果任務重要就同意該主張，否則就不同意該主張。"},{"key":"D","text":"操作人應完全熟悉並遵守無人機飛行手冊/操作人操作手冊所規定的程序作緊急處置，不可以同意該主張。"}]},{"id":"chapter-04-070","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"操作人正在作無人機飛行前檢查，發現螺槳上有刮傷刻痕，請問操作人對該刻痕應有下列哪一項認知？","answer":"D","options":[{"key":"A","text":"螺槳上有刮傷刻痕很平常，知道就好，不必大驚小怪。"},{"key":"B","text":"螺槳上有刮傷刻痕極為危險，應立即更換螺槳才可以啟動引擎。"},{"key":"C","text":"先執行無人機任務要緊，任務完成後再由無人機團隊共同研商該刻痕之對策。"},{"key":"D","text":"操作人應針對該刻痕依據廠商手冊或相關資料作風險評估，判斷該刻痕所產生風險的嚴重性及可能性是否可以接受。"}]},{"id":"chapter-04-071","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機正在機場的南方空域飛行時，航管通知有飛機準備從06跑道進場，要求無人機必須避開進場航線，請問操作人應採取下列哪一項動作？","answer":"A","options":[{"key":"A","text":"避開目前飛行空域的西方和北方。"},{"key":"B","text":"避開目前飛行空域的東方和北方。"},{"key":"C","text":"避開目前飛行空域的西方和南方。"},{"key":"D","text":"避開目前飛行空域的東方和南方。"}]},{"id":"chapter-04-072","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機在溫暖天氣低空飛行時常會有對流的氣流造成上下起伏的亂流空氣，請問操作人應採取下列哪一項動作來避免這些亂流情形？","answer":"A","options":[{"key":"A","text":"維持穩定速度飛行；視情況爬升高度。"},{"key":"B","text":"增加空速，衝過亂流區域。"},{"key":"C","text":"展現優異的無人機操作技巧，不必在乎亂流空氣。"},{"key":"D","text":"降低飛行高度，消除亂流空氣的影響。"}]},{"id":"chapter-04-073","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機正在執行任務，操作人發現動力系統警示紅燈會不定時亮起來一段時間，然後又熄滅，且一再重現，請問操作人對該現象應有下列哪一項認知？","answer":"B","options":[{"key":"A","text":"只要無人機還能正常飛行，不必在意該現象，繼續執行任務。"},{"key":"B","text":"該現象表示動力系統可能有緊急情況會發生，操作人應立即將無人機返航落地。"},{"key":"C","text":"無人機團隊應針對該現象共同研商出一個因應措施，尊重大家的意見，不是操作人或任何其他個人就可以決定。"},{"key":"D","text":"應視警示紅燈亮起來的時間長短及頻率而定，如果時間長、頻率高就注意該現象，否則就忽略該現象。"}]},{"id":"chapter-04-074","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人飛機頂風起飛離地後引擎失效，請問操作人對該狀況應有下列哪一項認知？","answer":"A","options":[{"key":"A","text":"立即確立適當的無人飛機飄降姿態，並直線往前或稍微偏離起飛路徑作降落。"},{"key":"B","text":"立即以大角度轉彎將無人飛機轉回本場作降落。"},{"key":"C","text":"立即反映無人飛機團隊，請大家集思廣益，提出對策。"},{"key":"D","text":"立即查閱無人飛機飛行手冊/操作人操作手冊所規定的程序，再作緊急處置。"}]},{"id":"chapter-04-075","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機正在執行任務，下列狀況幾乎同時發生：GPS信號失效、天氣變壞及圖傳遭受干擾等，請問操作人對該等狀況應有下列哪一項認知？","answer":"B","options":[{"key":"A","text":"應以達成任務為優先考慮，暫時忽略該等狀況。"},{"key":"B","text":"對該等狀況無法預作分析及沙盤推演，操作人應憑經驗果斷作成自動決策。"},{"key":"C","text":"應與無人機團隊共同研商該等狀況之對策，從容找出最佳方案。"},{"key":"D","text":"應仔細查閱無人機飛行手冊/操作人操作手冊所規定的程序，再依其中規定的處置措施逐步執行。"}]},{"id":"chapter-04-076","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"某無人飛機飄降比為10比1，正在距離機場約2公里、高度1,000英呎執行任務，此時為靜風，引擎忽然故障熄火，請問操作人應採取下列哪一項動作？","answer":"B","options":[{"key":"A","text":"不管無人飛機高度可否提供足夠飄降距離，因為無人機太重要，立即不顧一切執行飄降返場。"},{"key":"B","text":"判斷無人飛機高度可提供足夠飄降距離，立即執行飄降返場。"},{"key":"C","text":"判斷無人飛機高度無法提供足夠飄降距離，立即執行場外迫降。"},{"key":"D","text":"雖然無人飛機高度無法提供足夠飄降距離，因為操作人信心滿滿、技藝超群，仍執行飄降返場。"}]},{"id":"chapter-04-077","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人飛機正在執行任務，操作人發現動力系統警示紅燈亮起，燈號顯示燃油或電量已不足以安全返場落地，飄降距離也顯然太遠，請問操作人對該緊急狀況應有下列哪一項認知？","answer":"C","options":[{"key":"A","text":"盡量堅持下去，往本場飛，能飛多久是多久。"},{"key":"B","text":"盡量延伸飄降距離，不必考慮最低空速，最好能到達「理想的」落地區域。"},{"key":"C","text":"在操作人仍可繼續操作無人機時，儘快執行「預防性緊急著陸」。"},{"key":"D","text":"反正已不可能安全返場落地，放棄任何努力，聽天由命。"}]},{"id":"chapter-04-078","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"A、B兩架無人機在同一區域執行任務，A機操作人接到一通重要電話，於是商請B機操作人暫時同時幫忙操作A機，請問操作人對該要求應有下列哪一項認知？","answer":"A","options":[{"key":"A","text":"拒絕該要求。"},{"key":"B","text":"視當時的天氣狀況而定，如果天氣狀況良好就同意該要求，否則就拒絕該要求。"},{"key":"C","text":"視該電話的重要性而定，如果該電話真的很重要就同意該要求，否則就拒絕該要求。"},{"key":"D","text":"視A機的油量而定，如果油量充足就同意該要求，否則就拒絕該要求。"}]},{"id":"chapter-04-079","chapterId":"chapter-04","chapterName":"第四章緊急處置與飛行決策","question":"無人機團隊受某媒體委託執行空拍任務，執行任務過程中委託單位要求無人機飛出核准區域以取得更好的畫面，無人機團隊其他成員認為該要求合理，應予執行，但是操作人認為該要求有安全疑慮，應予拒絕，請問操作人對此情形應有下列哪一項認知？","answer":"C","options":[{"key":"A","text":"聽從無人機團隊領隊的指示，領隊說執行就執行，到時有問題由領隊負責。"},{"key":"B","text":"聽從無人機團隊大多數人的意見，到時有問題大家一起負責。"},{"key":"C","text":"無人機於飛航活動期間，操作人對無人機之處置有最後決定權。"},{"key":"D","text":"如果委託單位願意負責就執行該要求，否則就拒絕該要求。"}]}]}]};
